[Theorem of arXiv:2608.10415, 'Continuous random variables'] We have an isomorphism $L^2(\mathbb R)_{per}\simeq l^2(\mathbb Z)$, as follows:
\begin{enumerate}
\item Associated to $f\in L^2(\mathbb R)_{per}$ are its Fourier coefficients, given by:
$$\widehat{f}(n)=\frac{1}{2\pi}\int_{-\pi}^\pi f(t)e^{int}dt$$

\item Associated to $g\in l^2(\mathbb Z)$ is the series $S_g(t)=\sum_{n\in\mathbb Z}g(n)e^{-int}$.
\end{enumerate}

[Thm 14 of arXiv:2506.20146, 'Parabolic Anderson Model in the Hyperbolic Space. Part I: Annealed Asymptotics'] One has 
\begin{equation}
\underset{t\rightarrow\infty}{\overline{\lim}}\frac{1}{\beta(t)}\log\big(e^{-H(t)}\langle u(t,0)\rangle\big)\leqslant\underset{R\rightarrow\infty}{\underline{\lim}}(-\chi_{R}),
\end{equation}
where $\chi_{R}$ is defined by (\ref{eq:ChiR}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] For $0 \leq p, \, q \leq \infty$ and $s, \, \beta \in \mathbb{R}$, the Besov space with logarithmic scale is defined by 
\begin{equation}
 B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2) :  = \Big\{ f \in \mathcal{S}'(\mathbb{R}^2)~:~ \,  \sum_{j \in \mathbb{N}} j ^{-\beta q} 2^{jsq} \Vert \Delta_j f\Vert_p^q < \infty\big\}
\end{equation}
and we define a norm on $B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)$ by
$$
\Vert f \Vert_{B^{s}_{p,q,\vert \log \vert^{\beta}}(\mathbb{R}^2)} = \left( \sum_{j \in \mathbb{N}} j ^{-\beta q} 2^{jsq} \Vert \Delta_j f \Vert_p^q \right)^{1/q}.
$$

[Proposition 25 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $(\SC, \varrho)$ be a non-empty quasi-metric space.
 Let $\mu$ be a Borel probability measure on $\SC$, and let $s\in (0,\infty)$ and $t\in \RR$.
 Assume that there exist $r_0>0$ and $c_0>0$ such that
 \begin{equation*}
     \om{\mu} \bigl( \ball(x,r)\bigr) 
    \le \exp\biggl( - c_0 \cdot \Bigl( \frac{1}{r}\Bigr)^{s} \cdot \Bigl( \log_2 \Bigl(\frac{1}{r}\Bigr)\Bigr)^{t}\biggr)
    \quad \text{for all $x\in \SC$ and all $r\in (0,r_0)$.}
 \end{equation*}
 Then for every $\eps\in (0,r_0)$ there exists an $\eps$-separated subset $P_{\eps}$ with
 \begin{equation*}
   \num P_{\eps}
   \geq \exp
        \biggl(
          c_0
          \cdot \left(\frac{1}{\eps}\right)^s
          \cdot \left(\log_2 \left(\frac{1}{\eps}\right)\right)^{t}
        \biggr).
 \end{equation*}

[Lem LLNlr of arXiv:2608.13084, '\bf Branching random walk in random environment'] For any $x\in{\mathbb Z}^d$ and for ${\bf P}_p$-a.s. environment $\omega$, 
\begin{equation*}
\frac1n \sum_{1\le j\le n} r_j \xrightarrow[n\to\infty]{ \widehat{{\mathbb P}}^\omega_x-a.s. } \frac{p\sigma^2_\circ + (1-p)\sigma^2_\bullet}{2}.
\end{equation*}
The similar result holds for $(l_j)_{j\ge1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Assume that the conditions \textbf{(A)} and \textbf{(B)} hold with $r \in (1/2, 1)$. Let $\beta_N$ be a sequence of inverse temperatures satisfying $\beta_N N^{H/2} \to \beta \in [0, \infty)$ as $N \to \infty$. Then there exists a positive constant $C$ such that for any $N \ge 1$ and $k \ge 1$,
\begin{equation} 
\| \rho_k \|_{\mathcal{L}_K^k}^2 \le \frac{C^k \Gamma^k(H)}{\Gamma(kH + 1)}
\end{equation}
and
\begin{equation} 
k! \| \psi_N^k \|_{\mathcal{L}_K^k}^2 \le \frac{C^k \Gamma^k(H)}{\Gamma(kH + 1)},
\end{equation}
where
\begin{equation*}
\rho_k(\mathbf{t}, \mathbf{x}) := \prod_{i=1}^k \rho(t_i - t_{i-1}, x_i - x_{i-1}), \quad (\mathbf{t}, \mathbf{x}) \in \Delta_k(1) \times \mathbb{R}^k.
\end{equation*}
In particular, since $H > 0$, the bounds in \eqref{eq:rho_k_bound} and \eqref{eq:psi_k_bound} guarantee the summability of the following series:
\begin{equation} 
\sum_{k=1}^\infty (\sqrt{2}\beta)^{2k} \| \rho_k \|_{\mathcal{L}_K^k}^2 < \infty,
\end{equation}
and
\begin{equation} 
\lim_{l \to \infty} \limsup_{N \to \infty} \sum_{k \ge l} (\sqrt{2}\beta_N N^{H/2})^{2k} k! \| \psi_N^k \|_{\mathcal{L}_K^k}^2 = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:hp of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] Let $(P_t)_{t \in \mathbb T}$ be a transition probability function on $S$.
    If $(P_t)_{t \in
    \mathbb T}$ is increasing and there exists a positive $u \in \mathbb T$ such that $P_u$
    satisfies the MMC, then $(P_t)_{t \in \mathbb T}$ is globally stable on $\mathscr{P}(S)$
    under $\beta$ and convergence to the unique fixed point $\phi^*$ is
    exponential: 

    \begin{equation}
        \beta(\phi P_t, \phi^*) \leq C e^{-\alpha t}
        \quad \text{for all $\phi \in \mathscr{P}(S)$ and $t \in \mathbb T$},
    \end{equation}

    where $C \coloneq 2/(1-\epsilon)$ and $\alpha \coloneq \ln(1/(1-\epsilon))/u$.
    Moreover, when $\mathbb T = \mathbb{Z}_+$, each $P$-Markov process is monotone ergodic:

    \begin{equation*}
        \mathbb P
        \left\{
             \lim_{n \to \infty}
             \frac{1}{n} \sum_{t=0}^{n-1} h(X_t) = \phi^*(h)
        \right\} = 1
        \quad \text{for all } h \in ibS.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

