body:
[Lemma lem-prelim-gap-est-time-after-2R of arXiv:2607.22324, 'The conclave process'] {}
    Suppose that $\alpha > 1$ and
    \begin{equation}{}
        M \geq (\log n)^{100},\quad \delta \geq M^{-\frac{1}{2}}(\log n)^3, \quad (1-\delta)M \geq (\log n)^{12}, \quad 1-\delta > n^{-\frac{1}{\alpha+1}} \,.
    \end{equation}
    Define $\mathfrak F(M,\delta)$ to be the collection of $(M',\delta')$ such that
    \begin{align}
        &(M')^{-\frac{1}{2}}(\log n)^3 \leq \delta', \quad \left( 1-(\log n)^{-1} \right) M \leq M' \,;   \\
        &\min\left\{ \left( 1-(\log n)^{-3} \right) M(1-\delta), (\log n)^{20} \right\} \leq M'(1-\delta') \,;   \\
        & \left( 1-\frac{\delta}{\sqrt{\log n}} \right) (1-\delta)^\alpha \leq (1-\delta') \leq \left( 1+\frac{\delta}{\sqrt{\log n}} \right) (1-\delta)^{\alpha} \,.  
    \end{align}
    Given any $(\mathbf X_1,\ldots,\mathbf X_n) \in \overline{\Omega}_n(M,\delta)$, we have 
    \begin{equation*}
        \mathbb P^\alpha_{n,\mathbf X}\left( (\mathbf X_1',\ldots,\mathbf X_n') \in \cup_{ (M',\delta') \in \mathfrak F(M,\delta) } \overline{\Omega}_n(M',\delta'), \mathcal L(\mathbf X')=\mathcal L(\mathbf X) \right) \geq 1-\frac{1}{\log n} \,.
    \end{equation*}

