[Lem lemma:master-cancellation of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Consider a loop $\ell=\mathbf{e} \, \pi$, where $\mathbf{e}$ is a copy of the lattice edge $e$, and a non-zero plaquette assignment $K$ such that $(\ell,K)$ is balanced. Then
\begin{align}
	\sum_{p\in\mathcal{P}_{\mathbb{Z}^d}(e^{-1},K)}&\sum_{N\in \mathcal{N}\mathcal{P}\mathcal{M}^{\text{bad}}(\ell\ominus_{\mathbf{e}} p , K\setminus\{p\})}\upbeta^{\area(N)}w_{\infty}(N) \notag\\&= \sum_{q\in\mathcal{P}_{\mathbb{Z}^d}(e,K)}\sum_{N\in \mathcal{N}\mathcal{P}\mathcal{M}^{\text{bad}}(\ell\oplus_{\mathbf{e}} q , K\setminus\{q\})}\upbeta^{\area(N)}w_{\infty}(N),
\end{align}
where we recall that the sets $\mathcal{N}\mathcal{P}\mathcal{M}^{\text{bad}}(\ell\ominus_{\mathbf{e}} p , K\setminus\{p\})$ and $\mathcal{N}\mathcal{P}\mathcal{M}^{\text{bad}}(\ell\oplus_{\mathbf{e}} q , K\setminus\{q\})$ are defined in  Observations~(obs:almost-bij of the paper)~and~(obs:almot-bij2 of the paper), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem GGI of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] Let $0 <\alpha< 1$ and consider the time interval $I = [0, T)$, where $T \leq \infty$. Suppose $a(t)$ is a
nonnegative function that is locally integrable on $I$, and $b(t)$ and $g(t)$ are nonnegative, nondecreasing
continuous functions defined on $I$ and bounded by a positive constant $M$. If $f(t)$ is nonnegative
and locally integrable on $I$, and satisfies
\begin{align*}
    f(t)\leq a(t)+b(t)\int_0^tf(s) \, ds+g(t)\int_0^t(t-s)^{\alpha-1}f(s) \, ds,
\end{align*}
then
\begin{align*}
    f(t)\leq a(t)+&\sum_{n=1}^\infty\sum_{i=0}^n\frac{n!(b(t))^{n-i}(g(t)\Gamma(\alpha_1))^i}{i!(n-i)!\Gamma(i\alpha+n-i)}\times\int_0^t(t-s)^{i\alpha+n-i-1}a(s) \, ds,
\end{align*}
where $\Gamma(\cdot)$ is the Gamma function. Moreover, if $a(t)$ is nondecreasing on $I$. Then
\begin{align*}
    f(t)\leq a(t)E_{\alpha}(g(t)\Gamma(\alpha)t^{\alpha})e^{\frac{b(t)t}{\alpha}}.
\end{align*}
Here, the Mittag-Leffler function  $E_{\varrho}(z)$ is  defined by $E_{\varrho}(z)=\sum\limits_{k=0}^\infty \frac{z^k}{\Gamma (k\varrho+1)}$ for $z > 0$, and $E_{\varrho}(z)<\infty$ when  $\varrho>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 103 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] \cite[Thm. 2.4]{Tappe}
Let $f_0 \in \Lip([0,T] \times W,D(A))$ and $$f \in C_b^{2\beta,3}([0,T] \times H, L(U,D(A^2)))$$ be mappings such that
\begin{align*}
&f_0|_{[0,T] \times D(A)} \in \Lip([0,T] \times D(A),D(A^2)),
\\ &f|_{[0,T] \times D(A)} \in C_b^{2\beta,3}([0,T] \times D(A), L(U,D(A^3))).
\end{align*}
Then for every $\xi \in D(A^2)$ the following statements are true:
\begin{enumerate}
\item There exists a unique mild solution $(Y,Y') \in \scrd_X^{2 \beta}([0,T],W)$ to the random RPDE \eqref{random-SPDE} with $Y_0 = \xi$ on $N^c$.

\item If $W$ is a separable Hilbert space $H$, then there is a $\bbp$-nullset $N_1$ with $N \subset N_1$ such that the associated stochastic process $Y$ restricted to $N_1^c$ is also a mild solution to the It\^{o} SPDE \eqref{SPDE-Wiener}.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 7 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $\mathbf{x},\mathbf{y}\in C^{0,\textup{$p$-var}}_o([0,T],G^{\lfloor p\rfloor}(\mathbb{R}^k))$. Then, for every $t\in[0,T]$,
    \begin{equation*}
        \sum_{m=0}^N \big\lVert S^m(\mathbf{x})_t - S^m(\mathbf{y})_t \big\rVert_{(\mathbb{R}^k)^{\otimes m}} \leq C(p,N,\Gamma)d_{\textup{inhom $p$-var};[0,t]}(\mathbf{x},\mathbf{y}),
    \end{equation*}
    where $\Gamma:=\max\big\{\lVert\mathbf{x}\rVert_{\textup{$p$-var};[0,T]},\lVert\mathbf{y}\rVert_{\textup{$p$-var};[0,T]}\big\}$.

