[Theorem thm : LDP/ExpEquiv_LDP of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $(\mathbb{X}, \mathrm{d}_\mathbb{X})$ be a metric space.
	\begin{enumerate}[(i)]
		\item If the processes $(X_n)_{n\ge 1}$ and $(Y_n)_{n\ge 1}$ on $\mathbb{X}$ are exponentially equivalent and $(X_n)_{n\ge 1}$ follows a LDP with a good rate function, then $(Y_n)_{n\ge 1}$ also follows a LDP, with the same rate function.
		\item Assume that the processes $(X_n^{(b)})_{n \ge 1}$ on $\mathbb{X}$ are exponentially good approximations of $\mathopen{}\mathclose\bgroup\originalleft( X_n \aftergroup\egroup\originalright)_{n\ge 1}$ as $b\to \infty$, and for all $b \ge 1$, $(X_n^{(b)})_{n \ge 1}$ follows the LDP with a rate function $I^{(b)}$. Then $(X_n)_{n\ge 1}$ follows the weak LDP with the rate function 
		\begin{equation}
			I : x \longmapsto \lim_{\varepsilon \to 0}\!\!\uparrow\! \liminf_{b\to\infty} \inf_{\hat x \in \ball[\mathbb{X}]{x, \varepsilon} } I^{(b)}(\hat x). 	
		\end{equation}
		If furthermore $I$ is a good rate function and satisfies, for all closed sets $F$,
		\begin{equation}
			\inf_{x\in F}I(x) \le \limsup_{b\to\infty} \inf_{x\in F} I^{(b)}(x),
		\end{equation}
		then $(X_n)_{n\ge 1}$ follows the LDP with the rate function $I$.
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Under the conditions of
	Theorem~(T1 of the paper), FSMGDA-M-VR attains an $\epsilon$-Pareto stationary
	solution with communication complexity
\begin{equation*}
	\mathcal{O}\left(
	\max\left\{
	\frac{L(1+D^2)\sigma\Delta(1+S)^{\frac{3}{2}}}
	{KM\epsilon^{\frac{3}{2}}},
	\frac{LS\Delta}{\epsilon},
	\frac{(1+S)G_0^2}{\epsilon},
	\left(
	\frac{C_1}{\epsilon}
	\right)^{\frac{3}{4}},
	\frac{\sigma^2(1+S)}{KM\epsilon},
	\left(
	\frac{(1+S)\sigma^2}{KM\epsilon}
	\right)^{\frac{1}{2}}
	\right\}
	\right),
\end{equation*}
	where
\begin{equation*}
	C_1:=
	\frac{(1+S)\sigma^2}{KM}
	\left(
	\frac{MKL^2(1+D^2)^2\Delta^2}{\sigma^4}
	\right)^{2/3}.
\end{equation*}
Moreover, the corresponding sample complexity is
\begin{equation*}
	\mathcal{O}\left(SMK\max\left\{
	\frac{L(1+D^2)\sigma\Delta(1+S)^{\frac{3}{2}}}
	{KM\epsilon^{\frac{3}{2}}},
	\frac{LS\Delta}{\epsilon},
	\frac{(1+S)G_0^2}{\epsilon},
	\left(
	\frac{C_1}{\epsilon}
	\right)^{\frac{3}{4}},
	\frac{\sigma^2(1+S)}{KM\epsilon},
	\left(
	\frac{(1+S)\sigma^2}{KM\epsilon}
	\right)^{\frac{1}{2}}
	\right\}
	\right).
\end{equation*}

