[Prop 8 (Variations of constants) of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] For $t>0$, let $(x_t,y_t)\in\R^\ell\times\R^m$ be a strong unique solution to a coupled SDE system, where $x_t$ evolves according to  
\begin{align} 
dx_t = A x_t dt+ f(x_t,y_t,t) dt + C dW_t.
\end{align} 
Here $A \in \R^{\ell \times \ell}$ and $C \in \R^{\ell \times k}$ are constant matrices, $W_t$ is a standard Brownian motion in $\R^k$ and  $x_0\in\R^\ell$ is the initial condition. Furthermore, assume that $f:\R^{\ell+m}  \times \R_{\geq 0} \to \R^\ell$ satisfies 
\begin{enumerate}
    \item uniformly Lipschitz continuous in space, i.e.\ there exists $L_f>0$ such that for any $z,z'\in\R^{\ell+m}$ we have  $|f(z,t)-f(z',t)|\leq L_f|z-z'|$;
    \item sublinear growth, i.e.\ there exists a constant $c>0$ such that for any $z\in\R^{\ell+m}$ and $t>0$ we have $|f(z,t)|\leq c(1+|z|)$. 
\end{enumerate}
Then $x_t$ can be explicitly written as
\begin{equation}
    x_t = e^{At}x_0 + \int_0^t e^{A(t-s)} f(x_s,y_s,s) ds + \int_0^t e^{A(t-s)} C dW_s\,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma no_fattrees_locally of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] For $\theta > 0$, there exists a constant $C_{\theta} > 0$ such that for any $r \ge 0$, we have
\begin{align*}
\#\{t \in \mathcal{T}_{\mathbf{p}^{n}}(n,g_n) : \mathcal{D}^{\mathcal{A}_{\mathrm{left}}}(t,e^n_1) \text{ satisfies } (\mathcal{S}_r)\}\le C_{\theta}r^{-1}\tau_{\mathbf{p}^{n}}(n,g_n).
\end{align*}

[Lemma 44 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For every $p \in (0,1)$ and every fixed $k \geq 0$,
\begin{equation}
    \sum_{j > k} \sum_{\fp \in \fakepolymers_j} \E[\fphi_\fp]    
    \leq \poly(d) \cdot \Fr{(2-p)^{k+1}}{2^{k}}^d.
\end{equation}

[Lem equiv cv f and G_f and varphi of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] Let $f$ and $f_n$, $n\ge1$, be functions in $\mathcal{F}$.
    Let $\varphi$ and $\varphi_n$, $n\ge1$, be the corresponding functions in $\mathcal{E}$.
    The following assertions are equivalent:
    \begin{enumerate}[label=(\roman*)]
        \item $f_n(x) \to f(x)$ for all continuity points $x$ of $f$;
        \item $G_{f_n} \to G_f$ for the Hausdorff distance;
        \item $\varphi_n \to \varphi$ for the uniform distance.
    \end{enumerate}

