\begin{equation}
	r_l\le \frac{c_6^{1/d}}{\lambda_l}\,,\quad l\ge 1\,.
\end{equation}
We then use~\eqref{n7a} and~\eqref{h0} to obtain
\begin{align*}
	\lambda_l^d - u_l(0) & = \int_0^{r_l} \partial_r u_l(r)\,\rd r \le \frac{a}{dm} \int_0^{r_l} r u(r)\,\rd r \\
	& \le \frac{a}{2dm} \|u_l\|_\infty r_l^2 \le \frac{a c_6^{2/d}}{2dm} \lambda_l^{d-2}\,.
\end{align*}
