it holds that 
\begin{equation}
\begin{split}
 &\ex \!\left[ 
 \Phi ''(M_{t})|\dv _{t}|^{2}
 \right] 
 -\ex \!\left[ 
 \Phi ''(M_{s})|\dv _{s}|^{2}
 \right] \\
 &=\ex \!\left[ 
 \frac{1}{\Phi ''(M_{t})}\left| 
 \Phi ''(M_{t})\dv _{t}-\Phi ''(M_{s})\dv _{s}
 \right| ^{2}
 \right] \\
 &\quad -\frac{1}{2}\ex \!\left[ 
 \Phi ''(M_{s})^{2}|\dv _{s}|^{2}\int _{s}^{t}du\,\left( 
 \frac{1}{\Phi ''}
 \right) ''\!(M_{u})|\dv _{u}|^{2}
 \right] .
\end{split}
\end{equation}

