[Theorem 3 of arXiv:2607.11608, '2607.11608'] Let $d\ge 1$ and $p^*=2+\frac{4}{d}$. Let $\left\{\ld_N\right\}_{N\in \N}$ be a non-increasing sequence sequence of positive numbers tending to $0$ and $\left\{K_N\right\}_{N\in \N}$ be a non-decreasing sequence of positive numbers. Then, there exists $\ld^*\ge \ld_*>0$ such that the following hold:

\smallskip
\noi
\textup{(i) (weakly coupling regime).}
Suppose that 
\begin{align}
\ld_N\le \ld_* (K_N+\log N)^{-\frac{2}{d}}

\end{align}

\noi
for any $N \in \N$.
Then, 
given any $r\geq 1$ we have
\begin{align*}
\sup_{N\in\N}\mathcal{Z}_{p^*\!,\,N}:=\sup_{N\in\N}\Big\|\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}} e^{ \ld_N R_{p^*\!,N}(u)}\Big\|_{L^r(\mu)}<\infty.

\end{align*}

\noi
In particular, we have
\begin{align}
\lim_{N\rightarrow\infty}
\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}}  
e^{\ld_N  R_{p^*\!,N}(u)}=
\ind_{\{|\int_{\R^d} \, :|u|^2: \, dx| \, \leq K\}}  \quad     \text{in}\ L^r(\mu), 

\end{align}

\noi
where 
$K = \lim_{N \to \infty}K_N \in (0, \infty]$.
Here, 
\[\int_{\R^d} :\!|u|^2\!:dx = \lim_{N \to \infty}\int_{\R^d} :\!|\P_{N} u|^2\!:dx,\]

\noi
where the limit is understood in 
$L^r(\mu)$ and $\mu$-almost surely
as in Lemma \ref{LEM:conv0}.
As a consequence, 
we have

\smallskip
\begin{itemize}
\item[\textup{(i.a)}] 
If $K  =  \lim_{N \to \infty}K_N  = \infty$, 
then the truncated Gibbs measure $\rho_N$
in \eqref{trunc_gibbs}
converges in total variation to the base Gaussian measure $\mu$ in \eqref{Gaussian}
as $N \to \infty$.



\smallskip
\item[\textup{(i.b)}]
If $K = \lim_{N \to \infty}K_N < \infty$, 
then the truncated Gibbs measure $\rho_N$
in \eqref{trunc_gibbs}
converges in total variation to the base Gaussian measure
with a renormalized $L^2$ cut-off\textup{:}
\begin{align*}
\ind_{\{|\int_{\R^d} \, :|u|^2: \, dx| \, \leq K\}}  d\mu, 

\end{align*}

\noi
as $N \to \infty$.



\end{itemize}

\smallskip
\noi
\textup{(ii) (strongly coupling regime).}
Suppose that 
\begin{align}
\ld_N\ge \ld^{*}(K_N+\log N)^{-\frac{2}{d}}

\end{align}

\noi
for any sufficiently large $N \gg 1$.
Then, we have 
\begin{align}
\sup_{N\in\N}\mathcal{Z}_{p^*\!,\,N}=
\sup_{N\in\N}\Big\|\ind_{\{|\int_{\R^d} \, :|\P_{N} u|^2: \, dx| \, \leq K_N\}} e^{ \ld_N  R_{p^*\!,N}(u)}\Big\|_{L^1(\mu)}
=\infty.

\end{align}

\noi
As a consequence, 
the truncated Gibbs measure $\rho_N$ in \eqref{trunc_gibbs}
does not converge   to any  limit in total variation, even up to a subsequence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $d \geq 1$, $k \geq 1$, and $X_1$ has the bounded density $f$.
    Let $\{\Gamma_i\}_{i=1}^m$ be the set of all non-isomorphic feasible graphs with $k+1$ vertices that have at least one vertex of degree $k$.
    Then, as $n \to \infty$,
    \begin{equation*}
        -n^{(k+1)/(dk)} S_k(\CX_n) \xrightarrow{d} Z_{d,k},
    \end{equation*}
    where $Z_{d,k}$ is a random variable with the Weibull distribution
    \begin{equation*}
        P[Z_{d,k} \leq x] =
        \begin{cases}
            \exp(-\mu_{d,k}(-x)^{dk}) & (x < 0),\\
            1 & (x \geq 0)
        \end{cases}
    \end{equation*}
    and $\mu_{d,k} := \sum_{i=1}^m \mu_{\Gamma_i}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 9 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] We have the following absolutely convergent expression
		\begin{multline*}
			I_2(s)=\intop_{K_n}\intop_{N_2(\A)\bs G_2(\A)}\left(\ \intop_{[G_{n-2}]}W^{\Q_{n-2}}_{\phi_{\Q_{n-2}}}\left[\begin{pmatrix}g&\\&h\end{pmatrix}k\right]|\det g|^{s-1}\, dg\ \right)\\
			\times\overline{W^{\Q_{n-2}}_{\Eis(f)_{\Q_{n-2}}}\left[\begin{pmatrix}\mathrm{I}_{n-2}&\\&h\end{pmatrix}k\right]}\Phi\left[e_n\begin{pmatrix}\mathrm{I}_{n-2}&\\&h\end{pmatrix}k\right]|\det h|^{n-3/2+s}\, dh\, dk
		\end{multline*}
		for $\Re(s)$ sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $n\in\N$, $\mu\neq0$ be a finite measure on $\R^d$, $J$ be an index set, \linebreak $\{f_j:j\in J\}\subseteq L^1(\mu)$, and $x_1,...,x_n\in\R^d$. We say that $x_1,...,x_n$ form an \textit{averaging set} of $\mu$ and $\{f_j:j\in J\}$ of size $n$ if
    \begin{equation}
        \frac{1}{\mu(\R^d)}\int f_j(x)\, \mu(dx) = \frac{1}{n} \sum_{k=1}^n f_j(x_k),\quad j\in J.
    \end{equation}
    If we do not say otherwise, we require that $x_1,...,x_n$ are pairwise different. Then we also say that $\{x_1,...,x_n\}$ is an averaging set of $\mu$ and $\{f_j:j\in J\}$ of size $n$.

[Lemma Bounds_on_A_k of arXiv:2605.18744, 'Lattice random-field Widom--Rowlinson models'] There is $C>0$ such that for all $k\in \mathbb{Z}_{\ge 0}$ and $A\Subset \mathbb{Z}^d$
\begin{align*}
    |\partial^\prime A_k|\le C|\partial ^\prime A|,\qquad
    | A_{k+1}\ominus A_{k}|\le C2^k|\partial ^\prime A|\qquad \text{and }\qquad 
    |A_k|\le C|\partial^\prime  A|^{d/(d-1)}.
\end{align*}

