[Thm 65 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that \cref{ncptas} is satisfied. 
  We regard $F$ and $F_n$ as subsets of a common $\bcm$ space $(M,d)$.
  Let $x\in F$ and $x_n\in F_n$. Take $r_{\infty}\ge r_0$ satisfying 
  $x\in B(\rho,r_{\infty})$ and $x_n\in B(\rho_n,r_{\infty})$.
  Then, for any $f\in\BL^{\kappa}(M),\kappa\in [1/2,1]$ and $t>0$
  \begin{align*}
    |P_{t}f(x)-P^n_tf(x_n)|
    \lesssim\|f\|_{\BL^{\kappa}}
    \inf\Bigl\{  \Psi_1(n,r)+C_n(r)\Psi_2(n,r)^E : r\in [r_{\infty},\infty), \Psi_2(n,r)\le \frac{1}{2}\Bigr\},
  \end{align*}
  where
  \begin{equation*}
    \Psi_1(n,r)=P_{x}^n(\sigma_{B(\rho,r)^c}\le t)\vee P_{x_n}^n(\sigma^n_{B(\rho_n,r)^c}\le t),
  \end{equation*}
  \begin{equation*}
    \Psi_2(n,r)=d_{\rm{H}}(F^{(r)},F_n^{(r)})^{\kappa}+d_{\BL^{\kappa}}(\mu^{(r)},\mu^{(r)}_n)+d(x,x_n),
  \end{equation*}
  \begin{equation*}
    \begin{aligned}
      C_n(r)=&(D_n^{(r)})^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}\\
    &\quad\times \left[(\diam K_n^{(r)}+\mu_n(F_n^{(r)}))\diam K_n^{(r)}\mu_n(F_n^{(r)})\mu(F^{(r)})^{3/2}\diam F^{(r)}(\mu(F^{(r)})^{1/2}+\mu_n(F_n^{(r)}))\right]\\
    \lesssim& r^{6+\frac{3}{2}s+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)}(r+\mu_n(F^{(r)}))(r^{s/2}+\mu_n(F^{(r)}))(r^s+\mu_n(F^{(r)}))^{4+2(1+\frac{s}{2(1+s)\theta})(2\kappa-1)},
    \end{aligned}
  \end{equation*}
  \begin{equation*}
    K_n^{(r)}=F^{(r)}\cup F_n^{(r)},\qquad D_n^{(r)}=\mu(F^{(r)})\diam F^{(r)}\vee \mu_n(F^{(r)}_n)\diam F^{(r)}_n,
  \end{equation*}
  and
  \begin{equation*}
    E=\frac{\kappa}{\kappa+(1+s)(2+\kappa)(\kappa+\theta)}.
  \end{equation*}
  Moreover, the time-dependence of the constant in $\lesssim$ is $t^{[\kappa-\frac{s}{2(1+s)\theta}(2\kappa-1)]},\;t\in (0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] The  functional type law of large numbers holds for the multi-scale ensemble Kalman sampler model $((ex2:systema of the paper))$-$((ex2:systemb of the paper))$, i.e.,
	\begin{align*}
		\mathbb{E}\Big[\sup_{t\in [0, T]}|X_{t}^{\varepsilon}-\bar{X}_{t}|^{2}\Big]\lesssim_T (\varepsilon+\delta^{1/3}),
	\end{align*}
	where $\bar{X}_t$ is the solution of the corresponding averaged equation. Moreover,
	if $\delta = o(\varepsilon)$, then $\{X^{\varepsilon}\}_{\varepsilon\in (0,1)}$ satisfies the LDP.

