		\phi = K_H^{-1}\left( \int_0^\bullet \theta_r \d{r} \right) = c_H^{-1} \Gamma \left( H-\tfrac12 \right)^{-1} \bullet^{H-\frac{1}{2}} I^{-(H-\frac{1}{2})}_{0+}\left( \bullet^{-(H-\frac{1}{2})} \theta \right),
	\end{equation}
	it holds that
	\[
		\tilde{B}^H_t = \int_0^t K_H(t,s) \left( \d{B_s} + \phi_s \d{s} \right)
	\]
	and the claim follows from Theorem ...","release_manifest_digest":"sha256:4be9ae37127831716b1689a462012899d2fc53c90d38b89c9ad1c9dd0b4dc799","revision_digest":"sha256:d7a5dec6d8772b1ed1ab4d955effe461b6114d2654d3bb9509d4eefb9fc46bd0","source_id":"arxiv:2604.24664","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Prop PotentialOperator of arXiv:2411.19543, 'Feller property and convergence for semigroups of time-changed processes'] We have
\begin{enumerate}
\item[\rm(1)] Assume that  $\mu$ is $G$-bounded. Then $G^\mu$ maps continuously $\mathscr{B}_b(X)$ into $\mathscr{B}_b(X)$. If moreover $G^\mu 1$ is continuous then $G^\mu$ maps continuously $\mathscr{B}_b(X)$ into  $C_b(X)$.
\item[\rm(2)] Assume that  $\mu\in  \mathscr{K}(X)$. Then $G^\mu$  maps continuously  $\mathscr{B}_b(X)$ into $C_0(X)$.
\end{enumerate}

[Proposition of arXiv:2411.09257, 'Iterated Generalized Counting Process and its Extensions'] The L\'evy measure of IGCP is given by
\begin{equation*}
\Pi_{\hat{M}}(\mathrm{d}x)=\sum_{j_0=1}^{k_0}\mu_{j_0}\sum_{n=1}^{\infty}\sum_{\Omega(k,n)}\Big(\prod_{j=1}^{k}\frac{(j_0\lambda_{j})^{n_{j}}}{n_{j}!}e^{-j_0\lambda_{j}}\Big)\delta_n(\mathrm{d}x),
\end{equation*}
where $\delta_n$'s are Dirac measures.

