[Defn defn4.15 of arXiv:2411.09988, 'A Study in Markov Chains, Loop-Erased Random Walk and Loop Soups'] The \textit{rooted loop measure} $\tilde{m}=\tilde{m}^p$ is the measure that assigns measure
    \begin{equation}
        \tilde{m}(l) = \frac{p(l)}{|l|}
    \end{equation}
    to every loop
    \[l \in \bigcup_{j=1}^{n}\mathcal{K}_A(x_j, x_j).\]
    The corresponding Poisson realization is called the \textit{rooted loop soup}.

[Definition def:disc_loc_times of arXiv:2512.17747, 'On exponentially height-penalized random trees'] For any path $(p(t);0\leq t\leq n)$ of length $n$, define the local time at a particular level and the maximum local time as follows. For an integer $k\in [-n,n]$,
\begin{align*}
    L_{k,n}(p):=|\{t:p(t)=k\}|;\;\;L_n(p):=\max_{-n \leq k \leq n}L_{k,n}(p).
\end{align*}

[Prop thm:polynomial of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Let \(P\in\mathbb R[x]\) have degree \(d\ge2\).  Then there is a constant \(c_P>0\), depending only on \(P\), with the following property.  If
			\begin{equation}
				\sum_{s\ge1}s \exp(-c_PR'_d(s))<\infty,
			\end{equation}
			then \(P(X)\) is almost surely absolutely normal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:hoermplaw of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] {Keeler}}{}]
For any $M$ compact Riemannian manifold, 
\begin{equation} 
E^M_{[0,\ell]}(x,y) = \ell^n\left( E_{[0,1]}^{n}(\ell\dist xy)+R_{[0,\ell]}^M(x,y)\right),
\end{equation}
with remainder of order $R_{[0,\ell]}^M(x,y)=\mathrm{O}(\ell^{-1})$. Precisely, the estimate continues to hold for the derivatives in the following sense: for $\rho(M)$ small enough, for any $k\in \mathbb{N}$,
\begin{equation}
\sup_{\mathrm{dist}(x,y)\le \rho(M)}\max_{|a|,|b|\le k} \frac{\| \nabla^a \nabla^b R_{[0,\ell]}^{M}(x,y)\|}{\ell^{|a|+|b|}}=\mathrm{O}(\ell^{-1}). 
\end{equation}
In particular, it follows that: 
\begin{equation} 
\sigma(\phi_{[0,\ell]}^M)^2=\ell^{n}\left( \frac{b_n}{(2\pi)^n}+\mathrm{O}(\ell^{-1})\right),\quad \lambda(\phi_{[0,\ell]}^M)^2=\ell^2\left(\frac{n}{n+2}+\mathrm{O}(\ell^{-1})\right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop PRO26 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Assume that every semipolar subset of $E$ is polar. Then, for any $x\in E$ and $B\in \mathscr{B}^n(E)$,
\begin{equation}
    \widetilde{d}(x,B)=d(x,B\cap B^r). 
\end{equation}

[Proposition 7 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] There exist $\varepsilon,\gamma,C>0$, an analytic eigenvalue
$u\mapsto\lambda_u =\lambda(\beta-iu)$, and analytic rank-one Riesz
projections $u\mapsto P_u$, defined on an open neighborhood of $|u|\le\varepsilon$, such that
\begin{equation}
 S_u(t)=e^{-t\lambda_u}P_u+R_u(t),
 \qquad
 \norm{R_u(t)}_{2\to2}
 \leq Ce^{-(\lambda (\beta)+\gamma)t}

\end{equation}
for $|u|\leq\varepsilon$ and $t\geq1$.  Moreover,
\begin{equation}
 \lambda(\beta-iu)
 =\lambda (\beta)-iu \lambda'(\beta)
  -\frac12 \lambda''(\beta) u^2+O(|u|^3).

\end{equation}
After decreasing $\varepsilon$ if necessary,
\begin{equation}
 \Re\bigl(\lambda(\beta-iu)-\lambda(\beta)+iu \lambda'(\beta)\bigr)
 \geq c_0u^2,
 \qquad |u|\leq\varepsilon,

\end{equation}
for some $c_0>0$.

[Thm Theorem 1 of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$ with $\mathcal F^{elec}_{\beta}(\mathsf{P}_i)<\infty$, $i=0,1$. Then there exists a coupling $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$ such that for $0\leq t\leq 1$ \begin{align}
        \mathcal F^{elec}_{\beta}(\mathsf{P}_{t})&\leq  (1-t) \mathcal F^{elec}_{\beta}(\mathsf{P}_{0})+t\mathcal F^{elec}_{\beta}(\mathsf{P}_{1})\\
        &-\frac{(\mathbbm{1}_0(s)+s(s+1))(1-t)t\beta}{4}\int \sum_{(0,0)\neq (x,y)\in \bar\xi} (x-y)^2\inf_{z\in [x,y]}\left\lvertz\right\rvert^{-s-2} \mathsf{Q}^0(d\bar\xi),\nonumber
    \end{align}
    where  $\mathsf U:=\iota( \mathsf{Q})$ and  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LemmaUe of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that condition (equation third-grade-paremeters-res of the paper) and Hypothesis (Hyp-f-B of the paper) are satisfied. Then, for every $\mathfrak{r}\in \mathbb{R}$, $\omega\in \Omega$ and $B=\{B(\mathfrak{r},\omega):\mathfrak{r}\in\mathbb{R},\; \omega\in \Omega\}\in \mathfrak{D}$, there exists $\mathcal{T}=\mathcal{T}(\mathfrak{r},\omega,B)\geq 1$ such that for all $t\geq \mathcal{T}$, $s \in [\mathfrak{r}-1,\mathfrak{r}]$ and $\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t}\in B(\mathfrak{r}-t,\vartheta_{-t}\omega)$, the solution $\boldsymbol{\mathcal{Z}}(\cdot)$ of system (equation CTGF of the paper) with $\omega$ replaced by $\vartheta_{-\mathfrak{r}}\omega$ satisfies
		\begin{align}
			&\|\boldsymbol{\mathcal{Z}}(s;\mathfrak{r}-t,\vartheta_{-\mathfrak{r}}\omega,\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t})\|^2_{2} + \frac{\nu\varepsilon_0}{2}\int_{\mathfrak{r}-t}^{s}e^{-\int^{s}_{\zeta}\mathopen{}\mathclose\bgroup\originalleft(\frac{\sigma^2}{2}-2\sigma y(\vartheta_{\upeta-\mathfrak{r}}\omega)\aftergroup\egroup\originalright)\/\mathrm{d}\/ \upeta}\|\boldsymbol{\mathcal{E}}(\boldsymbol{\mathcal{Z}}(\zeta;\mathfrak{r}-t,\vartheta_{-\mathfrak{r}}\omega,\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t}))\|^2_{2}\/\mathrm{d}\/\zeta
			\nonumber\\ &	+ \beta\varepsilon_0 \int_{\mathfrak{r}-t}^{s}e^{-\int^{s}_{\zeta}\mathopen{}\mathclose\bgroup\originalleft(\frac{\sigma^2}{2}-2\sigma y(\vartheta_{\upeta-\mathfrak{r}}\omega)\aftergroup\egroup\originalright)\/\mathrm{d}\/ \upeta}\Upsilon^{-2}(\zeta,\vartheta_{-\mathfrak{r}}\omega)\|\boldsymbol{\mathcal{E}}(\boldsymbol{\mathcal{Z}}(\zeta;\mathfrak{r}-t,\vartheta_{-\mathfrak{r}}\omega,\boldsymbol{\mathcal{Z}}_{\mathfrak{r}-t}))\|^4_{4}\/\mathrm{d}\/\zeta
			\nonumber\\&\leq   \frac{4e^{\int_{s}^{\mathfrak{r}}\mathopen{}\mathclose\bgroup\originalleft(\frac{\sigma^2}{2}-2\sigma y(\vartheta_{\upeta-\mathfrak{r}}\omega)\aftergroup\egroup\originalright)\/\mathrm{d}\/ \upeta} }{\min\mathopen{}\mathclose\bgroup\originalleft\{2\nu\varepsilon_0,\sigma^2\aftergroup\egroup\originalright\}} \int_{-\infty}^{0} e^{\frac{\sigma^2}{2}\zeta+2\sigma\int^{0}_{\zeta} y(\vartheta_{\upeta}\omega)\/\mathrm{d}\/ \upeta} \Upsilon^2(\zeta,\omega) \|\boldsymbol{\mathfrak{K}}(\cdot,\zeta+\mathfrak{r})\|^2_{\mathbb{H}^{-1}}\/\mathrm{d}\/ \zeta < + \infty.
		\end{align}

