body:
[Lemma G_at_q0 of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] The function 
$\exp(G(z,w))= (z-1)^{\ell} w z^{-\tau }$ has a zero of order $2\ell$ at $q_0$. Hence in a neighbourhood of $q_0$ setting $z=1+\frac{Z}{\sqrt{N}}$, with respect to the (canonical) local chart coming from $(z,w)\mapsto z$ we have that
\begin{equation} 
w_k^{-r_k}\exp(NG(z_k,w_k))=\left(B^{-1}+\mathcal{O}\left(\frac{|Z_k|}{N^{\frac{1}{2}}}\right)\right)^{N-r_2}\left(\frac{Z_k}{N^{\frac{1}{2}}}\right)^{2\ell N-r_k\ell},\quad\text{for}\quad k=1,2,
\end{equation}
where $B>0$ is as in Lemma (lemma:local_action_function of the paper).

[Lemma 13 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ GOE/GUE matrix. For any fixed $D\in\N$, $n_1,n_2\in\N\cup\{0\}$ and multi-indices $\bm{k}\in \N^{n_1},\bm{l}\in\N^{n_2}$, it holds that
\begin{equation}
\E\left(\bm{k},\bm{l}\right) = \sum_{d=0}^{D-1} \frac{1}{(N\eta)^d}\Phi_d\left(\bm{k},\bm{l}\right) + \mathcal{O}\left(\frac{1}{(N\eta)^D}+\eta\right),

\end{equation}
where the implicit constant in $\mathcal{O}(\cdot)$ is uniform in $z\in\mathcal{D}$. For $d\in \N\cup\{0\}$, the coefficients $\Phi_d$ depend only on $\Re z$, $\bm{k}$, $\bm{l}$ and $\beta$, and satisfy the following recurrence relations for $\bm{k}\neq\emptyset$:
\begin{equation}
\begin{split}
\Phi_d(\bm{k},\bm{l})=&\frac{2\ma_0}{\beta}\Im m_0 \sum_{j=1}^{n_2} \frac{\ii^{k_1-l_j-1}}{2^{k_1+l_j-1}} l_j\binom{k_1+l_j-1}{k_1-1} \Phi_d\left(\bm{k}^{[1]},\bm{l}^{[j]}\right)+\bm{1}_{\beta=1}\ma_0 k_1\Phi_{d-1}\left(\big(k_1+1,\bm{k}^{[1]}\big),\bm{l}\right)\\
+& \ma_0 \sum_{u=1}^{k_1} \Phi_{d-1}\left(\big(u,k_1+1-u,\bm{k}^{[1]}\big),\bm{l}\right)+\frac{2\ma_0}{\beta} \sum_{i=2}^{n_1} k_i \Phi_{d-1}\left(\big(k_1+k_i+1,\bm{k}^{[1,i]}\big),\bm{l}\right)\\

+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{u=1}^{k_1} l_j \frac{(-1)^{k_1-u}}{(2\ii)^{k_1+l_j+1-u}} \binom{k_1+l_j-u}{l_j}\Phi_{d-1}\left( \big(u, \bm{k}^{[1]}\big), \bm{l}^{[j]}\right)\\
+&\frac{2\ma_0}{\beta} \sum_{j=1}^{n_2} \sum_{v=1}^{l_j+1} l_j\frac{(-1)^{k_1}}{(2\ii)^{k_1+l_j+1-v}}\binom{k_1+l_j-v}{k_1-1}\Phi_{d-1}\left(\bm{k}^{[1]},\big(v,\bm{l}^{[j]}\big)\right).
\end{split}

\end{equation}
Here we additionally set $\Phi_{d'}:=0$ for $d'<0$ and $\Phi_0(\emptyset,\emptyset):=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 12 of arXiv:2512.02766, 'Fine-Graining and Continuous Space Scaling Limit of the $H^{2|2}$ Model on the Hierarchica'] On the Dyson hierarchical lattice $\mathbb{X}$ with spectral dimension $d_s=2$, the $\widetilde{\beta}$-field and the $\widetilde{u}$-field (defined in Sec. \ref{sec:find-grain-coupling}) of the $H^{2|2}$-model are stationary and ergodic with respect to the group of automorphisms of $\mathbb{X}$. Especially, we have the following zero-one law on the limit martingale (defined in \eqref{eq:mart-eux}:
\begin{equation*}
    \mathbb{P}\left[\left\{\forall x\in[0,1), \varphi_{x}=0\right\}\right],  \mathbb{P}\left[\left\{\forall x\in[0,1), \varphi_{x}>0\right\}\right]\in\{0,1\}.
\end{equation*}

