[Theo thm:random-SLE of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Fix $\alpha>0$. In the previous setup, for $t^{(\alpha)}_n= n^{-(\alpha+\frac{1}{3})}$, one has $\mathbf{P}$-almost surely
\begin{equation}
	\gamma^{(\delta_n)}_{\omega,t^{(\alpha)}_n} \underset{n\to \infty}{\overset{(d)}{\longrightarrow}}  \mathrm{SLE}_{16/3}(\Omega,a,b),
\end{equation}
where $\mathrm{SLE}_{16/3}(\Omega,a,b)$ is the standard chordal Schramm–Loewner-Evolution process in $\Omega$ that connects $a$ to $b$ in $\Omega $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2604.11385, 'Quantitative large population limit for non exchangeable diffusions in Fisher information'] We let $\displaystyle \delta_{N}=\max_{(i,j) \in v^{2}} \xi_{i,j}^{N}$ and
\[H_{t}^{v}=H \left( P_{t}^{v,N}|Q_{t}^{v,N} \right), \qquad \quad I_{t}^{v}=I\left(P_{t}^{v,N}|Q_{t}^{v,N} \right).\]
Fix a $T>0$ and suppose that there exists a constant $C$ such that
\begin{equation*}
\forall v \subset [N], \
    H_{0}^{v}+I_{0}^{v} \leq C \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
Suppose moreover that $\left(P_{0}^{[N],N}, Q_{0}^{[N],N}\right)$ satisfies Hypothesis \ref{hyp-princ}.
We distinguish two set of assumptions:
\begin{itemize}
    \item Torus Case. Suppose that $b$ is smooth and assume that that  $\nabla^2 \log Q_{0}^{u,N}$ is bounded with constants that do not depend on $u$ or $N$.
    \item $\mathbb{R}^d$ case. Suppose that $b$ is smooth bounded, with bounded derivatives and assume that there exists $C>0$ such that 
    \begin{equation*}
   \forall u \in [0,1], \ \sup_{t\in [0,T]}\Vert \nabla^2 \log Q_{t}^{u,N}\Vert \leq C.
\end{equation*}

\end{itemize}
Then, there exists a constant $M_{T}$ (that does not depend on v,N) such that 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \left(\delta_{N} |v|+1\right)\left( \sum_{(i,j)\in v^{2}} \left(\xi_{i,j}^{N} \right)^{2}+\delta_{N} \sum_{(i,j) \in v} \left(\xi^{T} \xi+\xi \xi^{T} \right)_{i,j}+\delta_{N}^{2} |v| \right).
\end{equation*}
In particular, if $\xi_{i,j}^{N}=G_{N} \left( \frac{i}{N}, \frac{j}{N} \right)$ with $G_{N}$ a graphon with values in $[0,1]$, we have 
\begin{equation*}
\forall v \subset [N], \
    H_{T}^{v}+I_{T}^{v} \leq M_{T} \frac{\left|v \right|^{2}}{N^{2}}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 199 of arXiv:2601.16377, '2601.16377'] The master problem asks to find an $H$-tuple of functions $\boldsymbol{F}(z)=(F_h(z))_{h=1}^H$ with the following properties for any $h \in [H]$.
\begin{enumerate}
\item $F_h(z)$ is a holomorphic function of $z \in \amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$.
\item There exists a holomorphic function $A_h(z)$ of $z \in \amsmathbb{M}_h$ such that
\begin{equation}

 A_h(z) = \sqrt{(z-\alpha_h) (z-\beta_h)} \,\big\langle \bth_h \cdot \boldsymbol{F}(z)\big\rangle + E_h(z).
 \end{equation}
 \item $F_h(z) = \frac{\kappa_h}{z}+O\big(\frac{1}{z^2}\big)$ as $z \rightarrow \infty$. This can be equivalently restated as
\[
F_h(z)\,\, \mathop{=}_{z \rightarrow \infty} \,\, O\bigg(\frac{1}{z}\bigg) \qquad \textnormal{and} \qquad \oint_{\gamma_h} \frac{\dd z}{2\ii\pi}\,F_h(z) = \kappa_h.
\]
\end{enumerate}

