[Thm P th gau of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exist a deterministic constant $c_1\in(0,\infty)$
  and a deterministic function $c_2\colon (0,\infty)\to(0,\infty)$ such that the following holds.
  \begin{enumerate} [label = \textup{(\roman*)}]
    \item
    If $\hat{d}_{\mathrm{s}}>2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    \begin{equation}
      c_1
      \leq
      \sup_{x\in M}
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{cp}}}\log(1/r)}
      \leq
      \varlimsup_{r\downarrow0}
      \sup_{x\in M}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{cp}}}\log(1/r)}
      \leq
      c_2(t).
    \end{equation}

    \item
    If $\hat{d}_{\mathrm{s}}=2$, then, $\hat{P}_{\bm{\rho}}$-a.s., for all $t \in (0,\infty)$,
    \begin{equation}
      c_1
      \leq
      \sup_{x\in M}
      \varlimsup_{r\downarrow0}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}(\log(1/r))^2}
      \leq
      \varlimsup_{r\downarrow0}
      \sup_{x\in M}
      \frac{\Pi_t(B(x,r))}{r^{d_{\mathrm{f}}}(\log(1/r))^2}
      \leq
      c_2(t).
    \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

