[Lemma 9 of arXiv:2606.06193, 'Peng's Maximum Principle for McKean-Vlasov Stochastic Differential Equations with Common N'] Let $\varphi \in C_b^{2,1}(\R^d\times \mathcal{P}_2(\mathbb{R}^d),\R)$. Then, for any given $x\in\R^d$ and $X \in L^2(\Omega, \mathbb{R}^d)$ we have the following second-order expansion, for all $y\in\R^d$ and $Y\in L^2(\Omega,\R^d)$,
        \begin{equation*}
            \begin{aligned}
                &\varphi(y,\cL(Y))- \varphi(x,\cL(X)) \\
                = & \varphi_x(x,\cL(X))[y-x]
                +\E\left[\varphi_\mu(x,\cL(X))(X)[Y-X]\right]
                +\frac{1}{2}\varphi_{xx}(x,\cL(X))[y-x,y-x]\\
                &+\frac{1}{2} \E\left[\tilde{\E}\left[ \varphi_{\mu\mu}(x,\cL(X))(\tilde{X}, X)[ \tilde{Y}-\tilde{X},Y-X]\right]
                +\varphi_{y\mu}(x,\cL(X))(X)[Y-X,Y-X]\right]\\
                &+\E\left[\varphi_{x\mu}(x,\cL(X))(X)[Y-X,y-x]\right]+R(x,y,\cL(X), \cL(Y)).
            \end{aligned}
        \end{equation*}
        Furthermore, for all $x,y\in \R^d$ and $X,Y \in L^2(\Omega, \mathbb{R}^d)$, the remainder satisfies the estimate
        \begin{equation*}
            \begin{aligned}
                |R(x,y,\cL(X), \cL(Y))| \leq C\left( |y-x|^3

                + \E[|Y-X|^3]\right),
            \end{aligned}
        \end{equation*}
        and the constant $C \in \mathbb{R}_{+}$ only depends on the Lipschitz constants of $\varphi_{xx}$, $\varphi_{x\mu}$, $\varphi_{\mu\mu}$ and $\varphi_{y\mu}$.

