[Lemma lem-26apr2002 of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Suppose there exists $C>0$ so that 
    \begin{equation}

      \kappa(t)\le \frac{C}{|t|} \quad \text{for all } t \leq -1.
    \end{equation}
    Then there exists $t_{\textnormal{max}} \leq -1$ such that for all $\mathfrak{t} \leq t_{\textnormal{max}}$, there exists $T=T(\mathfrak{t}) > |\mathfrak{t}|$ such that the solution $z(t,x)$ of (equation eq:finite-time of the paper) satisfies
    \begin{equation}

      z(\mathfrak{t}, x) \geq x \quad \text{for all } x \leq \frac{\abs{\mathfrak{t}}}{2}
    \end{equation}
    and
    \begin{equation}

      \left |\partial_x z(t,x) \right| \leq 16 \quad \text{for all } t<\mathfrak{t}, x > 0.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:assoc-game of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] \enskip

\begin{enumerate}[(i)]
\item A global Markovian pure Nash equilibrium $(\tilde\tau_1^*,\tilde\tau_2^*)$, whose value corresponds to a continuous function $V: {\cal I}\rightarrow \mathbb{R}$, exists. 
More precisely,  
\begin{align*}
 \tilde \tau_i^*= \inf\{t \geq 0: X_t \in D_i^{*}\}, \enskip i=1,2,
\end{align*}
where
\begin{align}
\begin{split}
D_1^{*}:&=\{x \in {\cal I}: \tilde f(x)=V(x)\},\\
D_2^{*}:&=\{x \in {\cal I}: \tilde g(x)=V(x)\}.
\end{split}
\end{align}
Moreover, $\tilde f(x)\leq V(x) \leq\tilde g(x)$, for each $x \in {\mathcal I}$.

\item  For $x \in B^{g \leq f} \supseteq  {B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} $, it holds that $V(x) = \tilde f(x)=\tilde g(x)$. 
Moreover, in equilibrium both players stop on $B^{g \leq f}$; in particular, 
\begin{align}
{B^{g\leq h \leq f}} \cup {B^{h<g<f}} \cup {B^{g<f<h}} \subseteq B^{g \leq f} \subseteq  D_i^{*} , \enskip i =1,2.
\end{align} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

