	\begin{align}
	\mathcal I(s,\lambda;\varphi)\leq Cs^{15/2}\lambda^8\int_0^1\int_{\omega}e^{-4s\alpha_*+2s\alpha^*}(\xi^*)^{15/2}|\varphi|^2dxdr
	\end{align}
    for any $\lambda$ satisfying
	\begin{equation}
	\lambda\geq\widehat\lambda\exp\left(\widehat\lambda\|g\|_{L^\infty(Q)}^2\right)\left(1+\|g\|_{L^\infty(Q)}^{10/3}+\|\partial_rg\|_{L^2(0,1;L^4(D))}^{10/3}\right),
	\end{equation}
    and any $s\geq\widehat se^{8\lambda K}$.

