[Lemma 3 (Evolution of the area and its push-forward) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Let $X_t:=\partial_tF_t$.  Then the induced area measure on the fixed
domain satisfies
\begin{equation}

 \partial_t\dd\mu_t
 =-\langle H_t,X_t\rangle\dd\mu_t
 =a_t^{-2}\langle H_t,G_t\rangle\dd\mu_t.
\end{equation}
Moreover, for every $\varphi\in C^1(\Sph^3)$,
\begin{equation}

 \begin{aligned}
 \frac{\dd}{\dd t}\int_{\Sph^3}\varphi\dd\lambda_t
 &=\int_\Sigma
 \left[
  \big\langle\nabla^{\Sph^3}\varphi(F_t),X_t\big\rangle
  -\varphi(F_t)\langle H_t,X_t\rangle
 \right]\dd\mu_t\\
 &=\int_\Sigma a_t^{-2}
 \left[
  -\big\langle\nabla^{\Sph^3}\varphi(F_t),G_t\big\rangle
  +\varphi(F_t)\langle H_t,G_t\rangle
 \right]\dd\mu_t.
 \end{aligned}
\end{equation}

[Prop occupation of arXiv:2411.05441, 'Sticky diffusions on star graphs : characterization and It\^o formula'] For every bounded and measurable function $f \colon \mathbb{R}_+ \to \mathbb{R}$ the time-changed process $X$ satisfies
		\begin{equation}
		\int_0^t f(s) \mathbf{1}_{\{X(s) = \mathsf{v}\}}\, ds = \eta \int_0^t f(s) d\ell_X(s) \quad \textnormal{almost surely for every } t > 0,
		\end{equation}
		where the integral in the right-hand side must be understood in the Lebesgue-Stieltjes sense. In particular, the occupation time of $X$ at $\mathsf{v}$ is given by
		\begin{align}

		\int_0^t \mathbf{1}_{\{X(s) = \mathsf{v}\}}\, ds = \eta \ell_X(t) \quad \textnormal{almost surely for every } t > 0.
		\end{align}

