[Lemma eq:one_arm_isolation of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:one_arm_isolation}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.

    Let $b \in \mathbf{N}$, $\mathbf{m} \in \mathbf{N}^b$, and let $\mathbf{B} = (B_0,\ldots,B_{b-1}) \in \mathcal{A}(b, \mathbf{m})$ be a set of blocks.

    For $\ell \leq b$ and $I = \{i_0,\ldots,i_{\ell - 1}\} \subseteq [0,b-1]$, let $\mathbf{B}' = (B_{i_0},\ldots,B_{i_{\ell - 1}}) \subseteq \mathbf{B}$ be a subset of blocks.

    Then there exists $c = c(G,J) > 0$ such that

    \begin{equation}

        \mathbf{P}_{\beta}
        \left(
            \mathbf{B}'
            \text{ is }
            \mathcal{B}(K)
            \text{-isolated}
            \mid
            \mathcal{B}(K)
            =
            \mathbf{B}
        \right) 
        \leq
        \prod_{i\in I} \exp(-c\beta m_i).
    \end{equation}

[Proposition prop:remainderestimate of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Let $u$ be a URD solution to (equation eq:modeleqn of the paper) and $\tilde{L}$ the constant defined by ((eq:Ltilde of the paper)). Suppose that $|s-t|\leq \tilde{L}$,   then
     \begin{equation} 
      \omega_R(s,t) := \left\| R^u \right\|_{C^{\frac{1}{2\alpha}\textrm{-var}}([s,t];H^{-2})}^{\frac{1}{2\alpha}}
       \lesssim \left(1+ \left\| u \right\|_{L_T^\infty H}^{\frac{1}{2\alpha}}\right) \left[ \omega_\mu^{\frac{1}{2\alpha}}(s,t) +\omega_A(s,t) \right].
    \end{equation}

