[Definition of arXiv:2412.05030, 'Characterization of Subordinate Symmetric Markov Processes'] \begin{enumerate}[(i)]
    \item  We say that $(M,d,\mu)$ satisfies the volume doubling property (VD)
  if there exist constants $C \ge 1,d_2 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
    \frac{V(x,R)}{V(x,r)} \le C \left(\frac{R}{r}\right)^{d_2}.
  \end{equation}
  \item   We say that $(M,d,\mu)$ satisfies the reverse volume doubling property (RVD)
  if there exist constants $C > 0,d_1 > 0$ such that for all $x \in M$ and all $0 < r \le R$,
  \begin{equation}
   C \left(\frac{R}{r}\right)^{d_1} \le \frac{V(x,R)}{V(x,r)}.
  \end{equation}
  \end{enumerate}

[Lemma LB_lemma_1 of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $B_k := \{x \in \mathbb Z^d : \mathrm{D}_{\ell}(o, x) \le k \}$. Then, there exists a positive $C = C(d, \alpha, K, \ell)$ such that for any $m \ge 1$ and any $x \in \mathbb Z^d$ with $x \neq o$, we have
    \begin{align*}
        \mathbb P \left( \mathrm{D}_\ell(o, x) \le m \right) \le \lambda C \left(\frac{m}{|x|}\right)^{d + \alpha} \, \sum_{j=0}^{m-1} \mathbb{E} [|B_j|] \ \mathbb{E} [|B_{m-j-1}|].
    \end{align*}

