\[
\sigma_r^2 \;\geq\; c\, r^{2(1-H)}\Big[
     r^{\frac{3}{2}H}\Indi{\{d=1\}}
   + r^H\log(r)\Indi{\{d=2\}}
   + r^H\Indi{\{d\geq 3\}}
\Big].
\]

