[Theorem thm:hawkes-closure of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Fix a truncation level $m\in\mathbb{N}$. For all pairs $(r,w)$ satisfying
\begin{equation}
0\le r\le m,
\qquad
w\in\{0,1\}^{\ast},
\qquad
r+|w|\le m,
\end{equation}
define
\begin{equation}
Y_{r,w}(t)=\mathbb{E}\big[\lambda_t^r S_w(t)\big].
\end{equation}
Then the vector $Y^{(m)}(t)=(Y_{r,w}(t))_{r+|w|\le m}$ satisfies a finite-dimensional linear ordinary differential equation
\begin{equation}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}Y^{(m)}(t)=A_mY^{(m)}(t),
\qquad
Y_{r,\varnothing}(0)=\ell^r,
\qquad
Y_{r,w}(0)=0\quad(w\ne\varnothing),

\end{equation}
where the matrix entries are determined by the coordinate formula
\begin{align}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}Y_{r,w}
={}&
\mathbf 1_{\{w=v0\}}Y_{r,v}
+r\beta\mu\,Y_{r-1,w}-r\beta\,Y_{r,w}
\nonumber\\
&+
\sum_{j=0}^{r-1}\binom{r}{j}\alpha^{r-j}Y_{j+1,w}
+
\sum_{j=0}^{r}\binom{r}{j}\alpha^{r-j}
\sum_{k=1}^{\rho(w)}\frac{1}{k!}Y_{j+1,w^{[-k]}}.

\end{align}
Terms with negative intensity powers are omitted, so the drift term $r\beta\mu Y_{r-1,w}$ is absent when $r=0$. Consequently,
\begin{equation}
\mathbb{E}[\mathrm{Sig}^{M,(m)}(X)_{0,T}]
=
\big(Y_{0,w}(T)\big)_{|w|\le m}
=
\Pi_m\exp(TA_m)Y^{(m)}(0),
\end{equation}
where $\Pi_m$ selects the coordinates with $r=0$.

