[Definition def:liftdiffusion of arXiv:2505.12187, 'Speeding up quantum Markov processes through lifting'] Let $P_t = \exp(tL)$ and $\hat{P}_t = \exp(t \hat{L})$ be the Markov diffusion processes defined as above. We say that $\hat{P}_t$ is a lift of $P_t$ if
    it holds that $\dom(L) \subset \dom(\hat{L})$, and 
        \begin{align} 
            \langle f \circ \pi, \hat{L} (g \circ \pi)  \rangle_{L^2(\hat{\mu})} = 0\,,\quad \forall f \in L^2(\mathcal{S},\mu)\,,\ g \circ \pi \in \dom(\hat{L})\,,
        \end{align}
    and for a positive bounded operator $\mathsf{S}: L^2(\mathcal{S}, \mu)^\perp \to L^2(\mathcal{S}, \mu)^\perp$, 
    \begin{align} 
        \langle \hat{L}(f \circ \pi), \mathsf{S}\, \hat{L} (g \circ \pi)  \rangle_{L^2(\hat{\mu})} = - \langle f, L g  \rangle_{L^2(\mu)}\,, \quad \forall f \circ \pi \in \dom(\hat{L})\,,\ g \in \dom (L)\,.
    \end{align}

[Proposition lem:29 of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose  that there exist $\lambda, C>0$ and $r\in {\mathbb N}$  such that for every $\mu \in 
		\mathcal{P}_{p}({\mathbb R}^d)$and every $k>r$
		\begin{equation}  
			\qquad\qquad\qquad \left\Vert \Theta_{k}(\mu )\right\Vert _{p}^{p}\leq
			(1-\lambda \gamma _{k})\left\Vert \mu \right\Vert _{p}^{p}+C\gamma _{k}.
		\end{equation}
		Then for every $k\geq r$,
		\begin{equation*}  
			{\mathbb{E}}[|X_{r,k}(X)|^p]=\left\Vert \Theta_{t_{r},t_{k}}^{\pi
			}(\mu)\right\Vert _{p}^p\leq e^{-\lambda(t_{k}-t_r)}\left\Vert \mu\right\Vert
			_{p}^p+C_{\lambda}.
		\end{equation*}
		Here $\mathcal{L}(X)=\mu$ and $C_{\lambda}$ is a constant depending on $\lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 34 (L\'{e}pingle's inequality) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] For every $q\in[1,\infty)$, there exists a constant $C_q<\infty$ such that, for every $p>2$, and every martingale $M:[0,\infty)\rightarrow\mathbb{R}^d$, we have
    \begin{equation*}
        \mathbb{E}\left[\sup_D\left(\sum_{i=0}^{n-1} \Big\lVert M_{t_{i+1}}-M_{t_i}\Big\rVert^p_{\mathbb{R}^d}\right)^{q/p}\right] \leq C_q\frac{p}{p-2}\mathbb{E}\left[\lVert M\rVert^q_{\infty}\right]
    \end{equation*}
    where $D$ is a partition of $[0,\infty)$.

[Definition 6 (Iterative oriented graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the vertex set $V=\{v_1,\ldots,v_n\}$, consider degree sequences $\d=(d_1,\ldots,d_n)$ and $\d'=(d_1',\ldots,d_{n}')$ of non-negative integers with $m:=d_1+\ldots+d_n=d_1'+\ldots+d_{n}'>0$, and consider a set $X$ of forbidden arcs.
		\begin{itemize}
			\item Start with no edges $E_0=\emptyset$.
			\item For $r=0,\ldots,m-1$, let $d_{i,r}$ and $d_{i,r}'$ denote the out- and in-degrees of vertex $v_i$ in $(V,E_r)$, and consider those pairs of vertices $(v_i,v_j)\in V^2$ with $i\neq j$, $d_{i,r}<d_i$, $d_{j,r}'<d_j'$, $(v_i,v_j)\not\in E_r\cup X$, and $(v_j,v_i)\not\in E_r$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}=E_r$.
				\item Otherwise, choose such a pair $(v_i,v_j)$ at random with probability proportional to $(d_i-d_{i,r})(d_j'-d_{j,r}')(1-\tfrac{d_id_j'}{2m})$, and let $E_{r+1}=E_r\cup\{(v_i,v_j)\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ arcs.
		\end{itemize}
		This guarantees that $(V,E)$ is an oriented graph with out- and in-degree sequences $\d$ and $\d'$ and with no arcs from $X$.

[Definition 21 of arXiv:2606.07290, 'Boundary behaviour of the Volterra square-root process'] For $\gamma \in (0,1]$, the function space $S_{L, \gamma}$ consists of all functions $f \in C_{\mathrm{loc}}^{\gamma}(0, T] \cap L^1(0, T)$ such that $L \ast f \in C^1(0,T])$. For $f \in S_{L,\gamma}$, the generalized fractional derivative is defined for $t \in (0, T]$ as:
    \begin{equation}
        (D_L f)(t) = \frac{\mathrm{d}}{\mathrm{d}t} \int_0^t L(t-s)f(s)\, \mathrm{d}s
    \end{equation}

[Lemma lem:fringe tree count of arXiv:2606.24465, 'History estimation in random recursive trees:\\Pointwise approach via iterated Jordan cent'] Let $\ell, n\in\mathbb{N}$, and assume $r\ge 20\tfrac{n}{\ell}$. Then, 
    \[
    \mathbb{P}\left(N_n^\mathrm{Fr}(\ell, 2\ell] \ge r\right)\le 27e^{-0.04r}.
    \]
    \begin{proof}
        The statement is clear for $\ell \geq n$, since $N_n^\mathrm{Fr}(\ell, 2\ell]=0$ for $\ell \geq n$. Thus, assume that $\ell < n$ for the rest of the proof.
        We work under the fringe-tree splitting construction. Recall that $A_n^\prime$ denotes the set of occupied Ulam--Harris nodes in the tree of size $n$ that are not the root.
        Let 
        \begin{align*}
            B_1&:=\big\{(u,i)\in A_n^\prime: \mathrm{Fr}_n\left((u,i)\right)\in(\ell, 2\ell]\big\}, \\
            B_2&:=\big\{(u,i)\in A_n^\prime: \mathrm{Fr}_n(u)\ge \ell+1, \ \mathrm{Fr}_n\left((u,i)\right)\in[\ell/2, \ell]\big\}.
        \end{align*}
        The lemma aims to establish an upper bound on the size of the set $B_1$. The set $B_2$ will assist with this. Note that $B_1\cup B_2$ is the set of nodes that are not the root, whose fringe size lies in $(\ell/2, 2\ell]$, and whose parents have fringe size at least $\ell+1$. We bound 
        \begin{align*}
            \mathbb{P}\left(N_n^\mathrm{Fr}(\ell, 2\ell] \ge r\right)& \leq \sum_{t=r-1}^\infty\mathbb{P}\left(|B_1|+|B_2|=t, |B_1|\ge r-1\right)\\ &
            \leq \sum_{t=r-1}^\infty\big(\mathbb{P}\left(|B_1|\ge 4t/5, |B_1|+|B_2|=t\right)+\mathbb{P}\left(|B_2| > t/5, |B_1|+|B_2|=t\right) \big).
        \end{align*}
        The fringe trees attached to vertices in $B_2$ are disjoint, as a node with fringe-tree size at most $\ell$ can never have a descendant with fringe-tree size strictly larger than $\ell$. Thus, $|B_2|\cdot \ell/2 \le n$, which is equivalent to $|B_2|\le 2n/\ell$. As $t\ge r-1\ge 20n/\ell-1 > 10n/\ell$ by assumption, the second probability in the sum is equal to 0 for all $t \geq r-1$. Thus, 
        \[
        \mathbb{P}\left(N_n^\mathrm{Fr}(\ell, 2\ell] \ge r\right) \le \sum_{t=r-1}^\infty\mathbb{P}\left(|B_1|\ge 4t/5, |B_1|+|B_2|=t\right).
        \]

        For $1\leq i \leq n$, let $\{ u^i_1,\ldots,u^i_{n^i}\}= [n]^i$ in lexicographic ordering  and let $\{ v_1,\ldots,v_{K} \} = \bigcup_{i=1}^n [n]^i$ with $K=\sum_{i=1}^n n^i$, so that the level of $v_j$, i.e., the unique value $i\in [n]$ s.t. $v_j \in [n]^i$, is non-decreasing in $j$, and so that each block $[n]^i$ is in the lexicographic ordering.
        The sets $B_1$ and $B_2$ can be constructed iteratively via the fringe-tree splitting construction, by sampling fringe-tree sizes of the vertices $v_1,\ldots,v_K$. Let $B_1^j$ and $B_2^j$ be the sets
        \begin{align*}
            B_1(j)& := \big\{(u,i)\in \{v_1,\ldots,v_j\} : \mathrm{Fr}_n\left((u,i)\right)\in(\ell, 2\ell]\big\}, \\
            B_2(j)& := \big\{(u,i)\in \{v_1,\ldots,v_j\} : \mathrm{Fr}_n(u)\ge \ell+1, \ \mathrm{Fr}_n\left((u,i)\right)\in[\ell/2, \ell]\big\}
        \end{align*}

        Let $v_j=(u,i)$ and suppose that we reveal the uniform random variable $X_i = \mathrm{Fr}_n((u,i))$ in~(equation eq:uniform-splitting of the paper) determining the fringe-tree size of $(u,i)$ in two stages: first we reveal whether $X_i\in[\ell/2, 2\ell]$, then conditional on this event we sample whether $(u,i)$ belongs to $B_1$ or $B_2$; independently of the past, we have that $X_i\in[\ell/2, \ell]$ with probability at least $1/3$ as $X_i$ is uniform on $[\ell/2, (2\ell)\wedge R_i]$. As a result, we can couple $|B_1(j)|, |B_2(j)|$ with a sequence of i.i.d. Bernoulli(1/3)-distributed random variables $Y_1,Y_2,\ldots$ so that
        \begin{equation*}
            |B_2(j)| \geq \sum_{\ell=1}^{|B_1(j)| + |B_2(j)|} Y_\ell 
        \end{equation*}
        for all $j=1,\ldots,K$. Since $|B_1(K)|=|B_1|$ and $|B_2(K)|=|B_2|$, this implies that

        \begin{align*}
            \mathbb{P}\left(N_n^\mathrm{Fr}(\ell, 2\ell] \ge r\right)
            &\leq \sum_{t=r-1}^\infty\mathbb{P}\left(|B_1|\ge \tfrac{4}{5}t, |B_1|+|B_2|=t\right)\\
            &= \sum_{t=r-1}^\infty\mathb (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary qnform of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Retain the setting of Lemma (lemma:mshe of the paper) and Corollary (corollary:mshe of the paper). We have the following for any index {\small$\i=0,1,2$}, which uses notation to be explained afterwards:

\begin{align}
[\mathscr{S}^{N}\star(\mathfrak{e}_{\i}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}\d\t&=N\sum_{\n_{1}=1,\ldots,\mathrm{K}_{1}}\mathrm{c}_{\n_{1}}[\mathscr{S}^{N}\star(\mathfrak{q}_{\n_{1}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}\d\t\\
&+N\sum_{\n_{2}=\mathrm{K}_{1}+1,\ldots,\mathrm{K}_{2}}\sum_{|\mathfrak{l}_{0}|\leq1}\mathrm{c}_{\n_{2}}\cdot N\grad^{\mathbf{X}}_{\mathfrak{l}_{0}}[\mathscr{S}^{N}\star(\mathfrak{q}_{\n_{2}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot})]_{\x}\d\t.
\end{align}

\begin{itemize}
\item Above, {\small$\mathrm{K}_{1}\leq\mathrm{K}_{2}$} are uniformly bounded positive integers, and {\small$\mathrm{c}_{\n_{1}},\mathrm{c}_{\n_{2}}=\mathrm{O}(1)$} are deterministic.
\item The functions {\small$\mathfrak{q}_{\n}$} are admissible in the sense of Definition (definition:admissible of the paper).
\end{itemize}

