[Theorem cor of arXiv:2411.01731, '$L^2$-Wasserstein contraction of modified Euler schemes for SDEs with high diffusivity and'] Assume that $(i)$ $({\bf A}_0)$ with $\ell_0=0$, $({\bf A}_{4})$ and $({\bf A}_{5})$ with $\ell_0^\star=0$ for the EM scheme (equation WW of the paper);   $(ii)$ $({\bf A}_0)$, $({\bf A}_2)$ and $({\bf A}_{3})$ for the TEM scheme (equation EW0- of the paper);   $(iii)$ $({\bf A}_0)$, $({\bf A}_{4})$ and $({\bf A}_{5})$ for the PEM scheme (equation EWW of the paper). Then, there exist constants $C_0,\sigma_0,\lambda>0, \delta_2^{\star}\in(0,1]$ such that for all  $\delta\in(0,\delta_2^{\star}]$,   $\mu\in \mathscr P_2(\mathds R^d)$, and the noise intensity $\sigma$ satisfying $|\sigma|\ge\sigma_0,$
\begin{align}
\mathbb{W}_{2}\big(\pi_\8,\pi_\8^{(\delta)}\big)\le  C_0 \delta^{ \gamma_\star}  d^{\ell_\star},
\end{align}
and
\begin{align}
\mathbb{W}_2(\mu P^{(\delta)}_{n\delta},\pi_\8)\le C_0 \big(\text{\rm{e}}^{-\lambda n\delta}	\mathbb{W}_2(\mu,\pi_\8)+\delta^{\gamma_\star}d^{\ell_\star}\big),
\end{align}
where $\pi_\8$ $($resp. $\pi_\8^{(\delta)}$$)$ is the unique IPM  of $(X_t)_{t\ge0}$ $($resp. $(X_{n\delta}^{\delta})_{n\ge0}$$)$, and
 $\gamma_\star=1,\ell_\star=1/2$  for the EM scheme (equation WW of the paper); $\gamma_\star=\gamma, \ell_\star=\ell_0+1/2$ for the TEM scheme (equation EW0- of the paper); $\gamma_\star=1,\ell_\star=(\ell_0+1+{\ell_0^\star}/2)\vee((\ell_0+1)/2+\ell_0/\gamma)$ for the PEM scheme (equation EWW of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:equivalenceofensembles of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] Let $f:\Omega\longrightarrow\mathbb{R}$ be a local function whose support is included in $\{0,\hdots ,\ell_0-1\}$ for some $\ell_0\ge 1$. Then, there exists a constant $C_1=C_1(f)>0$ such that for any $\ell\ge\ell_0$, 
    \begin{equation}
        \sup_{\eta\in\Omega}\left| \mathbb{E}_\ell [f] - \left(\psi_f(\xi_0^\ell ,\eta_0^\ell ) - \frac{1}{2\ell }\mathrm{Tr}\big( \chi \mathrm{Hess}(\psi_f)\big) (\xi_0^\ell ,\eta_0^\ell)\right)\right| \le \frac{C_1}{\ell^2}.
    \end{equation}
    where $\chi$ is the compressibility matrix defined in (defin:compressibilitymatrix of the paper), and $\mathrm{Hess}(\psi_f)$ denotes the Hessian matrix of $\psi_f$.

[Proposition 22 of arXiv:2609.03512, ''] Let $g(G)=3$ and $r(G)=5$. Then $\gamma(G)=\gamma_t(G)=2$ if and only if $G$ belongs to one of the following classes:
\begin{enumerate}
\item $G\in\mathcal{M}\bigl(D_2,D_5,D_6,D_8,D_9,D_{11},D_{12},D_{13},D_{14},D_{16},D_{17},D_{19}\bigr)$; or
\item $G\in\mathcal{M}\bigl(D_{10},D_{15},D_{18},D_{20},D_{21},D_{22},D_{24}\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.
\end{enumerate}

[Definition Ideal $F/R$-Step of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] For a block-step $t$ in a trace walk of backbone-correction shapes from the current boundary vertex $U_{t}=u$ to the next boundary vertex $V_{t} =v$, we classify it as following:
\begin{enumerate}
\item Ideal-$F$-step:  There is a subsequent step (possibly an $S$-step to be defined) with the same underlying edges-set, i.e. there is some step $t'>t$ s.t. $E(\tau_t) = E(\tau_{t'})$. 
\item   Ideal-$R$-step: There is a a prior step (possibly an $S$-step) with the same underlying edges-set, i.e. there is some step $t'<t$ s.t. $E(\tau_t) = E(\tau_{t'})$ (pick $t'$ to be the smallest one if there are multiple).
 \item Any other $F/R$ step is a \emph{non-ideal} F/R-step.

\end{enumerate}

[Definition 34 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] For $p \in [1, \infty]$, we define the $L^{p}$-spectral radius $\lambda_{p}(\theta\mu)$ as
  \begin{align*}
    \lambda_{p}(\theta\mu) := - \lim_{t \to \infty} \frac{1}{t} \log \|P_{t}^{\theta\mu}\|_{p,p}.
  \end{align*}

