[Theorem 4 of arXiv:2510.24562, 'Hard wall repulsion for the discrete Gaussian free field in random environment on $\mathbb'] Recall $L \geq 1$, $K \geq 100$ are integers. Then, for all $r=r(L)>0$ such that $r(L)\to \infty$ as $L \to \infty$, all $b=b(L)>0$ bounded sequences, and for every $\beta \geq 0$,
    \begin{equation}
        \limsup_{L \to \infty } \sup_{\omega \in \Omega_{\lambda,\Lambda}} \sup_{\cS} \sup_{f \in \cF} \sup_{x \in \bbZ^d} \Big\{ r^{d-2}\bbV\mathrm{ar}^\omega[Z^\omega_{f,\beta,b}] - \frac{r^{d-2}}{\capa^\omega (S)}\alpha^\omega_{K,L,\beta,b}\Big\} \leq c_6 \beta^2  \,,
    \end{equation}
    where $\bbV\mathrm{ar}^\omega$ is the variance associated with $\bbP^\omega$, and
    \begin{equation}
        \alpha_{K,L,\beta,b}^\omega = b^2 -2\beta b \langle h^\omega_S ,\eta^\omega_{x,r} \rangle + \cR_{K,L,\beta,b} \,,
    \end{equation}
    with
    \begin{align}

        &0\leq \cR_{K,L,\beta,b} \leq b^2 U(K,L) + 2b\beta \Big[U(K,L) + \langle \IND_{\cU} ,\eta^\omega_{x,r} \rangle \Big] \,,\\

        &\cU = \bigcup_{z\in \cS} U_z\,,\qquad\lim_{K \to \infty} \limsup_{L \to \infty} U(K,L) = 0 \,,\qquad U(K,L) \geq 0 \,.
    \end{align}
    Moreover,
    \begin{equation}
        \sup_{L} \sup_{\omega \in \Omega_{\lambda,\Lambda}} \sup_{\cS} |\bbE^\omega[Z^\omega]| \left( \frac{\capa^\omega (S)}{|\cS|} \right)^{1/2} \leq \frac{c_7}{K^{c_8}} \,.
    \end{equation}

