[Lemma volt-04 of arXiv:2606.25336, '\bfseries Invariant Measures of L\'evy-driven Stochastic Differential Equations'] Let $d\geq 2$ and $P$ the Newton potential. If $F\in C^1({\mathds{R}^d},{\mathds{R}^d})$ is such that $\operatorname{div} F$ is Hölder continuous for some $\alpha\in (0,1]$ and
	\begin{itemize}
		\item $\operatorname{div} F\in L_1$ for $d\geq 3$,
		\item $\Lambda^\epsilon \operatorname{div} F\in L_1$ for some $\epsilon>0$ for $d=2$,
	\end{itemize}
	then $F^{\mathsf{sol}}:= F - \nabla P*\operatorname{div} F$ is divergence-free and we define 
	\begin{gather}
		F^{\mathsf{irr}}:=\nabla P*\operatorname{div} F 
		\quad\text{and}\quad
		F^{\mathsf{sol}}:= F-\nabla P*\operatorname{div} F.
	\end{gather}

