[Proposition 9 of arXiv:2608.06038, 'Efron type identities\\ for stopping sets and Poisson hulls'] Assume that $Z$ is a Markov set and let $B\in\cX$
  such that $\BP(\lambda_{Z^c}(B)<\infty)=1$. Let $k,l\in\N_0$. Then
  \begin{align} 
    \BE \big[\eta_{Z^c}(B)^{(k)}\lambda_{Z^c}(B)^l\big]
    =\BE \lambda_{Z^c}(B)^{k+l}=\BE \eta_{Z^c}(B)^{(k+l)}.
  \end{align}

[Theorem 5 (Rough case) of arXiv:2606.07290, 'Boundary behaviour of the Volterra square-root process'] Suppose that $K$ is regularly varying at zero, i.e., \eqref{eq: regularly varying} holds with $\alpha \in (1/2,1)$ and a slowly varying function $\ell > 0$. Define the constants
    \begin{align*}
        C_*(\alpha) = 2(2\alpha-1)\frac{\Gamma(1-\alpha)}{\Gamma(2-2\alpha)} \qquad \text{ and }\qquad C^*(\alpha) = \frac{\Gamma(3\alpha-1)}{2\Gamma(2\alpha-1)},
    \end{align*}
    and the time-dependent function
    \begin{align*}
        \Lambda_{\alpha}(t) = x_0 \frac{\Gamma(1-\alpha)}{\Gamma(2 - 2\alpha)}\frac{t^{1-2\alpha}}{\ell(t)^2} + \frac{b}{1-\alpha}\frac{t^{1-\alpha}}{\ell(t)}.
    \end{align*}
    Then for any $\varepsilon \in (0,1)$, there exists $t_0 > 0$ such that for all $t \in (0,t_0)$, the atom at zero satisfies the local bounds
    \begin{align*}
        \exp\bigg( - (1-\varepsilon)\frac{C^*(\alpha)\Lambda_{\alpha}(t)}{\sigma^2} \bigg) \geq \mathbb{P}[X_t = 0] \geq \exp\left( - (1+\varepsilon) \frac{C_*(\alpha)\Lambda_{\alpha}(t)}{\sigma^2} \right) > 0.
    \end{align*}
   For the pure fractional kernel $K(t) = \frac{t^{\alpha-1}}{\Gamma(\alpha)}$, we obtain for each $t > 0$ the global lower bound
    \begin{equation}
        \mathbb{P}[X_t = 0] \geq \exp\left( - \frac{C_*(\alpha)\Lambda_{\alpha}(t)}{\sigma^2} - \frac{2\beta}{\sigma^2}\mathbbm{1}_{\beta > 0} \left[ x_0 \frac{t^{1-\alpha}}{\Gamma(2-\alpha)} + b t \right] \right),
    \end{equation}
    where $\ell(t) \equiv 1$ in the evaluation of $\Lambda_\alpha(t)$. Finally, if $\beta = 0$, then we have the exact equality
    \[
        \mathbb{P}[X_t = 0] = \exp\left( - \frac{C_*(\alpha)\Lambda_{\alpha}(t)}{\sigma^2} \right).
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:errorEst of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Under the assumptions~((a:center of the paper))--((a:growth of the paper)) above, and with $n_0$ given by Lemma~(l:var-lower of the paper),
    there exists $Q_r < \infty$, such that for every $n, n'\ge n_0$, satisfying
    \begin{equation*}
        \frac{n}{2} \le n' \le 2n,
    \end{equation*}

we have
    \begin{equation}
        {\mathbb E}\, |r_{a;n, n'}|^{\textcolor{black}{2+{\varepsilon}}} <
        \left(\frac{Q_r}{\sqrt{n + n'}}\right)^{\textcolor{black}{2+{\varepsilon}}}

    \end{equation}

