body:
[Proposition prop: existence riccati of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Fix $\mathbf{u}\in \mathcal S^*$ and $\mathbf{v}$ such that $\exp(h_\mathbf{u})=h_\mathbf{v}$. Let $(\mathbf{c}(t))_{t\in [0,T]}$ be a solution of (equation eq:ODE sequence space holomorphic of the paper) for the initial condition $\mathbf{c}(0)=\mathbf{v}$. Assume that ${\bf c}(t)_{0}\neq0$ 
for each $t\in[0,T]$. Then there exists a solution of the Riccati equation (equation eq:ODE sequence space affine of the paper) with initial condition $\bm{\psi}(0)=\mathbf{u}$ given by
\begin{align*}
\bm\psi(t)_{0}&=\mathbf{u}_{0}+\int_0^t\frac{L{\bf c}(s)_{0}}{{\bf c}(s)_{0}}ds,\qquad
\text{and}\qquad {\bm\psi(t)}_\alpha=\Big(\sum_{k=1}^\infty{(-1)^{k-1}(k-1)! }{{\bf d}(t)^{* k}}\Big)_\alpha,
\end{align*}
for ${\bf d}(t)_{0}=0$ and ${\bf d}(t)_\alpha:={{\bf c}(t)_\alpha}/{{\bf c}(t)_{0}}$, for $|\alpha|>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm macro-cross of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume Assumption~(ass:weight of the paper), fix $\mathsf{u}\in(0,1/2)$, and let $T_n=T_n^{(\ell)}(0,\mathsf{u}_n)$.
\begin{enumeratea}
 \item 
 If $1\ll\ell\ll n/\log n$, then
 \begin{align*}
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n}T_n
 \stackrel{\pr}{\to}
 \frac1{\mathsf{v}^\star},
 \qquad
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n}\E T_n
 \to
 \frac1{\mathsf{v}^\star}.
 \end{align*}

 \item 
 If $\liminf_{n\to\infty}\frac{\ell\log n}{n} >0$ and $\ell\leqslant\frac n2,$
 then
 \begin{align*}
 T_n
 =
 \Theta_{\pr}\left(
 \frac{\log n}{\ell^{1/\theta}}
 \right),
 \qquad
 \E T_n
 =
 \Theta\left(
 \frac{\log n}{\ell^{1/\theta}}
 \right).
 \end{align*}

 \item 
 If $\ell/n\to\gl\in(0,1/2)$, then
 \begin{align*}
 \frac{\mathfrak{a}_\ell T_n}{\log n}
 \stackrel{\pr}{\to}
 1,
 \qquad
 \frac{\mathfrak{a}_\ell\E T_n}{\log n}
 \to
 1.
 \end{align*}
\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2604131506 of arXiv:2609.02626, 'Comparison principles and symmetry for subquadratic fractional $p$-Laplacian equations'] Let $N\ge 1$, $s\in (0, 1)$, $1<p<2$, $\mathcal{U}$ be an open set satisfying $\overline{\mathcal U} \Subset \mathbb{R}_+^N$, and $K\Subset \mathbb{R}^N_+\backslash \overline{\mathcal{U}}$. Then there exists  $C=C(\mathcal{U}, K, N, s, p)>0$  such that given any  $\delta>0$ and $v\in \widetilde{W}^{s,p}(\mathcal{U})\cap \widetilde{W}^{s,p}(\mathcal{T}(\mathcal{U}))\cap L^{\infty}(\mathbb{R}^N)$, if
\begin{equation}
|v(x)-v^*(x)|\le \Big[\frac{\beta (p-1)(2\|v\|_{L^{\infty}(K\cup \mathcal{U})}+\delta)^{p-2} \, {\rm dist}(\mathcal{U}, \mathcal{T}(K))^{N+sp}\delta}{2^{3-p}{\rm diam}(\mathcal{U}, K)^{N+sp}}\Big]^{\frac{1}{p-1}} \quad \mbox{in }\; \mathcal{U},
\end{equation}
with ${\rm diam}(\mathcal{U}, K)=\sup\{|x-y|: x\in \mathcal{U}, y\in K\}$ and
\begin{equation}
\beta:=1-\underset{x\in \mathcal{U}, y\in K}{\sup}\frac{|x-y|^{N+sp}}{|x-y^*|^{N+sp}}\in (0, 1),
\end{equation}
one has then, in weak sense,
\begin{align*}
& \quad (-\Delta)_p^s (v-\delta {\mathbbm 1}_{K})-(-\Delta)_p^s (v^*-\delta {\mathbbm 1}_{\mathcal{T}(K)})\\
&\ge  (-\Delta)_p^s v- (-\Delta)_p^s v^* + C(\|v\|_{L^{\infty}(K\cup \mathcal{U})}+\delta)^{p-2}\delta\quad \mbox{in }\; \mathcal{U}.
\end{align*}

