body:
[Theorem thm:twopointAT of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] Let $D$ be a simply-connected domain. Let $g\in\left((2-1/\sqrt{2})^2,(1+ 1/\sqrt{2})^2\right)\cup[4,+\infty)$ and let $E_{\varepsilon_1,\varepsilon_2}^{AT,g}$ denote the event that one of the CLE$_4$ gaskets obtained from the following iteration intersects both $\mathbb{D}(z_1,\varepsilon_1)$ and 
$\mathbb{D}(z_2, \varepsilon_2)$.
\begin{enumerate}
    \item We sample a CLE$_4$ gasket in $D$ to obtain $A_1$; 
\item Inside each connected component of $D \setminus A_1$, we sample a random gasket with the law of the two-valued set $A_{-2\sqrt{g}\lambda + 2\lambda, 2\lambda}$ to obtain $A_2$;
\item we then again sample CLE$_4$ inside each connected component of $A_2$ and iterate this way: on odd steps we sample CLE$_4$ gaskets, on even $A_{-2\sqrt{g}\lambda + 2\lambda, 2\lambda}$ gaskets.
\end{enumerate}
\begin{comment}
\begin{itemize}
    \item We start with the outermost CLE$_4$; 
\item next, towards the point $z_1$ we sample a two-valued set $A_{- 2\lambda, 2\sqrt{g}\lambda - 2\lambda}$ or $A_{-2\sqrt{g}\lambda+  2\lambda, + 2\lambda}$ depending on whether the label of the CLE$_4$ loop towards $z_1$ was $2\lambda$ or $-2\lambda$ respectively;
\item we then again sample CLE$_4$ and continue this way, making sure that on every even step we are at height $2\sqrt{g}\lambda\mathbb{Z}$.
\end{itemize}
\end{comment}
We then have that 
\begin{equation}
\lim_{\max(\varepsilon_1, \varepsilon_2) \to 0}(\varepsilon_1\varepsilon_2)^{-1/8}\mathbb{P}(E_{\varepsilon_1,\varepsilon_2}^{AT,g}) = 
C_{AT,g}
\CR(z_1,D)^{-1/8}\CR(z_2,D)^{-1/8}
\frac{\theta_3(q^{1/(2g)})}{\theta_2(q^{1/4})},
\end{equation}
where the nome $q$ is fixed by $\exp(\pi G_D(z_1,z_2)) = \frac{\theta_3(q^{1/2})}{\theta_2(q^{1/2})}$ and 
$C_{AT, g} = \frac{\pi^{1/4} (\mathbf{C}_{\rm{SLE}4}^{\rm loop})^2}{2^{5/4}\sqrt{g}}$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 (Preservation of the $\tau$-bi-Ricci pinching under surgery) of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] Fix $\tau\in\mathcal I_n$ and an initial quantitative pinching constant
  $\alpha_0^{\mathrm{in}}>0$.  There exist surgery parameters
  $B>1$ and $0<\delta_0<1$, and constants
  \begin{equation*}
  \eps_b>0,\qquad
  k_b\geq2,\qquad
  L_b\geq40,\qquad
  r_b>0,
  \end{equation*}
  together with
  \begin{equation*}
  0<\alpha_0^*\leq\alpha_0^{\mathrm{in}},
  \qquad
  c_b>0,
  \end{equation*}
  depending only on $n$, $\tau$, $\alpha_0^{\mathrm{in}}$, and the fixed
  standard cap, with the following property.

  Suppose that a standard replacement is performed on an
  $(\eps,k,L)$-neck of radius $r$ satisfying
  \begin{equation*}
  \eps\leq\eps_b,\qquad
  k\geq k_b,\qquad
  L\geq L_b,\qquad
  r\leq r_b,
  \end{equation*}
  and suppose that on the incoming neck the reduced pinching inequality
  \begin{equation}
    P_{ij}^{(\tau)}
    \geq
    \alpha_0^*H|\lambda_p-\lambda_q|
  \end{equation}
  for every $i\ne j$ and all $p,q$.  Then every changed point after surgery
  satisfies
  \begin{equation}
    \widetilde P_{ij}^{(\tau)}
    \geq
    \alpha_0^*\widetilde H
    |\widetilde\lambda_p-\widetilde\lambda_q|
  \end{equation}
  for every $i\ne j$ and all $p,q$.  Moreover,
  \begin{equation}
    \widetilde P_{ij}^{(\tau)}
    \geq c_b r^{-2},
    \qquad
    \widetilde H\geq c_b r^{-1}
  \end{equation}
  throughout the changed region.

[Prop 10 ($L_p$ version of the Prékopa-Leindler inequality) of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] Let $p\ge 1$, $s,\mu,\omega>0,$ and $f,g,h:\mathbb{R}^n\to [0,\infty)$ be integrable functions with nonepmty supports. If for all $x\in \operatorname{supp}f, y\in\operatorname{supp}g$ and $\lambda\in [0,1]$,
  \begin{equation*}
      h((1-\lambda)^{\frac{1}{q}}\mu^\frac{1}{p} x+\lambda^{\frac{1}{q}}\omega^\frac{1}{p} y)^{\frac{1}{s}}\geq (1-\lambda)^{\frac{1}{q}}\mu^\frac{1}{p} f(x)^{\frac{1}{s}}+\lambda^{\frac{1}{q}}\omega^\frac{1}{p} g(y)^{\frac{1}{s}},
      \end{equation*}
  where $q$ is the Hölder conjugate of $p$,
  then
  \begin{equation*}
      \left(\int_{\mathbb{R}^n}  h~dx\right)^{\frac{p}{n+s}} \geq \mu\left(\int_{\mathbb{R}^n}  f~dx\right)^{\frac{p}{n+s}}+\omega\left(\int_{\mathbb{R}^n}  g~dx\right)^{\frac{p}{n+s}}.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.26619, 'Uniqueness of Positively Curved Ancient Ricci Flows on Surfaces with Boundary'] Our constructed old solutions $u_i(\psi,t)$ satisfy
\begin{gather}
R_i(0,t)\leq \frac{2}{u_i(\hpi,t)} - 2k^2\leq R_i(\hpi,t),\\
{1 - k^2u_i\parent{\hpi,t}} \leq e^{2k^2t},\\
u_i(0,t)\leq \frac{u_i(\hpi,t)}{\parent{1+k\sqrt{u_i(\hpi,t})}^2}.
\end{gather}

[Lemma lem-good-event-E-1 of arXiv:2607.22324, 'The conclave process'] {}
    Suppose $\alpha \in [1, +\infty)$ and $R$ is a fixed constant. Define $\mathcal E_{(lem-good-event-E-1 of the paper)}=\mathcal E_{(lem-event-E-diamond of the paper)} \cap \mathcal E_{\star}$, where 
    \begin{align*}
         \mathcal E_{\star} = \left\{ \mathbf Z_{\mathbf X_k} \leq n(200\alpha)^{2R^2\alpha^R}, 1\leq k \leq R \right\} \,.
    \end{align*}
    We then have $\mathbb P^{\alpha}_n(\mathcal E_{(lem-good-event-E-1 of the paper)})=1-o(n^{-\tfrac{1}{2}})$.

