[Theorem 3 (\cite{BS2024}) of arXiv:2604.00882, 'On some extensions of generalized counting processes'] The process ${M}^{\psi,f}$ has probability distribution function
   	 \begin{equation}
   	          \tilde{p}_n^{\psi,f}(t)=\sum_{\Omega(k,n)}^{}\prod_{j=1}^{k}\frac{\lambda_j ^{x_j}}{x_j!}\left(-\partial_{\Lambda}\right)^{z_k}\tilde{\ell}_f(t,\psi (\Lambda)), \, n\ge 0,
    	\end{equation}
    	and $\tilde{p}_n^{\psi,f}(t)$ satisfy the following equation
    	\begin{equation}
   		 \mathcal{D}^f_t \tilde{p}_n^{\psi,f}(t)=-\psi(\Lambda)\tilde{p}_n^{\psi,f}(t) -\sum_{m=1}^{n}\sum_{\Omega(k,m)}^{}\psi^{(z_k)}\left(\Lambda\right) \prod_{j=1}^{k}\frac{(-\lambda_j )^{x_j}}{x_j!}\tilde{p}_{n-m}^{\psi,f}(t),, \, n\ge 0, \,t>0,
  	\end{equation}
   	 with initial conditions 
    \begin{equation*}
         \tilde{p}_n^{\psi,f}(0)=
         \begin{cases}
                1,\quad n=0,\\
                0,\quad n\geq1.\\
         \end{cases}
     \end{equation*}
        The probability generating function of the process ${M}^{\psi,f}$ is of the form
\begin{equation}
             \tilde G^{\psi,f}(u,t)=\tilde \ell_f\Big(t, \psi\Big(\sum_{j=1}^{k}\lambda_j(1-u^j)\Big)\Big),\, |u|<1,
\end{equation}
and satisfies the equation
\begin{equation}
        	\mathcal{D}^f_t \tilde G^{\psi,f}(u,t)=-\psi\Big(\sum_{j=1}^{k}\lambda_j(1-u^j)\Big)\tilde G^{\psi,f}(u,t)
    \end{equation}
    with $\tilde G^{\psi,f}(u,0)=1$.
    The derivatives used in \eqref{Dtfpn} and \eqref{DftG} are the C-D convolution-type derivatives defined in \eqref{fDt}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2606.22526, 'The conditional expectation of the product of the first $n-1$ Hermite polynomials in a mul'] Let $n-$dimensional random vector be normal with $N\left(
\mathbf{0},\mathbf{\Sigma}\right)  ,$ where $\mathbf{\Sigma\allowbreak
=\allowbreak\lbrack}\rho_{j.k}]$ with $\rho_{j,j}\allowbreak=\allowbreak1.$

By $\mathbf{\rho}$ let us denote the $n-1$- dimensional vector with entries
$\left(  \rho_{1,n},\ldots,\rho_{n-1,n}\right)  $ and by $\mathbf{\Sigma}_{c}$
the $(n-1)\times(n-1)$ matrix defined by $[\rho_{k,j}-\rho_{k,n}\rho
_{j,n}]_{j,k=1,\ldots,n-1}$. Notice that the diagonal of this matrix takes on
values $1-\rho_{i,n}^{2}$ for $i\allowbreak=\allowbreak1,\ldots,n-1.$ Let us
denote for simplicity
\begin{equation}
\hat{C}_{k_{1},\ldots k_{n-1}}\allowbreak=\allowbreak C_{k_{1},\ldots,k_{n-1}
}^{(n-1)}(\mathbf{D\Sigma}_{c}\mathbf{D})\prod_{j=1}^{n-1}\left(  \sqrt
{1-\rho_{j,n}^{2}}\right)  ^{k_{j}}, 
\end{equation}
for $k_{j}\geq0,$ $j=1,\ldots,n-1$, where $\mathbf{D}$ is an $(n-1)\times
(n-1)$ diagonal matrix with $1/\sqrt{1-\rho_{j,n}^{2}}$ as an $j-th$ element
of the diagonal.

Then the conditional expectations
\[
h_{k_{1}\ldots,k_{n-1}}(\mathbf{\Sigma,}z\mathbf{)\allowbreak=\allowbreak
}E\left(  \prod_{j=1}^{n-1}H_{k_{j}}(X_{j})|X_{n}=z\right)
\]
are equal to
\begin{equation}
h_{k_{1}\ldots,k_{n-1}}(\mathbf{\Sigma,}z\mathbf{)\allowbreak}=\sum_{s_{1}
=0}^{k_{1}}\ldots\sum_{s_{n-1}=0}^{k_{n-1}}\hat{C}_{s_{1},\ldots s_{n-1}}
\prod_{j=1}^{n-1}\binom{k_{j}}{s_{j}}\rho_{j,n}^{k_{j}-s_{j}}H_{k_{j}-s_{j}
}(z), 
\end{equation}
Moreover, polynomials $h_{k_{1}\ldots,k_{n-1}}$ satisfy the following system
of equations:
\begin{equation}
\sum_{s_{1}=0}^{k_{1}}\ldots\sum_{s_{n-1}=0}^{k_{n-1}}h_{s_{1}\ldots,s_{n-1}
}(\mathbf{\Sigma,}z\mathbf{)}\prod_{j=1}^{n-1}\binom{k_{j}}{s_{j}}\left(
i\rho_{j,n}\right)  ^{k_{j}-s_{j}}H_{k_{j}-s_{j}}(iz)=\hat{C}_{k_{1}
,\ldots,k_{n-1}}, 
\end{equation}

