[Theorema WPFLS of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] \
\begin{enumerate}
\item Gr\"unrock [Grunrock] proved (equation NLS of the paper) is:
\begin{itemize}
    \item[-] LWP for $\alpha=3$ and $1<p<\infty$. 
    \item[-] GWP  for $\alpha=3$ and $5/3<p<2$. 
\end{itemize}    
    \item Hyakuna-Tsutsumi [hyakuna2012existence] proved (equation NLS of the paper) is:
    \begin{itemize}
     \item[-] LWP for $\alpha \in (1,5)$, $4/3<p<2$ or $2<p<\infty.$ 
    \item[-] GWP for $\alpha \in (1,5)$, $4/3<p<2$ or $2<p<\infty,$ with $p$ sufficiently close to 2.    
\end{itemize}
\item Masaki-Segata [Masaki1] established LWP for $4/3<p<4$ and $p=\alpha+1$.
\item Bhimani-Carles [BhimaniNorm] proved (equation NLS of the paper) is
\begin{itemize}
    \item[-] strong ill-posedness below the expected critical regularities ($s<s_{c}$).
\item[-] norm inflation with infinite loss of regularity. 
\end{itemize}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] We say a partially ordered space~$(X,\leq)$ is:
	\begin{itemize}
		\item a \emph{Priestley space} if~$X$ is Stone and \emph{Priestley separation} holds: for all $x\not\leq y$ there exists a clopen $U=\up U$ such that~$x\in U$ and~$y\notin U$;
		\item an \emph{Esakia space} if it is a Priestley space and~$\down$~preserves open subsets.
	\end{itemize}

[Lemma 38 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{27}>0$, which depends on the following values:

\begin{equation*}
T, \quad \|u_0\|_{H^1(\Omega)}, \quad \|v_0\|_{H^1(\Omega)}, \quad \|w_0\|_{H^1 (\Omega)},
\end{equation*}

such that the following uniform estimate holds:

\begin{align*}
&\sup_{\delta \in (1,\infty)} \left\{ \left( \sup_{0 \le t \le T} \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)}\right)^2+
\int_0^T \|u_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2dt\right.\\
&\hspace*{2.5cm}\left.+\left( \sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^1(\Omega)}\right)^2+
\int_0^T \|w_{\text{{\tiny $\delta$}}}(t)\|_{H^2(\Omega)}^2dt\right\} \le C_{27}.
\end{align*}

