[Lem 2 of arXiv:2510.25151, '$L^{\alpha-1}$ distance between two one-dimensional stochastic differential equations with'] Let $u(x)=|x|^{\alpha-1}$ and $\alpha\in(1,2)$. For any $\eps >0$ and $\delta>1$, one can construct a smooth function $\pde$ such that:
\begin{itemize}
    \item[(i)] $\pde$ is supported on $\left[\eps\delta^{-1}, \eps\right]$ and satisfies $\int_{\eps\delta^{-1}}^{\eps} \pde(y) dy=1$, and is bounded by
    \begin{align*}
0\le \pde(x) \le 2(x \log \delta)^{-1}\quad \textrm{for~}x\in\left[\eps\delta^{-1}, \eps\right] .
\end{align*}
    \item[(ii)] The mollified function $u_{\delta,\eps} = u \ast \pde$ is of class $C^2$ and satisfies the following inequalities for all $x\in\real$:
    \begin{align}
        |x|^{\alpha-1} &\le \eps^{\alpha-1} + u_{\delta,\eps}(x),  \\
        u_{\delta,\eps}(x) &\le |x|^{\alpha-1} + \eps^{\alpha-1},  \\
        |u'_{\delta,\eps}(x)| &\le 2^{2-\alpha}(\alpha-1)|x|^{\alpha-2}\1_{[-2\eps,2\eps]^c}(x) + \frac{2^{3-\alpha}\delta(1-\delta^{-1})^{\alpha-1}}{\eps^{2-\alpha}\log \delta}\1_{[-2\eps,2\eps]}(x). 
    \end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Reduced \local\ for UGW trees) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds. Let $\tree \sim \mathrm{UGW}(\rho_{\myroot})$, and let $X$ be as in \eqref{eq:GW}, and also let $(\bar{\tree},\Xbar)$ be as in Construction \ref{constr:UGWlocal}. 
Then for each $k \in \N_0$, we have
\begin{equation*}
\big((1_{\{v \in \tree\}},X_v[k])_{v \in \V_1}, \, |N_1(\tree))|\big) \stackrel{d}{=} \big((1_{\{v \in \bar{\tree}\}},\Xbar_v[k])_{v \in \V_1}, \, \Nhat(k)\big).
\end{equation*}
In particular, the $(\{0,1\} \times \PolishX^\infty)^{\V_1}$-valued random variables $(1_{\{v \in \tree\}},X_v)_{v \in \V_1}$ and $(1_{\{v \in \bar{\tree}\}},\Xbar_v)_{v \in \V_1}$ have the same law. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition distribution_Mallows of arXiv:2412.07258, 'Permuton limit of a generalization of the Mallows and $k$-card-minimum models'] Let $n \in \mathbb{N}$ and $q \in \mathbb{R}_+\setminus \{1\}$.
    The $(n,q)$-Mallows model can be generated as in Definition (def_gen_perm_model of the paper) if
        we sample $C^{(n),i}$ according to the truncated geometric distribution
\begin{align}
        \mathbb{P}(C^{(n),i} = l) = \frac{q^{l-1} - q^{l}}{1-q^{n-(i-1)}}, \qquad l=1,\dots, n-(i-1).
        \end{align}

[Lemma 36 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] (\cite{el2026fast}, Lemma 3.5)
    Consider a Glauber dynamics with discrete-time Markov chain $(\sigma_k)_{k\geq 0}$. Let $\pi_k$ be the distribution of $\sigma_k$ and $\pi_\infty=\mu_G$ be the invariant measure. Suppose that $\pi_\infty$ satisfies the following weak conductance bound
    \begin{equation}
\pi_\infty(S)(1-\pi_\infty(S))\leq AQ(S,S^c)^{1/p},\quad\forall S\subseteq \{-1,1\}^V,        
    \end{equation}
    where $p\geq 1,A^p\geq 2/4^{p-1}$, and the following warm start condition holds:
    \begin{equation}
    \max_{S\subseteq \{-1,+1\}^V}\frac{\pi_0(S)}{\pi_\infty(S)}\leq M,
    \end{equation} then 
    \begin{equation}
 d_{\operatorname{TV}}(\pi_k,\pi_\infty)\leq M(\frac{A^{2p}\log k}{k})^{1/(2p-1)}       ,\quad k\geq 1.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:S_B_d-funnel of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let $\overline{\left[S^\infty_{B_{d}}\right]}$ be given by~{\em ((eq:S_Bd_by_dist of the paper),(eq:E-E-R-M=infty of the paper))}. Then 
\begin{equation}
	\overline{\left[S^\infty_{B_{d}}\right]}
	= 		\lim_{M \to \infty}
	\mathbb{E}_{{\cal G}(M,\frac{\lambda}{M})}  \bigg[ \frac{\prod_{i=1}^d [S^{k_i,p_j}_j]}{([S^{p_j}_j])^{d-1}} 
	~ \Big| ~ d_j = d     \bigg] ,\qquad d=2,3,\dots

\end{equation}

