[Lemma lem:collision-moments-proof of arXiv:2608.18320, 'Asymptotics for Beta-Splitting Trees via Homogeneous Fragmentations and Meromorphic Potent'] Conditionally on $\mathbf P(t)$,
    \begin{equation}
            \operatorname{Var}\bigl(C_n(t)\mid\mathbf P(t)\bigr)=\binom n2S_2(t)\bigl(1-S_2(t)\bigr)+6\binom n3\bigl(S_3(t)-S_2(t)^2\bigr).
    \end{equation}
    In particular,
    \begin{equation}
            \operatorname{Var}\bigl(C_n(t)\mid\mathbf P(t)\bigr)\le\mu_n(t)+n^3S_3(t).
    \end{equation}

[Theorem 2 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] Under the assumptions in Theorem \ref{theorem12121}, assume further that there exists some $M>0$ such that 
\begin{equation}
|h_u|\leq M\quad a.s.\quad \forall u\in V.
\end{equation}
Then with $\mathbb{P}_h-$ probability at least $1-O_{\beta,\Delta,p_0}(\frac{1}{|V|}
)$, the Glauber dynamics of $\mu_G$ satisfies a modified log-Sobolev inequality with constant $$
\rho_{LS}(P)\geq \frac{1}{3|V|}\exp\left(-4\beta((C_{\Delta,M,\beta}+1)\frac{4\Delta\ln|V|}{\alpha_*}+1)\right),
$$where $C_{\Delta,M,\beta}$ is a constant defined in \eqref{cemmdelta}.
Consequently, the $\epsilon$-mixing time of Glauber dynamics for $\mu_G$ is
$$
t_{mix}(P,\epsilon)=O(\rho_{LS}(P)^{-1}(\log(\beta\Delta |V|+\|h\|_1)+\log(1/\epsilon))).
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 ($(\beta - \slackmeasure, \sigma)$-consistency of a \smallset{} set) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] Given a Rashomon \smallset{} set $\retailset = \{f_k : k \in [\Nretail]\} \subseteq \emprashomonset$ of size $\Nretail$, a set of perturbed samples $\localtestmat = \{\localtest_{j} : j \in [\nogaussianpts]\} \subseteq \ltwohsphere(x,\sigma)$, the ensemble prediction $\ensmretset(\retailset,x)$ at $x$ as in Equation~\eqref{eq: ensemble at x}, and a constant $\slackmeasure \ge 0$, let $ \consistency(\retailset,\localtestmat, x)$ be defined as,
\begin{align}
    \consistency(\retailset,\localtestmat, x) = \babs{\ensmretset(\retailset,x)-\frac{1}{2}} - \frac{1}{\nogaussianpts}\sum_{j=1}^{\nogaussianpts}\frac{1}{\Nretail}\sum_{j=1}^{\Nretail}\babs{f_k(x) - f_k(\localtest_j)}.

\end{align}
 Then $\retailset$ is said to be $(\beta - \slackmeasure, \sigma)$-consistent if  
 \begin{align}
    \consistency(\retailset,\localtestmat, x) \ge \beta - \slackmeasure
 \end{align}

[Definition 1 of arXiv:2604.06645, '2604.06645'] Let $L: D\times D\rightarrow \mathbb R$ be a symmetric, positive--definite generalized function. A white-in-time, colored-in-space Gaussian noise with spatial covariance kernel $L$ is a centered Gaussian random measure on $[0,T]\times D$ such that for all adapted test functions $\varphi,\psi\in C^{\infty}_c([0,T]\times D)$,
\begin{align*}
&\mathbb{E}
\left(\int_0^T\int_D \varphi(s,x)\,W(dxds)\right)
\left(\int_0^T\int_D \psi(s,y)\,W(dyds)\right)
\\
=&\mathbb E\int_0^T\int_D\int_D
\varphi(s,x)\,\psi(s,y)L(x,y)dxdyds.
\end{align*}

