[Lemma 55 of arXiv:2608.27307, '2608.27307'] Under the assumptions of Theorem~\ref{thm:rand_sc_eq}, for every fixed integer $r\geq1$, uniformly for deterministic vectors $\bbv,\bbw\in\C^L$,
        \begin{align}
                \abs{\partial_{i\mu}^r(Q)_{\bbv\bbw}} \prec (1+\phi)^{r+1}\frac{\vphi+\eta}{N\eta}\|\bbv\|\|\bbw\|. 
        \end{align}
        Moreover,
        \begin{align}
                \abs{(Q)_{\bbv\bbw}} \prec (1+\phi)^4\left(\frac{\vphi+\eta}{N\eta}\right)^{3/2}\|\bbv\|\|\bbw\|. 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 25 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. For $\eps_*>0$ sufficiently small, every $z$ with $|z-E_*|<\eps_*$ and $\Im z\geq0$ satisfies
        \begin{align}
                |\Theta|+\|\bbs_*\| & \lesssim|z-E_*|^{1/3}\leq\eps_*^{1/3},  \\
                \|\bbs_*\|          & \lesssim|z-E_*|+|\Theta|^2. 
        \end{align}
        Moreover, $\Theta$ satisfies
        \begin{align}
                0=\mu_1(z-E_*)+\mu_2\Theta^2+\mu_3\Theta^3+O(|z-E_*||\Theta|+|z-E_*|^2+|\Theta|^4), 
        \end{align}
        and the coefficients defined above are real and satisfy
        \begin{align}
                c\leq\mu_1\leq C, \qquad |\mu_2|+|\mu_3|\leq C. 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Definition~3.2 of~\cite{LMST} of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] For $n\in \mathbb N$, $\delta>0$, $t>0$, consider the Ising model in $R_n$ with random boundary condition $\tau \sim \mathbf{P}$. We say $\mathcal A(L_n,t_n,\delta_n)$ holds if 
    \begin{align*}
        \mathbf{E}||\mu_{t_n}^\pm - \pi^\tau\|\le \delta_n \qquad \text{for all $\mathbf P\in \mathcal D(R_{L_n})$}\,.
    \end{align*}
    The statement $\mathcal B(L_n,t_n,\delta_n)$ is defined with $Q_{L_n}$ replacing $R_{L_n}$.

[Definition 19 (Pairwise Disagreement~\citep{black2022model}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The pairwise disagreement of the empirical Rashomon set $\emprashomonset$, at a test instance $x$, is the average disagreement between pairs of models $f_{k},f_{l} \in \emprashomonset$ and is defined as,
\begin{align}
      \pairwisedisag(x) = \frac{1}{\abs{\emprashomonset}(\abs{\emprashomonset}-1)}\sum_{h_k,h_l \in \emprashomonset, h_k \ne _l}\Indic{h_{k}(x) \ne h_{l}(x)},
\end{align}  
where $h(x)= \Indic{f(x) \geq \frac{1}{2}}$ is the hard decision of $f$.

[Lemma 43 of arXiv:2506.10494, 'Geometric Jensen-Shannon Divergence Between Gaussian Measures On Hilbert Space'] Let	$A \in \Sym(\Hcal)\cap\HS(\Hcal)$, $I+A > 0$. Then
		$(A-\log(I+A))\in \Sym^{+}(\Hcal) \cap\Tr(\Hcal)$. Furthermore,
		\begin{align}
			||A-\log(I+A)||_{\tr} = -\log\dettwo(I+A) \leq ||(I+A)^{-1}||\;||A||^2_{\HS}.
		\end{align}

