body:
[Lemma 8 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Suppose that $(Z_n)$ is a zero mean square-integrable martingale. Let $r_n^2:= \displaystyle\sum_{k=n}^{\infty} \dE[(\Delta Z_k)^2]$. If $\displaystyle\sum_{k=1}^{\infty} \dE[(\Delta Z_k)^2] < +\infty,$
and $\displaystyle\sum_{k=1}^{\infty}\frac{1}{r^2_k} \left[ (\Delta Z_k)^2 - \dE[ (\Delta Z_k)^2 \vert\mathcal{F}_{k-1}]\right] < +\infty ~ \text{ a.s.},$ we have the following:
\begin{itemize}
    \item [(i)] The limit $Z:= \sum_{k=1}^{\infty} \Delta Z_k $ exists almost surely and $Z_n \overset{L^2}{\rightarrow} Z$.
    \item [(ii)] Assume additionally that

		\begin{itemize}
        \item [a)] $\displaystyle\frac{1}{r_n^2}\sum_{k=n}^{\infty}\dE\left[(\Delta Z_k)^2\vert\mathcal{F}_{k-1}\right]\rightarrow 1$ as $n \to \infty$ in probability, and
        \item [b)] $\displaystyle\frac{1}{r_n^2}\displaystyle\sum_{k=n}^{\infty}\dE\left[(\Delta Z_{k+1})^2 \mathbb{I}_{\{\vert\Delta Z_{k+1}\vert\geq\varepsilon r_k\}}\right] \rightarrow 0$ for any $\varepsilon > 0$.

        Then, we have that
        \begin{equation*}
            \displaystyle\frac{Z-Z_n}{r_{n+1}}=\frac{\sum_{k=n+1}^{\infty}\Delta Z_k}{r_{n+1}} \overset{d}{\rightarrow}N(0,1).
        \end{equation*}
    \end{itemize}

     \item [(iii)] If, in addition, the following conditions hold 
       \begin{itemize}
        \item [a')] $\displaystyle\frac{1}{r_n^2}\sum_{k=n}^{\infty}\dE\left[(\Delta Z_k)^2\vert\mathcal{F}_{k-1}\right]\rightarrow 1$ as $n \to \infty$ a.s.
        \item [c)] $\displaystyle\sum_{k=1}^{\infty}\frac{1}{r_k}\dE[ |\Delta Z_k| \mathbb{I}_{\{| \Delta Z_k|  > \varepsilon r_k\}}] < +\infty$ for any $\varepsilon > 0$, and
        \item [d)] $\displaystyle\sum_{k=1}^{\infty}\frac{1}{r_k^4}\dE[ (\Delta Z_k)^4 \mathbb{I}_{\{|\Delta Z_k|  \le \delta r_k\}}] < +\infty$ for some $\delta > 0$. 
    \end{itemize}
    Then, $\displaystyle\limsup_{n\to\infty}\pm \frac{Z-Z_n}{\sqrt{2\cdot r^2_{n+1} \log |\log r^2_{n+1} |}} = 1$ a.s.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

