body:
[Proposition prop:abstract-common-domain of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] The operator $\widehat A_{\tau,f}$ is associated in $L^2(\mu)$ with
\begin{equation}
 a_{\tau,f}(u,v)
 =\mathcal E(e^{-\kappa\tau f/2}u,e^{-\kappa\tau f/2}v),
 \qquad
 \operatorname{Dom} a_{\tau,f}=V_\mu.

\end{equation}
For every $T>0$, the form norms
\[
 \left\|u\right\|_{\tau,f}^2
 :=a_{\tau,f}(u,u)+\left\|u\right\|_{L^2(\mu)}^2
\]
are uniformly equivalent for $|\tau|\le T$: there are
$0<c_{T,f}\le C_{T,f}<\infty$ such that
\begin{equation}
 c_{T,f}\left\|u\right\|_{\mathcal E,\mu}
 \le \left\|u\right\|_{\tau,f}
 \le C_{T,f}\left\|u\right\|_{\mathcal E,\mu},
 \qquad |\tau|\le T.

\end{equation}
For $u,v\inV_\mu$,
$\tau\mapsto a_{\tau,f}(u,v)$ is real analytic and
\begin{equation}
 \dot{a}_{0,f}(u,v)
 =-\frac\kappa2\mathcal E(fu,v)-\frac\kappa2\mathcal E(u,fv).

\end{equation}

