[Lemma eq:dI-budget of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:aggregate-jet-budget}
Uniformly in \(O\in\mathcal O_{N,L}\),
\begin{equation}
 \sum_{I\in[N]^p}\mathfrak d_I\le C N,
 \qquad
 \max_{I\in[N]^p}\mathfrak d_I\le Cq_N^2.
\end{equation}
Writing \(\alpha_I(J)=\partial_I\Psi_O(J)\), one also has
\begin{equation}
 \max_I\left\lvert\alpha_I(J)\right\rvert\le Cq_N,
 \qquad
 \sum_I\left\lvert\alpha_I(J)\right\rvert^2\le CN,
\end{equation}
and, for \(2\le k\le m+1\),
\begin{equation}
 \left\lvert\partial_I^k\Psi_O(J)\right\rvert
 \le C_k\mathfrak d_Iq_N^{k-2}.
\end{equation}
Consequently, for \(2\le k\le m+1\),
\begin{align}
 \left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kF_O(J)
 \left(\left\lvert\alpha_I(J)\right\rvert^k+
       \mathfrak d_Iq_N^{k-2}\right),
 \\
 \sum_I\left\lvert\partial_I^kF_O(J)\right\rvert
 &\le C_kNq_N^{k-2}F_O(J).

\end{align}
All constants are uniform in \(J,N,O\).

[Lemma lemma10.444 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Under the assumption of Theorem (Theorem1.2 of the paper), for any $\delta_1,\delta_2\geq e^{-cn^{\sigma}}$, any $u\in\mathbb{S}^{n-1}$, and any $p>1$, we have the following estimate:
\begin{equation}
\begin{aligned}
&\mathbb{E}_{A_n}\sup_{r_1,r_2\in\mathbb{R}}\mathbb{P}_X\left(
    \frac{|\langle (A_n-\lambda_i I_n)^{-1}X,X\rangle-r_i|}{\|(A_n-\lambda_i I_n)^{-1}\|_*}\leq\delta_i
    ,\langle X,u\rangle\geq s,\frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\leq(\delta_1\delta_2)^{-p}
    \right)\\&\lesssim e^{-s}\delta_1\delta_2+e^{-\Omega(n^{\sigma/2})}
    \\&+e^{-s}\delta_1\delta_2\mathbb{E}_{A_n}\left[\left(\frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\right)^{\frac{9}{10}}
    \wedge\left\{ \frac{\prod_{i=1}^2\mu_1(\lambda_i)}{n}\leq (\delta_1\delta_2)^{-p}\right\}\right]^{\frac{80}{81}},\end{aligned}
\end{equation}
    where the constant $c>0$ in the assumption $\delta_i\geq e^{-cn^\sigma}$ and the implied constant in the inequality $\lesssim$ depend on all the constants $B,\kappa,\Delta,\sigma$.

[Lemma 14 (Survival along a sequence of stars) of arXiv:2604.00630, 'The contact process on a bipartite spatial network'] Let~$G$ be a bipartite graph. Let~$(x_k)_{k\ge 0}$ and~$(y_k)_{k \ge 1}$ be sequences of vertices of~$G$ such that:
	\begin{itemize}
		\item $(x_k)_{k \ge 0}$ have type 1 and~$(y_k)_{k \ge 1}$ have type~2, with
	\[
x_0 \sim y_1 \sim x_1 \sim y_2 \sim x_2 \sim \cdots;
	\]
\item the sequence~$(x_k)_{k\ge 0}$ has infinitely many distinct elements.
	\end{itemize}
	Then, the contact process on~$G$ with rates~$\lambda_1,\lambda_2$ and~$x_0$ initially infected survives forever with probability at least
	\begin{equation*}
		1-\sum_{k=0}^\infty ((\varepsilon \lambda_1 \lambda_2 \deg(x_k))^{-1/2} + \exp\{-c\lambda_1 \lambda_2^2 \lfloor \exp(\varepsilon \lambda_1 \lambda_2 \cdot \deg(x_k)) \rfloor \}),
	\end{equation*}
	where~$\varepsilon > 0$ is the constant of Lemma~\ref{lem_main_star} and~$c > 0$ is a constant not depending on~$\lambda_1,\lambda_2$.

[Definition fixptfun of arXiv:2605.06887, 'Law of large numbers for activated random walk on villages'] Define the function $\phi:\mathbb{R}_+^{V} \rightarrow{\mathbb{R}^{V}}$ as follows: for $m \in \mathbb{R}_+^{V}$ and $x \in V$, set
\begin{equation} 
     \phi(m)_x = (\sigma_x - \frac{\lambda_x}{1+\lambda_x})\left( 1-e^{-\beta(m)_x}\right) + \beta(m)_x
\end{equation}
We call $\phi$ the fixed point function of the VARW model.

[Lemma le:chineq of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] The function $c(r,s)$ in (equation equality_beta of the paper) can be bounded from above as
\begin{equation} 
c(r,s)\leq\frac{1}{d(r)}+\frac{1}{1-d(r,s)}
\end{equation}
for $d(r,s)=d(r)+d(s)$ and $d(s) \in (0,\frac{1}{2})$.

