[Definition eq:cor-F-integral of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Given a typical diagram $\Gamma$,  for      $t_1,\dots,t_s>0$ introduce   a family of  linear constraint   inequalities    for edge–weighted variables $\{\alpha_e\geq 0\}$
\begin{equation}
\mathfrak{C}(\{\alpha_e\})
:\quad
\sum_{e\in E(\Gamma)} c_i(e)\,\alpha_e \;\le\; t_i, 
\quad i=1,\dots,s,
\end{equation}
with \(c_i(e)\in \{0,1,2\}\) counting  the times  of   \(e\) appearing in $\partial D_i$, a diagram 
 function   is defined as 
 \begin{equation}
\mathcal{F}_\Gamma(t_1,\dots,t_s)
\;=\;
\frac{C_\Gamma}{\,t_1\cdots t_s\,}\,
\int \cdots \int_{\mathfrak{C}(\{\alpha_e\})}
\prod_{b_j}\Bigl(\sum_{i=1}^q e^{\tau_i\,\ell_{b_j}}\Bigr)
\,\prod_{e\in E(\Gamma)}d\alpha_e,
\end{equation}
where for each open cycle \(b_j\subset E_b(\Gamma)\)
\begin{equation}
    \ell_{b_j}:\;=\;\sum_{e\in b_j}\alpha_e,
\end{equation} 
and \(C_\Gamma>0\) is a combinatorial constant depending only on \(\Gamma\) defined by
\begin{equation}
    C_\Gamma=\lim_{n_j\rightarrow\infty}\frac{\#\{(w_e)_{e\in E(\Gamma)}|
        t_j, w_e\in \mathbb{N},~t_j \ge 0,\; w_e \ge 1,~
        2t_j + \sum\limits_{e \in \partial D_j} w_e = n_j,~ j=1,\dots,s\}}{\mathrm{Vol}\{(\alpha_e)_{e\in E(\Gamma)}|\alpha_e\in \mathbb{R}^+, \sum_{e\in E(\Gamma)} c_i(e)\,\alpha_e \;\le\; n_j, 
\quad j=1,\dots,s\}}.
\end{equation}

[Lemma lem:CT of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For every $u\in\{0,1,2\}$ and $c>0$ small enough, uniformly in $\eps\in(0,1]$ and $s\in\R$, we have
\begin{equs}
    |\d^u_\eps\mathfrak{c}_\eps^{\tt S}(s)|\lesssim \eps^{(-1+c)u}\quad\text{and}\quad|\d^u_\eps\mathfrak{c}^+_\eps(s)|\lesssim \eps^{(-1+c)u}(1\wedge |s|+\eps)^{-1+2H-cu}\,.
\end{equs}

