[Proposition of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] $\mathsf{acc}$ is strictly proper iff there is a convex function $\varphi$ (with values $\mathsf{acc}_v(v)$) where:
	\begin{align}\mathsf{acc}_v(x):=\mathsf{acc}_v(v)-\br{\varphi(v)-\varphi(x)-(v-x)\varphi'(x)}
	\end{align}
	That is, the error-score is:
	\begin{align}\mathfrak{s}_v(x)=\varphi(v)-\varphi(x)-(v-x)\varphi'(x)
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 13 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-particles} hold.
For $k$ as in Assumption~\ref{assump-particles}\ref{hyp:F0Nk} and for any cut-off $A>0$ from \eqref{def:cutoff}, there exists $C = C(T,A,k,d)>0$ such that

\begin{equation}
\sup_{N\in \N^*}  e^{-C T \sigma_{N}^{-2}} \bigg(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} F_{t}^{N} \big\|_{L^{2}_{x,v}}^{2q}
+ \sigma_N^{2q}\, \E \bigg[ \Big(\int_{0}^T \big\lVert \langle v \rangle^k \nabla_{v} F^N_{s}\big\rVert_{L^{2}_{x,v}}^{2} \dd s\Big)^q\bigg] \bigg)^{1/q}<\infty.
\end{equation}

