[Lemma 1 of arXiv:2608.12056, 'Deviation inequalities for U-processes of growing order, with applications to half-space d'] Let $\mathcal{H}_m$ be a Euclidean class with exponent $V$. Then for any $j \in [m]$, 
    \begin{align}
    \mathbb E \gamma_{2} \left(\mathcal{H}_m, d^{(2)}_{N,j}\right) \leq C^j\Gamma(j,m,N,V).
    \end{align}
    Moreover, for any $p \geq 2$ and $2 \leq j \leq m$,  
    \begin{equation}

    \left(\mathbb E \left(\gamma_{2/j} (\mathcal{H}_m, d^{(1)}_{N,j}) \right)^p\right)^{1/p} 
    \leq \left(C_1V \left[j\log\left(\frac{C_2m}{j}\right) \bigvee \log\left( \frac{e}{\Sigma_{\mathcal H_m}}\right)\right]\right)^{j/2}D(p,j).
    \end{equation}
    Finally, if $p \geq 4V$, then  
    \begin{align}

        \gamma_{2/j, \lfloor \log_2 (pj) \rfloor}(\mathcal{H}_m, d^{(1)}_{N,j}) \leq 
        (C_5 pj)^{j/2} e^{-pj/V}

    \end{align}
    with probability $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.30178, '2608.30178'] \rev{For every \(x,y>0\), equation~\eqref{eq:noimm-system} admits} a pathwise unique \vthirtyfour{strong}
c\`adl\`ag solution \((X,Y)\), defined on the time interval
\([0, \tau_0\wedge\tau_\infty)\) and taking values in \((0,\infty)^2\).  The solution is adapted to the completed filtration generated by the four driving noises.  The associated stopped interior martingale problem is well-posed and consequently defines a strong Markov family.

[Lemma 20 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and let $X_{N}= I_{p} (f_{N})$ with $ f_{N} \in H ^ {\odot p}$ for all $N\geq 1$. Assume that $(X_{N}, N\geq 1)$ satisfies (\ref{c1}). Let $Y_{N}= I_{q} (g_{N}) $ with $p<q<2p$ and $(Y_{N}, N\geq 1)$ bounded in $ L^ {2}(\Omega)$. Then
		\begin{enumerate}
			\item For $N\geq 1$, 
			\begin{equation*}
				Y_{1, N}= \frac{ p(q-1)!}{(q-p)!} I_{q-p} (f_{N}\otimes _{p}g_{N}) + R_{1,N},
			\end{equation*}
			where $R_{1, N}\to _{N \to \infty } 0 $ in $ L ^ {2}(\Omega)$.
			\item $X_{N}$ and $Y_{1, N}$ are asymptotically independent, i.e. 
			\begin{equation*}
				\langle DX_{N}, DY_{1, N} \rangle _{H} \to _{N\to \infty}0 \mbox{ in } L^ {2}(\Omega).
			\end{equation*} 
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

