[Lemma 4 of arXiv:2609.04095, '2609.04095'] For \(n\ge0\) and \(0\le p\le2n\),
\begin{equation}
 a_p^{(n)}=
 \begin{cases}
  T_p(0),&0\le p\le n,\\
  T_{2n-p}(p-n),&n\le p\le2n.
 \end{cases}
\end{equation}
The two expressions agree when \(p=n\).

[Lem ;laltv of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] We have 
\begin{align}
 V(z)=C_{p,\nub }'\int _{0}^{z}du\,\int _{0}^{\infty }d\lambda  \,
 \lambda  ^{(2p-1)\nub +1}K_{\nub }(\lambda  )\exp \!\left( 
 -\frac{q^{2}u}{8}\lambda  ^{2}
 \right) 
\end{align}
for all $z\ge 0$. Here the constant $C_{p,\nub }'$ is given by 
\begin{align}
 C_{p,\nub }'=\frac{1}{
 2^{(2p-1)\nub }\Gamma (1+p\nub )\Gamma (1+(p-1)\nub )
 }.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:chen_mixed of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] We denote by $\mathcal{R}^{\gamma, \beta}([0, 1]; V\times E)$ the collection of all elements ${\color{purp}g}=(g^\bullet, g^\circ, \mathbb{g}^{\bullet\bullet},  \mathbb{g}^{\circ\bullet}, \mathbb{g}^{\bullet\circ})$, such that 
    $(g^\bullet, \mathbb{g}^{\bullet\bullet}) \in  \mathcal{R}^\gamma([0, 1]; V)$,
    $g^\circ \in \mathcal{C}^\beta([0, 1];E)$,     
        $ (\mathbb{g}^{\bullet\circ}, \mathbb{g}^{\circ\bullet}) \in  \mathcal{C}^{\beta+\gamma}_2([0,1]^2;  (V\otimes E) \times (E\otimes V) )$, and that the Chen's relations
        \begin{equs}                
            \mathbb{g}^{\bullet\circ}_{s, t}-\mathbb{g}^{\bullet\circ}_{s, u}- \mathbb{g}^{\bullet\circ}_{u, t}= g^\bullet_{s, u} \otimes g^\circ_{u, t}, \qquad \mathbb{g}^{\circ\bullet}_{s, t}-\mathbb{g}^{\circ\bullet}_{s, u}- \mathbb{g}^{\circ\bullet}_{u, t}= g^\circ_{s, u} \otimes g^\bullet_{u,t}       
        \end{equs}
        hold for all $(s,u,t)\in[0,1]^3_\leq$.
        Moreover, we set 
        \begin{equ}
         \,    [{\color{purp}g}]_{\mathcal{R}^{\gamma, \beta}}= [g^{\bullet}]_{\mathcal{C}^\gamma}+ [g^{\circ}]_{\mathcal{C}^\beta}+[\mathbb{g}^{\bullet \bullet}]_{\mathcal{C}^{2\gamma}_2}+[\mathbb{g}^{\circ  \bullet}]_{\mathcal{C}^{\gamma+ \beta}_2}+[\mathbb{g}^{\bullet \circ}]_{\mathcal{C}^{\gamma+ \beta}_2}.
        \end{equ}

[Lemma lem:odometer-derivative of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Suppose $(\zeta(x))_{x\in\mathbb{Z}^d}$ are independent and atomless. Then,
	$\mathbb{P}$-almost surely, for every $n\geq1$ and $x,z\in\mathbb{Z}^d$,
	\begin{equation}
		\partial_{\zeta(z)}u_n(x)
		=
		\mathbf E_x\sum_{j=0}^{n-1}
		\mathbf{1}_{\{X_j=z\}}
		\prod_{i=0}^j\mathbf{1}_{\{u_{n-i}(X_i)>0\}}
		=
		\mathbf E_x\sum_{j=0}^{n-1}
		\mathbf{1}_{\{X_j=z\}}\mathbf{1}_{\{\tau_n^*>j\}}\, .
	\end{equation}

