[Problem probICPDou of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] Find the unknown solution
\begin{align*}
y \in L^{2}_{\mathbb{F}}(\Omega; C([0,T]; L^{2}_{loc}(G))) \cap L^{2}_{\mathbb{F}}(0,T;H^{2}_{\Gamma_{0}}(G))
\end{align*}
to the equation (eqInversPParabolicPartialBoudaryeq of the paper) via $y \big|_{(0,T)\times \Gamma_0}$ and $ \dfrac{\partial y}{\partial \nu}  \bigg|_{(0,T)\times \Gamma_0}$. (Stated as a problem by the paper; open unless the paper says otherwise.)

[Lemma lem: Wasserstein-$p$ bound SSQ reduction of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Wasserstein-$p$ Bound Reduction for SSQ)}
    With the same notations above, for $p \leq \lambda/(2\gamma)$: 
    \begin{align*}
        W_p(\mathcal{L}(\tilde{q}), \mathcal{L}(Z))&\leq C_{10, \lambda, \mu} \cdot \big(p\sqrt{\gamma} + \frac{1}{\sqrt{\gamma}} \|\mathbf{1}_{q=0} \|_{L^p} +\gamma\sqrt{p} \| q - \frac{\lambda-\mu}{\gamma}\|_{L^p} \big)
    \end{align*}
    Here $C_{10, \lambda,\mu}$ is constant independent of $\gamma$ and $p$, defined in (equation eq: C_10, lambda, mu of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:deftwist of arXiv:2604.15146, 'Renormalised two-point functions of CLE$_4$ gaskets'] The (zero boundary) twist field correlations $\sigma_{\rm tw}^D(z_{1}, z_{2},\dots, z_{n})$ can be defined via three equivalent ways by taking the following limits. 
\begin{enumerate}[i)]

\item As $\delta\to 0$, we consider the limit of
\begin{equation}
\delta^{-n/16}\exp(n\mathbf{c}_\mathbb{D}^{\rm{loop}})\exp\left(-
\mu^{\rm loop}_{D}
\Big(\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd},
t_{\gamma}>\delta
\Big)\right),
\end{equation}
where $\mathbf{c}_\mathbb{D}^{\rm{loop}}$ is an explicit constant 
that can be expressed through the Brownian loop measures
in the unit disk $\mathbb{D}$ and its complement
$\mathbb{C}\setminus\overline{\mathbb{D}}$:

$$\mathbf{c}_\mathbb{D}^{\rm{loop}}
=
\mu^{\rm loop}_{\mathbb{D}}(t_{\gamma}>1,
\indx_{\gamma}(0) \text{ odd})
-
\mu^{\rm loop}_{\mathbb{C}}(
\gamma \cap (\mathbb{C}\setminus\overline{\mathbb{D}})\neq\emptyset,
t_{\gamma}<1,
\indx_{\gamma}(0) \text{ odd}).
$$

\item
As $\max_{1\leq j\leq n}\varepsilon_j\to 0$, we consider the limit of
\begin{equation}
\prod_{j=1}^{n}
\Big(
\frac{1}{\varepsilon_j^{1/8}\sqrt{|\log \varepsilon_j|}}
\Big)
\left(\pi/2\right)^{n/2}\exp\left(-\mu^{\rm loop}_{D_{\varepsilon_1, \dots, \varepsilon_n}(z_1, \dots, z_n)}
\Big(\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd}
\Big)\right).
\end{equation}
\item Consider the Brownian loop soup 
$\mathcal{L}_{D_{\varepsilon_1,\dots, \varepsilon_n}(z_1,\dots, z_n)}$
in the domain with holes
$D_{\varepsilon_1,\dots, \varepsilon_n}(z_1,\dots, z_n)$,
and let $(\overline C_i^{\varepsilon_1,\dots, \varepsilon_n})_{i \geq 1}$ denote the collection of topological closures of its clusters. 
(It is an infinite countable collection of random compact disjoint subsets in $D$.) 
As $\max_{1\leq j\leq n}\varepsilon_j\to 0$, we consider the limit of
\begin{equation}
\prod_{j=1}^{n}
\Big(
\frac{1}{\varepsilon_j^{1/8}\sqrt{|\log\varepsilon_j|}}
\Big)
\left(\pi/2\right)^{n/2}\mathbb{P}\left(\nexists \text{ path }\gamma\subseteq
\bigcup_{i \geq 1}
\overline{C}_i^{\varepsilon_1,\dots, \varepsilon_n}
\text{ with }\sum_{j=1}^{n}
\indx_{\gamma}(z_j)
\text{ odd}
\right).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

