[Theorem Theorem~2 in \cite{HebischSikora1990} of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\mathbb G$ be any homogeneous Carnot group equipped with the  dilations $(\delta_\lambda)_{\lambda>0}$. Then there exists $\varepsilon_0>0$ such that for every $0<\kappa<\varepsilon_0$, 
    \begin{align*}
        \rho(x):=\inf\{t>0: |\delta_{1/t} x|<\kappa \}
    \end{align*}
    defines a symmetric homogeneous norm on $\mathbb G$. In particular, the unit metric ball $\{x\in\mathbb G: \rho(x)<1\}$ coincides with the Euclidean ball $B_{\mathbb{R}^n}(0,\kappa)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor cor1:sig:gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:derv:liningam of the paper)}  hold, then for   $ 2\leq p_0\leq \min\{{\bar p}/((\eta+1)
  (\eta/8+1)),\bar p/2\}$
		\begin{align*}
			\sum_{\mathfrak q=1}^{2}E\big|(\widehat\sigma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)\big|^{p_0} 
			+ \sum_{\mathfrak q=1}^{2}\int_Z E\big|(\widehat\gamma_{\mathfrak{q}})_{tam}^{\displaystyle{n}}\big(\kappa_n(s),s,x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)},\bar z\big)\big|^{p_0}\nu(d\bar z)
			\leq &  
			Kn^{-1}
		\end{align*}
  for any   $s\in[0,T]$ and $i\in\{1,\ldots,N\}$   where $K>0$ is independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 20 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] For $\kappa>0$, we let $\mathcal G_{\kappa}$ be the set of probability measures $\Ups$ on $\mathbb R$ which are absolutely continuous with respect to 
 Lebesgue measure with density $\dd \Ups(x) \, = \, \varrho(x) \dd x$ such that

\begin{enumerate}

\item $\Ups$ is compactly supported with bounded density, $\varrho \in L^{\infty}(\R)$;

\item $\Int{\mathbb{R}}{} \ln(1+|x|)^4 \, \varrho(x)\, \mathrm{d}x  < +\infty$;

\item $1+ \frac{2}{\ell} \Int{\mathbb{R}}{} \ln |x-y| \, \varrho(y) \, \mathrm{d}y \geq \kappa$ for all $x\in \mathbb R$. 

\end{enumerate}

[Lemma 14 (Stopped estimates) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[lemma]{le:ll_stopped_int_l2}
For every \(\rho>0\), there exists \(C_\rho<\infty\) such that, for
\(p=2,4\),
\begin{equation}
    \Exp*{}{
        \sup_{s\in I_m^n}
        \left|
            \hat X^n_{s\wedge\tau_{n,\rho}}
            -
            \hat X^n_{t_{m-1}^n\wedge\tau_{n,\rho}}
        \right|^p
    }
    \le
    C_\rho n^{-p/2}.
\end{equation}
Moreover,
\begin{equation}
    \Exp*{}{
        \int_0^{\tau_{n,\rho}}
        |\hat X_s^n-\hat X_{\varphi_n(s)}^n|^2\,ds
    }
    \le
    C_\rho n^{-1},
\end{equation}
\begin{equation}
    \Exp*{}{
        \left(
            \int_0^{\tau_{n,\rho}}
            |\hat X_s^n-\hat X_{\varphi_n(s)}^n|^2\,ds
        \right)^2
    }
    \le
    C_\rho n^{-2},
\end{equation}
and
\begin{equation}
    \Exp*{}{
        \sup_{t\le1}
        |X_{t\wedge\tau_{n,\rho}}-
        \hat X^n_{t\wedge\tau_{n,\rho}}|^2
    }
    \le
    C_\rho n^{-3} .
\end{equation}
Consequently,
\begin{equation}
    \Exp*{}{
        \int_0^{\tau_{n,\rho}}|X_s-\hat X_s^n|^2\,ds
    }
    \le
    C_\rho n^{-3},
\end{equation}
and, for \(m=0,\dots,n\),
\begin{equation}
    \Exp*{}{
        |X_{t_m^n\wedge\tau_{n,\rho}}
        -\hat X^n_{t_m^n\wedge\tau_{n,\rho}}|^2
    }
    \le
    C_\rho n^{-3} .
\end{equation}

[Proposition 4 of arXiv:2605.16733, 'Concentration Inequalities for Sample Cross-Covariances'] Let \((X_i,Y_i)_{i=1}^N\) be i.i.d. copies of a centered Gaussian random
vector $(X,Y) \in \R^{d_X+d_Y}$.
Then
\begin{align*}
\E \bigg\|\frac{1}{N}\sum_{i=1}^{N} X_i Y^{\top}_i-\E XY^{\top}\bigg\| \gtrsim (\|\Sigma_{X}\|\|\Sigma_Y\|)^{1/2} \bigg(\sqrt{\frac{r_{X}+r_{Y}}{N}}+ \frac{\sqrt{r_{X}r_{Y}}}{N}\bigg).
\end{align*}

[Lemma 1 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] The operator-valued increment $a$ from \eqref{eq:a-def} satisfies
\begin{equation*}

(\delta a)_{tus}=a_{tu}a_{us},
\qquad 0\le s\le u\le t\le T.
\end{equation*}

