&P(V_1\ge x|V_1=\min(V_1,\cdots, V_r), V_2=\min(V_2,\cdots, V_s) )=\\
&\frac{P(V_1\ge x,V_1<V_2, V_1<\min(V_{s+1},\cdots, V_r), V_2<\min(V_3,\cdots ,V_s))}{P(V_1<V_2, V_1<\min(V_{s+1},\cdots, V_r), V_2<\min(V_3,\cdots, V_s))}.
