[Lemma lem:incidence-bound of arXiv:2608.18293, 'Critical tensor covariance at the Marchenko--Pastur threshold'] Assume $n>2d$. Let $b=(b_I)_{I\in\Omega_{n,d}}\in\mathbb{C}^{\Omega_{n,d}}$ satisfy
\[
  \sum_{I\in\Omega_{n,d}}b_I=0.
\]
Then for $1\le r\le d$,
\begin{equation}
  \boxed{
  \|M_r^{\mathsf T}b\|_2^2
  \le
  \binom{d-1}{r-1}
  \binom{n-r-1}{d-r}
  \|b\|_2^2.}

\end{equation}

