[Lemma lem:markov_eta of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] {Suppose that $\mathbf{q} \in \mathcal{Q}_{\mathrm{M}}$ and fix $x \in {\mathbb{Z}}$. Under $\mu_{\mathbf{q}}$, } $\left(T^{n}\eta\left(x\right) \right)_{n \in {\mathbb{Z}}}$ is an irreducible and non-periodic two-sided Markov chain on $\{ 0,1 \}$ whose transition matrix is given by 
        \begin{align}
            R = \begin{pmatrix}
                R_{00} & R_{01} \\
                R_{10} & R_{11}
            \end{pmatrix} := 
            \begin{pmatrix}
                1 - \frac{{\rho\left(\mathbf{q}\right)}}{1 - {\rho\left(\mathbf{q}\right)}} & \frac{{\rho\left(\mathbf{q}\right)}}{1 - {\rho\left(\mathbf{q}\right)}} \\
                1 & 0
            \end{pmatrix},
        \end{align}
            and invariant measure $\pi \in [0,1]^2$ for $R$ is the Bernoulli measure with density ${\rho\left(\mathbf{q}\right)}$.

[Theorem 11 of arXiv:2608.01419, 'A model of opinion dynamics evolving via a preferential attachment mechanism involving mul'] Consider the stochastic approximation process in \eqref{sa_borkar_general}, with $\delta_{n}=\mathbf{0}$ for each $n$. In addition to Assumptions~\eqref{borkar_1}, \eqref{borkar_2} and \eqref{borkar_4}, we assume  
\begin{enumerate}[label=(B'\arabic*), ref=B'\arabic*]
\item  that $F$ is continuously differentiable, and its Jacobian $J_{F}$ is uniformly Lipschitz,
\item  that $\alpha:=\lim_{n\rightarrow\infty}\{a_{n+1}^{-1}-a_{n}^{-1}\}$ exists and is finite,
\item  that $\sup_{n}\E[||Z_{n}||^{4}]<\infty$,
\item  that for some $K>0$, and some $Q:\mathbb{R}^{d}\rightarrow\mathbb{R}^{d\times d}$ such that $Q(\mathbf{x})$ is a non-negative definite symmetric matrix for each $\mathbf{x}\in\mathbb{R}^{d}$, we have
\begin{equation}
\E\left[\Delta M_{n+1}\Delta M_{n+1}^{T}\big|\mathcal{F}_{n}\right]=Q(Z_{n}) \text{ and } \E\left[\left|\left|\Delta M_{n+1}\right|\right|^{4}\big|\mathcal{F}_{n}\right]\leqslant K\left(1+||Z_{n}||^{4}\right),\nonumber
\end{equation}
where $A^{T}$, for any matrix $A$ with real entries, indicates its transpose.
\end{enumerate}
Fix \emph{any} $T>0$. Writing $t_{0}=0$ and $t_{n}=\sum_{i\in[n]}a_{i}$ for $n\in\mathbb{N}$, we set $m_{n}=\min\{m\geqslant n: t_{m}\geqslant t_{n}+T\}$ for each $n\in\mathbb{N}$. For each fixed $n\in\mathbb{N}$, let $\{Z^{n}(t): t\geqslant t_{n}\}$ indicate the solution to
\begin{equation}
\dot{\mathbf{x}}(t)=F(\mathbf{x}(t)) \text{ for all }t\geqslant t_{n}, \quad \text{with} \quad \mathbf{x}(t_{n})=Z_{n},\nonumber
\end{equation}
and let $W_{j}=a_{j+1}^{-1/2}\{Z_{j}-Z^{n}(t_{j})\}$ for each $j\geqslant n$. We now define the process $\{W^{n}(t):t\in [t_{n},t_{n}+T]\}$: 
\begin{equation}
W^{n}(t)=W_{j}+\frac{t-t_{j}}{t_{j+1}-t_{j}}(W_{j+1}-W_{j}) \text{ for }t\in[t_{j},t_{j+1}], \text{ for each }j\in\{n,n+1,\ldots,m_{n}-1\}.\nonumber  
\end{equation}  
Finally, we set $\tilde{W}^{n}(t)=W^{n}(t_{n}+t)$ for all $t\in[0,T]$. Likewise, we define $\tilde{Z}^{n}(t)=Z^{n}(t_{n}+t)$ for all $t\in[0,T]$. Then the laws of the processes $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ are relatively compact in the space $\mathcal{P}(C([0,T];\mathbb{R}^{d}))^{2}$, where $C([0,T];\mathbb{R}^{d})$ is the set of all continuous functions from $[0,T]$ to $\mathbb{R}^{d}$ and $\mathcal{P}(C([0,T];\mathbb{R}^{d}))^{2}$ is the space of all probability measures on $C([0,T];\mathbb{R}^{d})\times C([0,T];\mathbb{R}^{d})$.

If a subsequence of $\{(\tilde{Z}^{n}(\cdot),\tilde{W}^{n}(\cdot))\}_{n\in\mathbb{N}}$ converges in law to a limiting process $\{z^{*}(\cdot),w^{*}(\cdot)\}$, then $z^{*}(\cdot)$ is a solution to the ODE $\dot{\mathbf{x}}(t)=F(\mathbf{x}(t))$ for $t\geqslant 0$, belonging to a compact, connected, internally chain transitive invariant set corresponding to this ODE, and each of
\begin{align}
&w^{*}(t)-\int_{0}^{t}\left(J_{F}\left(z^{*}(s)\right)+\frac{\alpha}{2}I_{d}\right)w^{*}(s)ds \quad \text{and}\nonumber\\
&\left[w^{*}(t)-\int_{0}^{t}\left(J_{F}\left(z^{*}(s)\right)+\frac{\alpha}{2}I_{d}\right)w^{*}(s)ds\right]\left[w^{*}(t)-\int_{0}^{t}\left(J_{F}\left(z^{*}(s)\right)+\frac{\alpha}{2}I_{d}\right)w^{*}(s)ds\right]^{T}-\int_{0}^{t}Q\left(z^{*}(s)\right)ds,\nonumber
\end{align}
is a martingale for $t\in[0,T]$, where $I_{d}$ indicates the $d$-dimensional identity matrix. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Kato--Ponce estimates;
	see \cite{Kenig-Ponce-Vega-1991-JAMS}) of arXiv:2609.02019, '2609.02019'] Let $s>0$. For sufficiently smooth $f$ and $g$,
	\[
	\|[\mathcal D^s,f\mathbf I]g\|_{L^2}
	\lesssim_s
	\|\partial_xf\|_{L^\infty}
	\|\mathcal D^{s-1}g\|_{L^2}
	+
	\|\mathcal D^sf\|_{L^2}
	\|g\|_{L^\infty},
	\]
	and
	\[
	\|\mathcal D^s(fg)\|_{L^2}
	\lesssim_s
	\|f\|_{L^\infty}
	\|\mathcal D^sg\|_{L^2}
	+
	\|\mathcal D^sf\|_{L^2}
	\|g\|_{L^\infty}.
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro cor:momentmatching of arXiv:2605.07920, 'Primitive Sequences for Probability Measures on Compact Intervals'] Suppose that $c_1, \ldots, c_m$ are the first $m \geq 1$ terms of an admissible sequence for $[a,b]$. Then for every integer $k \geq 0$, 
    \begin{equation*}
        M_m^+(k; c_{1:m}) := \sup_{\mu \in \pazocal{F}_m(c_{1:m})} \int_{[a,b]} \frac{(b-t)^k}{k!} \mu(\mathop{}\!\mathrm{d} t)
        \end{equation*}
    and
    \begin{equation*}
        M_m^-(k; c_{1:m}) := \inf_{\mu \in \pazocal{F}_m(c_{1:m})} \int_{[a,b]} \frac{(b-t)^k}{k!}  \mu(\mathop{}\!\mathrm{d} t) 
    \end{equation*}
    are attained by $(m+1)$-atomic measures. Equivalently, if $X$ is any random variable on $[a,b]$ with given moments $\mathbb{E}[X^k]$ for $k=1,\ldots,m$, then sharp bounds on $\mathbb{E}[p(X)]$ for any degree-$r$ polynomial $p$ are attained by discrete random variables supported on at most $m+1$ points. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2609.02327, 'On the counting function of square-full numbers'] For $x \geqslant x_0$, where $x_0$ is sufficiently large, unconditionally we have

			\begin{equation}
				\sum_{n\leqslant x} f_2(n)= \frac {\zeta (\frac {3}{2})}{\zeta (3)} x^{\frac {1}{2}} + \frac {\zeta (\frac {2}{3})}{\zeta (2)}  x^{\frac {1}{3}}+
				\sum_{\substack{\rho=\frac{\beta}{6}+i\frac{\gamma}{6},\; \zeta(6\rho)=0,\\0<6\beta <1,\;|\gamma |< c_3 x^{\frac{105}{226-168\epsilon}},\\1\leqslant {\rm ord}(6\rho)\ll \log (c_3 x^{\frac{105}{226-168\epsilon}})}}{{\rm Res}\atop s=\rho}\left[\frac{\zeta(2s) \ \zeta (3s)}{\zeta(6s)}\; \frac{x^s}{s}\right]+O_{\epsilon}\left ( x^{\frac{1}{12} + 10 \epsilon} \right)
			\end{equation}
			for some positive constant $c_3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor FDkSk of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Let $a_{1},\cdots,a_{m}\in\mathbb{C}$ be given
fixed numbers. Consider the $\mathfrak{sl}_{m+1}(\mathbb{C})$-development
defined by ((eq:FI of the paper)) where $A\in\mathfrak{h}$ is chosen to be
such that $[A,E_{k,k+1}]=a_{k}E_{k,k+1}$ for all $k=1,\cdots,m.$
Then one has 
\begin{equation}
\hat{F}(D_{k}\tilde{L})=\sum_{j=1}^{m-k+1}S_{k}(a_{j},\cdots,a_{j+k-1})E_{j,j+k}
\end{equation}
for all $k=1,\cdots,m.$

PRIVATE REDUCTION, author-recorded. Heydenreich-van der Hofstad Open Problem 13.4 asks that the second largest cluster at p_c(1 + eps) on {0,1}^d match, to leading order, the largest cluster at p_c(1 - eps), eps >> 2^{-d/3}. G(n,p) has this by exact symmetry after removing the giant; the hypercube does not, so it must come from tails: the subcritical largest cluster is Theta(eps^{-2} log(eps^3 2^d)) once the tail P(|C| >= k) >= c k^{-1/2} exp(-c' eps^2 k) holds with the SHARP rate in eps^2 k (the upper bound is known, the sharp lower bound is the missing half), and the supercritical second-largest needs the same tail for the clusters after removal of the giant, which is the geometric-depletion question of the exploration process. So the duality principle is equivalent to two tail statements, one subcritical with a sharp rate and one post-giant.
Bernoulli bond percolation on the hypercube {0,1}^d
Critical window width 2^{-d/3}

[Proposition 40 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $\xi$ and $\psi$ be associated with the multi-species model given in~\eqref{e.def H_N}--\eqref{e.def.FN.delta0}.
For every $t > 0$ and $q \in \mcl Q_1^\sS$, there exist $p^+, p^- \in \mcl Q_{\infty,\leq \lambda_\infty}^\sS$ such that 
\begin{equation}
p^+=\partial_q\psi(q+t\nabla\xi(p^+)), \qquad p^-=\partial_q\psi(q+t\nabla\xi(p^-)),
\end{equation}
and
\begin{equation}
\sP_{t,q}(p^-) \le \liminf_{N \to \infty} \bar F_N(t,q) \le \limsup_{N\to\infty} \bar F_N(t,q)\leq \sP_{t,q}(p^+).
\end{equation}

