[Theorem 3 (Total stability of SSB) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Make the same assumptions as in Theorems \ref{thm:continuous_kernel_stability} and \ref{thm:continuous_margin_stability}. Let $d\mathcal{R} = e^{-\kappa}d(\mu_0 \otimes \mu_1)$ and $d\mathcal{R}' = e^{-\kappa'}d(\mu_0' \otimes \mu_1')$. Further assume that
		\begin{align}
			e^{-M} \leq \frac{d(\mu_0 \otimes \mu_1)}{d(\mu_0' \otimes \mu_1')} \leq e^{M} \quad \mu \otimes \nu \text{ a.s. }
		\end{align}
		for some $M \ge 0$. Then 
		\begin{align}
		&	d_{H}(\pi^{\mu_{0}, \mu_{1}; \mathcal{R}}, \pi^{\mu_{0}', \mu_{1}'; \mathcal{R}'})^2\\
		&\qquad	\leq 8(\norm{\kappa}_{\infty} + M) \left( \norm{\rho_{\r} - \rho_{\r}'}_{L^1(\mu)} + \norm{\rho_{\c} - \rho_{\c}'}_{L^1(\nu)} \right) + 4e^{3(\norm{\kappa}_{\infty} + M) \vee \norm{(\kappa')}_{\infty}}\, d_{H}(\mathcal{R}, \mathcal{R}')^2.
		\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] The process $(Z_u^+)_{u\ge0}$ is a Feller process on $E\times[0,\infty)$ with the generator $\mathfrak{A}^+$ such that
		\begin{align*}
			\mathfrak{A}^+ h(x,t)&=-a\,h(x,t)+b(G-\partial_t^{(0,\infty)})h(x,t)\\
			&\hspace{4em}+\int_0^\infty \left(P_sh\big(\cdot,(t-s)\vee0\big)(x)-h(x,t)\right)\nu(ds),
		\end{align*}
		for all $h\in \mathrm{span} \{(x,t)\mapsto f(x)g(t): f\in \DD(G),g\in C_{00}^1([0,\infty))\}$.\footnote{Here $C_{00}^1([0,\infty))\coloneqq \{f\in C_0([0,\infty)):f\in C^1(0,\infty),\, \lim\limits_{t\searrow0}f'(t)=\lim\limits_{t\to\infty}f'(t)=0\}=\{f\in C_0([0,\infty)):f\in C^1(0,\infty),\, \lim\limits_{t\searrow0}(f(t)-f(0))/t=\lim\limits_{t\to\infty}f'(t)=0\}$, and $\partial_t^{(0,\infty)}f(t)=f'(t)\1_{t>0}$, $f\in C_{00}^1([0,\infty))$.}

