body:
[Thm PSY of arXiv:2411.09640, 'Random Lipschitz functions on graphs with weak expansion'] Let $G$ be a connected $\lambda$-expander where $\lambda\le\frac{d}{32(M+1)\log(9Md^2)}$, and $v_0 \in V(G)$. If $f \in_R\mbox{\rm{Lip}}_{v_0}(G;M)$, then 
\begin{equation}\label{range.ub'} R(f)=O\left(M\left\lceil\frac{\log\log n}{\log(d/\lambda)}\right\rceil\right)\end{equation}
    w.h.p. as $n \rightarrow \infty.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo lgp of arXiv:2411.07158, 'Markov chains on trees: almost lower and upper directed cases'] Let $\pi^{T{(k)}}$ be  the ${\sf h}$-invariant measure of $\;{\sf U}^{T{(k)}}$ on the finite tree $T{(k)}$, normalized by $\pi_{\varnothing}^{T{(k)}}=1$.
	\begin{itemize} \topsep0pt   \itemsep=0pt   \partopsep=0pt   \parsep=0pt \setcounter{c}{0}
	\addtocounter{c}{1}\item[($\roman{c}$)] 	$(a)$ the measures  $\pi^{T{(k)}}$ and $\pi^{T{(k-1)}}$ coincide on $T{(k-1)}$,\\
	$(b)$ to compute the value $\pi^{T{(k)}}_{u_k}$ (on the additional node) using $\pi^{T{(k-1)}}$,
	\begin{eqnarray} 
	\pi^{T{(k)}}_{u_k}    ={\displaystyle\sum_{v\in \cro{\varnothing,p(u_k)}} \pi^{T{(k-1)}}_{v} {\sf U}_{v,T_{u_k}}}/ {{\sf U}_{u_k,p(u_k)}} .\end{eqnarray}
	\addtocounter{c}{1}\item[($\roman{c}$)] The measures $(\pi^{T{(k)}},k\geq 0)$ are consistent (that is $\pi^{T{(k+1)}}$ and  $\pi^{T{(k)}}$ coincide on $T{(k)}$, for all $k$), so that there exists a measure $\rho$ on $T$, such that $\rho\big|_{T{(k)}}=\pi^{T{(k)}}$. This measure $\rho$ is the \textsf{h}-invariant measure $\pi$ of ${\sf U}$.
	\end{itemize}\vspace{-2em}~ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem measurable density of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $p$ be a stochastic kernel on $\mathbb R^d$ such that $p(x,\cdot)$ is absolutely continuous with respect to $\mathrm {Leb} $ for all $x\in \mathbb R^d$. Then, $p$ has a jointly measurable density; in other words there exists a function $f:\mathbb R^d\times \mathbb R^d\to[0, \infty)$ that is $\mathcal B(\mathbb R^d\times \mathbb R^d)$-measurable\footnote{$\mathcal B(\mathbb R^d\times \mathbb R^d)$ denotes the Borel $\sigma$-algebra of $\mathbb R^d\times \mathbb R^d$.} and such that 
	\begin{equation*}	
		p(x,A)=\int_Af(x,y)\mathrm {Leb}  (\mathrm d y),\qquad x\in \mathbb R^d, A\in \mathcal B(\mathbb R^d).
	\end{equation*}

