[Theorem thm:lipschitzconcentration of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] There is some $\eta > 0$ as well as constants $C, c > 0$
such that the following holds for $X \sim \mu_\mathsf{H}^\eta(n,p)$.
For any function $f$ with Lipschitz vector $\mathcal{L}$ and $\lambda \geq 0$ with
$\lambda \leq c \| \mathcal{L} \|_1$,
\begin{equation}
    \mathbb{P}[| f(X) - \mathbb{E}[f(X)] | > \lambda]
    \leq 2 \Exp{ - c \cdot \max \mleft\{
      \frac{\lambda^2}{n^2 \| \mathcal{L} \|_\infty^2},
      \frac{\lambda^2}{\| \mathcal{L} \|_1 \| \mathcal{L} \|_\infty} - \Exp{\frac{C \lambda}{\| \mathcal{L} \|_\infty} - c n}
      \mright\} }
      + e^{-c n}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm th:2.3 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Suppose $\xi = g_\alpha = 1-2\sqrt{\alpha}$, $f$ satisfies Assumption~(assumpt:2.1.1 of the paper) with $\alpha_n = 1$ and $\{x_n^f, n \in \mathbb{N}\}$ fulfils Assumption~(assumpt:2.7 of the paper). \\
	Case 1: if $d < \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation} 
	\begin{aligned}
	& \lim_{T \to \infty} \mathbb{P}(x^f_{\alpha T}(T) > (1-2\sqrt{\alpha})T - S T^{1/3}) \\
	&= \mathbb{P} \Bigl ( \sup_{\tau \geq 0} \{ \mathcal{A}_2(\tau)-g_n(\tau) \} < c_1^{-1} S \Bigr ) 
	\times  \Phi_{n-1}^{\alpha_0, \dots, \alpha_{n-1}}(S).
	\end{aligned} 
	\end{equation}
	Case 2: if $d = \tfrac{1}{\sqrt{\alpha}}$, then it holds
	\begin{equation}  
	\begin{aligned}
	& \lim_{T \to \infty} \mathbb{P}(x^f_{\alpha T}(T) > (1-2\sqrt{\alpha})T - S T^{1/3}) \\ 
	&= \mathbb{P} \Bigl ( \sup_{\tau \geq 0} \{ \mathcal{A}_2(\tau)-g_n(\tau) \} < c_1^{-1} S, \ \sup_{\tau  \leq 0} \{ \mathcal{A}_2(\tau)-\tau^2 - y(-\tau) \} < c_1^{-1} 	S \Bigr ) \\ 
	& \hphantom{=} \times \Phi_{n-1}^{\alpha_0, \dots, \alpha_{n-1}}(S).
	\end{aligned} 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t: stealthy characterization of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally absolutely square-integrable invariant random complex measure. Then $\Phi$ is $\infty$-uniform iff there is a function $f\in L^1(\R^d, \C)$ with $\lambda_d(f)\neq0$ such that $\BV[\Phi(f)]=0$. Further, if $\hat{f}(k)\neq 0$ for all $k\in B_{\varepsilon}$ and some $\varepsilon>0$, then $\Phi$ is $\infty$-uniform with radius $\varepsilon$. Conversely, if $\Phi$ is $\infty$-uniform with radius $\varepsilon>0$, then $\BV[\Phi(f)]=0$ for all $f\in L^1(\R^d, \C)$ with $\hat{f}(k)=0$ for all $k\in B_\varepsilon^c$.
\begin{proof}
    Basically, the assertions follow directly from the definition of $\infty$-uniformity with radius $\varepsilon$ and the fact that by the covariance formula~(equation e: spectral covariance formula of the paper),
    \begin{equation}
        \BV[\Phi(f)] = \frac{1}{(2\pi)^d}\int |\hat{f}(k)|^2\, \hat\beta_\Phi(dk).
    \end{equation}
    For the first assertion, one should also note that if $\lambda_d(f)\neq 0$, then $|\hat{f}(0)|^2 > 0$, which stays true in a neighborhood of $0$ since $f\in L^1$, whereby $\hat{f}$ is continuous.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] In any compact subset $B$ of the subcritical region \cref{Sub},

we have
\ben{
d_{\rm{loc}}(E_n, Z_{\mu_n, \sigma_n^2}^{(d)})\leq C n^{-9/8},
}
where $C$ is a constant depending only on $B$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d: Wasserstein distance of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi, \Psi$ are invariant random (nonnegative) measures with the same finite intensity. For $p\in [1,\infty)$ define
    \begin{align}
        W_p(\Phi, \Psi) := \inf\bigg\{\bigg(\BE_0^\Phi\bigg[\int\|x\|^p\, K_0(dx)\bigg]\bigg)^{\frac{1}{p}}: K \text{ invariant proba} &\text{bility kernel} \nonumber\\
        &\text{with } \Psi=K\Phi\bigg\},
    \end{align}
    and for $p=\infty$ define
    \begin{align}
        W_\infty(\Phi, \Psi) := \inf\bigg\{\sup_{\substack{\omega\in A\\ x\in\supp(K_0(\omega))}} \|x\| : K &\text{ invariant probability kernel}\nonumber\\ &\text{with } \Psi=K\Phi,A\in \cF, \BP_0^\Phi(A)=1\bigg\},
    \end{align}
    then $W_p(\Psi, \Phi)$ is called the $p$- or $L^p$-Wasserstein distance.

[Proposition 12 (Endpoint factorization) of arXiv:2605.11451, '2605.11451'] Let $1\le p<\infty$, $n\ge2$, and $1\le k\le n$. Then
\begin{equation}
 A_{p,n,0}(u^{(k)})
 =
 \frac{\Gamma(1+n/p)}{\Gamma(1+(n-1)/p)}
 \frac{\Gamma(1+(k-1)/p)}{(2\Gamma(1+1/p))^k}
 S_{p,k}.
\end{equation}
Equivalently,
\begin{equation}
 A_{p,n,0}(u^{(k)})
 =
 \frac{\Gamma(1+n/p)}{\Gamma(1+(n-1)/p)}\,b_{p,k},
\end{equation}
where
\begin{equation}
 b_{p,k}:=
 \frac{\Gamma(1+(k-1)/p)}{(2\Gamma(1+1/p))^k}S_{p,k}.
\end{equation}

