[Theorem thm:L of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] Let (asn:b of the paper) and (asn:sigma of the paper) hold. Let $\chi\in\mathrm{Cut}_d$,  $p\in[1,\infty)$, $\theta\in[0,1]$,  and let $X$ and $Y$ be two solutions to (equation eq:main of the paper). For $f\in \mathcal{C}^1$ define the process
\begin{equ}
J_t=\int_0^t\chi_{\rho}(X_r-Y_r)f\big(\theta X_r+(1-\theta)Y_r\big)\,dr.
\end{equ}
Then for any $\gamma\in(-1/(2H),0)$ 
there exists a constant $C$ such that for all $(s,t)\in[0,1]^2$ one has
\begin{equ}
\|J_{t}-J_s\|_{L^p(\Omega)}\leq C\|f\|_{\mathcal{C}^{\gamma}}|t-s|^{1+\gamma H}
\end{equ}
and $C=C(\alpha,\gamma,p,d, \chi, \lambda,H,\|\sigma\|_{\mathcal{C}^5},C^X_{D, p}, C^X_{S, 2p}, C^Y_{D,p}, C^Y_{S, 2p})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 21 (Dubins' inequality for finite time, $T < \infty$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $f_0, f_1, \ldots, f_T,$ be a given real valued supermartingale sequence with $f_n \geq c $ where $c$ is a constant. Assume the definitions of $\rho_k, \tau_k$ given by Definition \ref{upcrossing_stopping_times}  with $T < \infty$ (i.e. the finite time case). Furthermore, assume
that $(L)-a.e.$ holds; then,
for any $k\ge 0$ and $c \leq a < b$:
\begin{equation} \nonumber 
\overline{\sigma}({\bf 1}_{\{\tau_{k+1} < T+1\}}) \leq \left(\frac{a-c}{b-c} \right)~~ \overline{\sigma}({\bf 1}_{\{\rho_{k}  < T+1\}}) \leq
\left(\frac{a-c}{b-c}\right)~~ \overline{\sigma}({\bf 1}_{\{\tau_{k}  < T+1\}}),
\end{equation}
and so
\begin{equation} 
\overline{\sigma}({\bf 1}_{\{\tau_{k+1}  < T+1\}}) \leq
\left(\frac{a-c}{b-c} \right)^{k+1} ~\overline{\sigma}({\bf 1}_{\{\rho_{0}  < T+1\}}) \leq
\left(\frac{a-c}{b-c}\right)^{k+1}.
\end{equation}

[Definition 89 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] We say that $X$ is a {\em regular
diffusion process 
\index{$D$@Processes!regular
diffusion process}
corresponding to
$\cL$ or to $a,b$\/} if



(i)  for any $(t,x)\in\bR^{d+1}$
there exists a $d$-dimensional Wiener process $w_{t}$, $t\geq0$,
which is a Wiener process relative to $\bar \cN_{t}$,
where $\bar \cN_{t}$ is the completion of $\cN_{t}$
with respect to all $P_{s,y}$, and such that with    
$P_{t,x}$-probability one, for
all $s\geq 0$, $\sft_{s}=t+s$ and
\begin{equation} 

x_{s}=x+\int_{0}^{s}\sigma(t+u,x_{u})\,dw_{u}
+\int_{0}^{s}b(t+u,x_{u})\,du.
\end{equation}

(ii) there exists $\rho_{b}\in(0,\infty)$ such that
\begin{equation}

  \bar b_{\rho_{b}}=\sup_{r\leq\rho_{b}}r^{-1}
\sup_{(t,x)\in\bR^{d+1}}\sup_{C\in\bC_{r}}
E_{t,x}\int_{0}^{\tau_{C}}|b(\sft_{s},x_{s})|\,ds \leq \sfb_{0},
\end{equation}
where $\tau_{C}$ is the first exit time of 
$(\sft_{s},x_{s})$ from $C$.

[Defi 9 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Denote the canonical variable on $\mathscr{X}\times\mathcal{H}$ by $(\mathbb{X},u)$ and consider the space of probability measures
    \begin{align*}
        \mathcal{Y}\coloneq \{\mu\in \mathcal{P}(\mathscr{X}\times\mathcal{H})\ |\ \mathbb{E}_\mu[\Vert u\Vert_\mathcal{H}^2]<\infty\}.
    \end{align*}
    We equip this space with the topology induced by the convergence $\mu_n\to\mu$ which is defined as follows:
    \begin{itemize}
        \item $(\mu_n)_{n}$ converges to $\mu$ weakly on $\mathscr{X}\times \mathcal{H}_w$, where $\mathcal{H}_w$ is $\mathcal{H}$ equipped with the weak topology,
        \item $\sup_n\mathbb{E}_{\mu_n}[\Vert u\Vert_\mathcal{H}^2]<\infty$.
    \end{itemize}
    Let 
    \begin{align}
        \mathcal{X}\coloneq \{\mu\in\mathcal{Y}\ |\ \mu=\Law_\mathbb{P}(\mathbb{Y},u)\text{ for some }u\in\mathbb{H}\}
    \end{align}
    and denote by $\bar{\mathcal{X}}\subset\mathcal{Y}$ the closure of $\mathcal{X}$ in $\mathcal{Y}$.

[Defn eq:tau-col of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] For $v\in\mathds{T}_n$ and $t\geqslant0$, define the one-source passage times and
passage-time balls by
\begin{align*}
 \mathsf{T}_1(v)&:=T_{\mathds{T}_n}^{(\ell)}(0,v),
 &
 \mathcal{A}_1(t)&:=\{v\in\mathds{T}_n:\mathsf{T}_1(v)\leqslant t\},\\
 \mathsf{T}_2(v)&:=T_{\mathds{T}_n}^{(\ell)}(U_n,v),
 &
 \mathcal{A}_2(t)&:=\{v\in\mathds{T}_n:\mathsf{T}_2(v)\leqslant t\}.
\end{align*}
The \emph{original-time collision time} is
\begin{align}
\tau_{\mathrm{col}}:=\inf\Big\{t\geqslant0:
&\text{ there exist }u\in\mathcal{A}_1(t),\ v\in\mathcal{A}_2(t)
\text{ with }\{u,v\}\in\mathcal{E}_n^{(\ell)}
\text{ and} \notag\\
&\go_{u,v}
\leqslant (t-\mathsf{T}_1(u))+(t-\mathsf{T}_2(v))
\Big\}.
\end{align}
Its rescaled version is
\begin{align*}
 \mathsf{S}_{\mathrm{col}}:=\mathfrak{a}_\ell\tau_{\mathrm{col}}.
\end{align*}

[Prop 7 of arXiv:2604.06516, 'From stochastic individual-based models to free-boundary Hamilton-Jacobi equations'] Let $x\in\R$. We consider the birth-death-mutation process $(Z^K_t,t\ge 0)$ defined as before but started from a unique individual with trait $x$, i.e.\ $Z^K_0=\delta_{x}$, and we denote the corresponding expectation by $\mathbb{E}_{\delta_x}$.\\ 
(i) Let $\varphi:\R\to\R$ be bounded and measurable. Then, for any $t>0$, we have
		\begin{equation}

			\mathbb{E}_{\delta_{x}}\left[\langle {Z}^K_{t}, \varphi\rangle \right]=\mathbb{E}_{x}\left[\exp\left(\int_{0}^{t} R(X^K_s)\ ds \right)\varphi(X^K_{t}) \right],
		\end{equation}
		where $X^K$ is the  process defined in  \eqref{marchealeatoire}.\\
(ii) For $t>0$, $x\in \R$ and for a bounded measurable function $\Phi:\mathbb{D}[0,t]\to\mathbb{R}$,
		\begin{equation}

			\mathbb{E}_{\delta_x}\left[\langle {\Theta}^K_t,\Phi\rangle\right]=\mathbb{E}_{\delta_{x}}\left[\sum_{u\in {V}^K_{t}}\Phi({X}^{K,u}_{s},\ s\leq t) \right]
            =\mathbb{E}_{x}\left[\exp\left(\int_{0}^{t} R(X^K_{s})\ ds \right)\Phi(X^K_{s},\ s\leq t) \right].   
		\end{equation}
(iii) For all $t>0$ and $A\subset\mathbb{D}[0,t]$,
\begin{align*}
        \E (N^{K,A}_{t})  & =\int_\R K^{\beta^K_0(x)}\E_{\mu^K_{x,T}}\Big[\exp\Big(\log K\int_0^{t} R(Y_s^K) ds \Big)\mathbbm{1}_{(Y^K_{s})_{s\in[0,t]}\in A}\Big]dx.
\end{align*}

[Theorem 1 of arXiv:2607.17396, '2607.17396'] Let $\left\{X_{k}, k \geq 0 \right\}$ be a critical branching process with immigration with $\lambda \in \left(0, \infty\right)$, $b^{2}\in \left(0, \infty\right)$ and $\sigma^{2}\in \left(0,\infty\right)$.
Assume that the immigration sequence $\left\{{{\varepsilon_k},k\geq 1} \right\}$ is a strictly stationary and ergodic sequence adapted to a stationary non-decreasing filtration $\left\{\mathcal{H}_{i}, i \in \mathbb{Z}\right\}$ such that $\delta_{n,2}=o\left(\sqrt{n}\right)$ as $n \to \infty$.

Then
\begin{equation}
 Y_{n} \mathop{\to}\limits^{\mathcal{D}} Y, \qquad n\to \infty,
\end{equation}
where the limit process $Y=\left\{Y\left(t\right), t \geq 0 \right\}$ is the pathwise unique strong solution of the stochastic differential equation (SDE)
\begin{equation}
 \mathrm{d} Y\left(t\right) = \lambda \mathrm{d}t+\sigma \sqrt{Y\left(t\right)^{+}} \mathrm{d} W\left(t\right)
\end{equation}
with initial condition $Y(0)=0$, where $\left\{W\left(t\right), t \geq 0 \right\}$ is a standard Wiener process. (Proof in the paper; no proof environment follows the statement in the TeX.)

