[Theorem 1 of arXiv:2608.27156, 'Traveling Waves in Equity Markets with\\Rank-Based Entry and Exit'] Assume $\lambda_b, \lambda_d, b \in C^1([0,1])$ and $\sigma^2 \in C^1([0,1])$ with $\min_{[0,1]} \sigma^2 > 0$, and let the initial positions be independent samples from a distribution on $(0,\infty)$ with continuous CDF $u_0$ and $\E|\log X^1_0| < \infty$. Set $m(t) := e^{f(1)t}$. Then for every $T > 0$,
\begin{equation}
    \sup_{t \leq T}\, \Big( \big|m^n_t - m(t)\big| + \sup_{x > 0}\, \big| F^n(t,x) - m(t)\, w(t,\log x) \big| \Big) \;\longrightarrow\; 0
    \quad \text{in probability as } n \to \infty,
\end{equation}
where $w$ is the unique CDF solution (in the sense of Lemma~\ref{lem:uniqueness} below), in the log-capitalization variable $y$, of the quasilinear reaction-diffusion equation
\begin{equation}
    \pp_t w \;=\; \pp^2_{yy} A(w) - \pp_y B(w) + \tilde f(w),
    \qquad w(0, y) = u_0(e^y),
\end{equation}
with
\begin{equation*}
    A(q) \;=\; \int_0^q \frac{\sigma^2(r)}{2}\,\d r, \qquad
    B(q) \;=\; \int_0^q \tilde b(r)\,\d r, \qquad
    \tilde b \;=\; b - \frac{\sigma^2}{2}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:volume-recovery of arXiv:2609.01464, 'Removability of non-isolated singularities for Einstein metrics and RCD spaces'] Suppose $(X_k,\mathrm{d}_k,\mathcal H^n,x_k)$ is a sequence of pointed
$\operatorname{RCD}(-\eta_k,n)$ spaces, $n\geqslant2$, and $u_k$ satisfies
(equation eq:as-lip of the paper) on $B_6(x_k)$ and (equation eq:as-errors of the paper) with right-hand
side $\kappa_k$.
Assume $\kappa_k+\eta_k\to0$.  Then, for the fixed
$\rho$ in Lemma~(lem:almost-splitting of the paper),
\begin{equation}
 \sup_{0<s\leqslant\rho}
 \left|\frac{\mathcal H^n(B_s(x_k))}{\omega_ns^n}-1\right|\to 0.
\end{equation}

[Lemma lem-Galerkin_estimates' of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] \begin{enumerate}
\item $\overline{u}_n$ is almost surely in $\mathbb{D}([0,T];P_nH)$ and for any $p\in [2, 4+\gamma)$ there exists a constant $C_1(p)>0$
\begin{equation} 
 \sup_{n\in \mathbb{N} } \overline{\mathbb{E}}\left[ \sup_{ s\in [0,T] } \bigl| {\overline{u}}_{n} (s){\bigr| }_{H}^{p}\right] \le {C}_{1}(p),
\end{equation}
\begin{equation} 
  \sup_{n\in \mathbb{N} } \overline{\mathbb{E}}\left[ \int_{0}^{T} {\bigl\| {\overline{u}}_{n} (s)\bigr\| }_{V}^{2} \, \mathrm{d}s \right] \le {C}_{2}.
\end{equation}
\item $\overline{u}$ satisfies the following estimates
\begin{equation} 
\overline{\mathbb{E}} \left[ \int_{0}^{T} \lVert \overline{u} (s)\rVert_{V}^{2}\, \mathrm{d}s \right] < \infty,
\end{equation}
\begin{equation} 
\overline{\mathbb{E}}\left[ \sup_{s\in [0,T] } \bigl| \overline{u} (s){\bigr| }_{H}^{2}\right] < \infty.
\end{equation}
\end{enumerate}

