body:
[Proposition pro:CheegerPoincareBounds of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $D \geqslant 2$ be an integer and $U$ be a doubly stochastic irreducible $D \times D$ transition matrix. Let $U^+$ be the additive symmetrisation of $U$. Then
    \begin{enumerate}[label=(\alph*)]
        \item The Cheeger constant $\Phi_{\ast}(U)$ of $U$ is equal to that of $U^T$ as well as to that of $U^+$.

        \item The spectral gap $\gamma^+$ of $U^+$, also known as the \emph{Poincar\'e constant} of $U$, satisfies $\gamma^+ \asymp \Phi_{\ast}(U)$.

        \item The following \emph{Poincar\'e inequality} holds: For any distribution $\nu$ on $[D]$, writing $\pi$ for the uniform distribution on $[D]$, we have that for all $t \geqslant 0$,
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \leqslant \mathrm{e}^{-\gamma^+ t} \left\lVert\nu - \pi\right\rVert_{2, \pi} = \mathrm{e}^{-\gamma^+ t} \Big( \sum_{x \in [D]} \Big( \frac{\nu(x)}{\pi(x)}-1\Big)^2 \pi(x)\Big)^{\frac{1}{2}}.
        \end{equation*}

        \item In the notation of (c), uniformly in $t \geqslant D$, we have that
        \begin{equation*}
            \normtp{\nu \mathrm{e}^{t(U-I)} - \pi} \lesssim (1+t^D)  \mathrm{e}^{-\gamma (t-D)} \left\lVert\nu - \pi\right\rVert_{2, \pi}.
        \end{equation*}

        \item The worst-case total variation distance from $\pi$ at time $t$, defined as
        \begin{equation*}
            \mathrm{d}_{\mathrm{TV}}(t) \coloneqq \max_{x \in [D]} \normTV{\delta_x \mathrm{e}^{t(U-I)} - \pi},
        \end{equation*}
        where $\delta_x$ is the Dirac measure on $x$, satisfies uniformly in $t \geqslant D$ that
        \begin{equation*}
            \frac 12 \mathrm{e}^{-\gamma t} \leqslant \mathrm{d}_{\mathrm{TV}}(t) \lesssim (1+t^D)  \mathrm{e}^{-\gamma (t-D)}.
        \end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor gamma 1 gamma2 capacity change of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] Let $\gamma$, $\tilde{\gamma}$ be two hulls starting at $e^{ix} \in \partial \mathbb{D}$ and $e^{iy} \in \partial \mathbb{D}$ with capacity $\varepsilon$ and $c \varepsilon$ , let $g_{\varepsilon}$ be the normalized map removing $\gamma$ and $\tilde{\varepsilon}= \operatorname{hcap}(g_{\varepsilon}\circ \gamma(t))$, then we have:

\begin{equation}
\tilde{\varepsilon}=
c \varepsilon\left(1-\frac{\varepsilon}{\sin^2(\frac{x-y}{2})}\right)+o\left(\varepsilon^2\right).
\end{equation}

[Theorem 1 (Gaussian permanent anticoncentration) of arXiv:2607.20329, '2607.20329'] For every $\mathbb K\in\{\R,\C,\Hh\}$ and $n\ge1$,
		$W_n^{\mathbb K}$ has a radial density $p_n^{\mathbb K}$ satisfying
		\begin{equation}
			\|p_n^{\mathbb K}\|_\infty
			=p_n^{\mathbb K}(0)
			\lesssim_\beta n^{(\beta+2)/4}.
		\end{equation}
		Consequently, for every $\varepsilon>0$,
		\begin{equation}
			\sup_{z\in\mathbb K}
			\Pp(|W_n^{\mathbb K}-z|\le\varepsilon)
			\lesssim_\beta n^{(\beta+2)/4}\varepsilon^\beta.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop pb-surj-glo of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let
    \begin{equation}
        \begin{tikzcd}
            A\arrow[r,"g"]\arrow[d,"q"']\arrow[dr,pullback] & B\arrow[d,"p"]\\
            C\arrow[r,"f"'] & D
        \end{tikzcd}
    \end{equation}
    be any pullback square in the 1-category of compact Lie groups such that the homomorphism $p$ is \emph{surjective}. Then the corresponding square in $\textup{Glo}$ is a pullback.

    In particular, $\textup{Glo}$ has finite products, given by products in the 1-category of compact Lie groups. (Proof in the paper; no proof environment follows the statement in the TeX.)

