body:
[Lemm 19 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] Assume that the FBSDE \eqref{fbsde:equ} satisfies all the condition of Theorem \ref{theorem:path-regularity} with $p \geq 2$,
    and it admits a unique $\cL^p$-solution $(X,Y,Z)$.
    If its coefficients satisfy Assumption \ref{assme:fractionalPotential}, and one of the following conditions holds:
    \begin{itemize}
        \item[(\textbf{Case I})] $p > 2$,
        $R_i$ is uniformly Lipschitz in $\tz$ which does not depend on $z$, and
        \begin{align}
            \sup_{u\in [t,T]} \sup_{r\in (0,1]} \frac{\left[\E\left[\left|V_i^{\vz_r} (u) - V_i(u)\right|^{\frac{2\bz_i p}{p - 2}}\right]\right]^{\frac{p - 2}{p}}}{r^2} < \fz,
        \end{align}
        for all $i\in \{1,2,3,4\}$.
        \smallskip

        \item[(\textbf{Case II})] $p \geq 2$, $R_i$ is uniformly bounded, and
        \begin{align}
            \sup_{u\in [t,T]} \sup_{r\in (0,1]} \frac{\E\left[\left|V_i^{\vz_r} (u) - V_i(u)\right|^{2\bz_i}\right]}{r^2} < \fz,
        \end{align}
        for all $i\in \{1,2,3,4\}$.
    \end{itemize}
    Then \eqref{equ:Sobolev:cond:g} holds.

