{"artifact_digest":"sha256:6428a29a6e7732ef0b8aebeb0f4e521093a3c7a709f9ea8218c0ee18dcf4a00b","artifact_path":"objects/sha256/64/6428a29a6e7732ef0b8aebeb0f4e521093a3c7a709f9ea8218c0ee18dcf4a00b.md","bundle_digest":"sha256:b29a3f45aee696cad878a0debdb9fe4b9cc1f54c26e4e50dbfaef172f1e4df39","bundle_entry_key":"2606-18047-theorem-12-asymptotics-of-var-d-n","bundle_id":"population.tex-extract-s3_053","claim_kind":"theorem","conditions":[],"domain":"probability theory","draft":"tex-extract-20260907/bundle_s3_053.json","evidence_ids":[],"logical_id":"math:harvest.arxiv.mathematics:arxiv-2606-18047-theorem-12-asymptotics-of-var-d-n","overlay_schema_version":1,"proof_text":"Paper's own proof, opening: Put $\delta=2p-1$. For $1\leq \ell\leq m$, define
