[Theorem 4 (Decision-boundary representation of the error-rate Hessian) of arXiv:2609.00774, 'Semi-Supervised Classification with Informative Missing Labels in Weibull Mixture Models'] Under \Cref{ass:boundaries}, with $p_Y$ continuous at the boundaries,
\begin{equation*}
 \left.\frac{\partial R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta}\right|_{\widetilde\theta=\theta}=0,
\end{equation*}
and
\begin{equation}
 H_{R}(\theta)
 :=\left.\frac{\partial^2 R(\widetilde\theta;\theta)}
 {\partial\widetilde\theta\partial\widetilde\theta^\top}
 \right|_{\widetilde\theta=\theta}
 =\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{2|\delta_y(y_j;\theta)|}
 g(y_j;\theta)g(y_j;\theta)^\top.

\end{equation}
Let $\widehat\theta$ satisfy
\begin{equation}
 \sqrt n(\widehat\theta-\theta)\xrightarrow{d}N(0,V),
 \qquad
 n\E\{(\widehat\theta-\theta)(\widehat\theta-\theta)^\top\}\longrightarrow V,

\end{equation}
and suppose that, for some $\epsilon>0$,
\begin{equation}
 \E\|\sqrt n(\widehat\theta-\theta)\|^{2+\epsilon}=O(1).

\end{equation}
Then
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top Vg(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For a correctly specified regular maximum-likelihood estimator satisfying the stated moment conditions,
$V=\J(\theta)^{-1}$, so
\begin{equation}
 \E\{R(\widehat\theta;\theta)\}-\err(\theta)
 =\frac{1}{4n}\sum_{j=1}^K
 \frac{p_Y(y_j;\theta)}{|\delta_y(y_j;\theta)|}
 g(y_j;\theta)^\top\J(\theta)^{-1}g(y_j;\theta)
 +o(n^{-1}).

\end{equation}
For the estimator that ignores the missingness mechanism, the same specialisation holds with $\J=\J_{\mathrm{ig}}$ by \Cref{lem:ig-information}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (\ac{SMM} phase transition) of arXiv:2607.12667, 'Phase Transition of Eigenvalues of Covariances from the Spiked Mixture Model in High-dimen'] The extreme eigenvalues of $\Sb_{d,n}$ \eqref{eq:covariance_def} exhibit the following behavior as $n\to \infty$ and $d\to \infty$ with $d/n \to \gamma$. 

Consider $\mathbf{L} \in \mathbb{R}^{K\times K}$ the Gram limiting matrix with entries $\mathbf{L}_{l,m} = \theta_{l,m} \sqrt{\pi_l \pi_m \beta_l \beta_m}$. 
\begin{itemize}
    \item For $1\leq i \leq K$,
    \begin{align*}
    \lambda_i(\Sb_{d,n}) \xrightarrow{\textit{a.s.}}
    \begin{cases}
        T^{-1}(1/\lambda_i(\Lb)) &\quad\text{if } \lambda_i(\Lb) > \sqrt{\gamma} \\
        (1 + \sqrt{\gamma})^{2} &\quad\text{otherwise},
    \end{cases}; \text{ and}
    \end{align*}    
    \item for $i > K$, 
    \begin{align*}
        \lambda_i(\Sb_{d,n}) &\xrightarrow{\textit{a.s.}} (1+\sqrt{\gamma})^2.
    \end{align*}
\end{itemize}
Here,
\begin{align*}
    T(z) &= \int \frac{t}{z-t} d \mu_{\mathrm{MP}(\gamma)}(t) &\text{for } z \in \mathbb{C} \setminus [a,b],
\end{align*}
is the $T$-transform of $\mu$, and $\mu_{\mathrm{MP}(\gamma)}$ is the \acl{MP} distribution with parameter $\gamma > 0$. Its density is 
\begin{align*}
    d \mu_{\mathrm{MP}(\gamma)}(x) = \frac{1}{2\pi \gamma x} \sqrt{(b-x)(x-a)}\ind_{[a,b]}(x) d x + \max\left(0,1-\frac{1}{\gamma}\right)\delta_0,
\end{align*}
where $\ind_{[a,b]}$ is the indicator function, $a := (1-\sqrt{\gamma})^2$ and $b :=(1+\sqrt{\gamma})^2$ denote the edges of the bulk of the distribution, and $\delta_0$ is the Dirac delta at location  $0$.
The inverse $T$-transform associated with $\mu_{\mathrm{MP}(\gamma)}$ is
\begin{align*}
    T^{-1}(l) = (1+1/l)(1+\gamma l).
\end{align*}
Note that for $l\in \mathbb{R}^+$ we indeed have $T^{-1}(1/l) \geq b$ with equality only for $l=\sqrt{\gamma}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma mns1-mns2 lemma used for passing limit of arXiv:2411.04631, 'Existence of Martingale Solutions to Stochastic Constrained Heat Equation'] For all $t_1,t_2 \in [0,T]$ with $t_2 \leq t_1$, for all $\phi$ in $ \mathcal{V}$ and for all $h$ in $\mathcal{C}([0,T], \mathcal{H})$. Then following holds.
    \begin{align}
        \lim_{n \rightarrow \infty }\hat{\mathbb{E}}\left[ \left \langle \hat{M}_{n}(t_1)-\hat{M}_{n}(t_2) , \phi_1 \right \rangle_{\mathcal{H}}h(v_{n|[0,t_2]}) \right]= \hat{\mathbb{E}}\left[ \left \langle \hat{M}(t_1)-\hat{M}(t_2) , \phi_1 \right \rangle_{\mathcal{H}}h(v_{|[0,t_2]}) \right]. 
    \end{align}

