u(3)&=\frac{3\sqrt{2}}{\pi}\,{}_2F_1\bigg({\frac{1}{12},\frac{1}{2} \atop \frac{25}{24}} \; \bigg| \;1\bigg)  \\
&=\frac{1+\sqrt{3}}{2}\,{}_3F_2\bigg({\frac{1}{12},\frac{1}{2},\frac{11}{12} \atop 1,1} \; \bigg| \;1\bigg). 
\end{align}

