body:
[Theorem VD-Volterra of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let 
\begin{equation}
(\mathcal{K}f)(x)=\int_{0}^{1/2}K(x,u)f(u)\,du=\int_{0}^{x}f(u)\,du,\qquad
0\leq x\leq \frac{1}{2},  
\end{equation}
where $K$ is the kernel from \textit{Lemma~(Volterra-kernel-TN of the paper)}. Then 
\begin{equation}
Z(\mathcal{K}f)\leq Z(f)  
\end{equation}
for every continuous function $f$ on $[0,\tfrac{1}{2}]$.

[Cor cortau of arXiv:2605.01878, '\Large Random trade timing and power-law tails in realized prices'] Let $X$ be a real-valued random variable whose Laplace transform $\varphi_X$ satisfy the conditions (lemxpluda of the paper)--(lemxpludc of the paper) of Lemma (lemxplus of the paper). Then there exist finite constants $C_1$ and $C_2$, depending only on
$\alpha$, $\ell$, and $\delta$, such that
\begin{align}
A_\ell C_1
&\le \liminf_{x\to\infty} x^{-\ell+1} e^{\alpha x} \mathbb{P}(X>x) \notag\\
&\le \limsup_{x\to\infty} x^{-\ell+1} e^{\alpha x} \mathbb{P}(X>x)
\le A_\ell C_2. 
\end{align}
If, in addition, $\ell=1$ and $-\alpha$ is the unique singularity of $\varphi_X$ on the
axis $\mathrm{Re} (s)=-\alpha$, then
\begin{align}
\lim_{x\to\infty} e^{\alpha x}\mathbb{P}(X>x) = A_1/\alpha. 
\end{align}

[Definition 6 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $K$ be a graph over $V$. We define the self-overlap of $K$:

\begin{equation} 
    SOV(K) = \operatorname*{lim}_{\eps \to 0} \operatorname*{plimsup}_{n \to +\infty}  \max_{\sigma \in \Sym_n}\max_{\underset{|\mc{A}| \geq \eps n}{\mc{A} \subseteq \Der \sigma}}  \operatorname*{min}_{v \in \mc{A}} w_{(K \land_\sigma K)}(v).
\end{equation}

[Lemma 3 (Weighted-report cluster linearization) of arXiv:2608.30916, 'Selection-Aware Stress Testing for Interactive Agents'] Conditional on $\mathcal F_{\Dcal}$, suppose the conditions of Theorem~\ref{thm:validity} hold. Let $\mu_m=\E(H_{1,m}\mid\mathcal F_{\Dcal})$ and $\Phi_{k,m}=\nabla F_m(\mu_m)^\top(H_{k,m}-\mu_m)$. Uniformly over the finite family $\Jcal_0$,
\begin{equation}
 \sqrt N(\widehat\Delta_m-\Delta_m)
 =N^{-1/2}\sum_{k=1}^N\Phi_{k,m}+o_p(1),

\end{equation}
and the canonical plug-in contributions satisfy
\begin{equation}
 \max_{m\in\Jcal_0}N^{-1}\sum_{k=1}^N
 (\widehat\Phi_{k,m}-\Phi_{k,m})^2\xrightarrow{p}0.

\end{equation}

