[Lemma 73 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For $n\geq 1$ and $z\in\C$,
\begin{eqnarray*}
:\Phi^{n}_{\varepsilon}:(z)&=&
Q_{n}(\nu^{\rm gen}_{0,\varepsilon}(z),V_{A^{\rm gen, +}_{0},\varepsilon}(z)) +
Q_{n}(\Phi_{D\setminus A^{\rm gen, +}_{0},\varepsilon}(z),G_{D,\varepsilon,\varepsilon}(z,z))
\\
&&-\ind_{n \text{ even}}(-1)^{n/2}
\dfrac{n!}{2^{n/2} (n/2)!}
V_{A^{\rm gen, +}_{0},\varepsilon}(z)^{n/2}
\\&& +
\sum_{\substack{0\leq j\leq n-1\\0\leq k <\lfloor j/2\rfloor}}
(-1)^{k}\dfrac{n!}{2^{k} (n-j)! k! (j-2k)!}
V_{A^{\rm gen, +}_{0},\varepsilon}(z)^{k}
\nu^{\rm gen}_{0,\varepsilon}(z)^{n-j}
\,
:\Phi_{D\setminus A^{\rm gen, +}_{0},\varepsilon}^{j-2k}:(z).
\end{eqnarray*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Representation of averaged dynamics) of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Suppose $\textup{Law}(X)=\bbE[P_{[T]}^N(\bfJ)]$. With $Q$ as in \eqref{eq: averaged dynamics 1}, define
    \[\Lambda^i(t) := \int_0^t D^i_s X_t^\top  Q_s X_s\, ds, \quad i = 1, \ldots, N, \quad t \in [0, T]. \]
    Then $X$ satisfies
\begin{equation}
\begin{aligned}
dX_t^i &= - U'(X_t^i) dt + \beta^2 \bigg[ \int _0^t R_{\hat{\mu}^N}(t, s) dW^i_s \bigg] dt + \frac{\beta^2}{N}\Lambda^i(t)dt +  dW^i_t, \quad i = 1, \ldots, N, \quad t \in (0, T).\\
\end{aligned}

\end{equation}
Moreover, for $0 \leq s \leq t \leq T$ we have $R_{\hat{\mu}^N}(t, s) = \frac{1}{N} X_t^{\top} Q_s X_s.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:boolean-commutation of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] For every $0\leq k\leq n-1$,
\begin{equation}
 D_{k+1}U_k-U_{k-1}D_k=(n-2k)\mathrm{Id}_{\mathcal{H}_k}.
\end{equation}
Consequently, for every $f\in\mathcal{H}_k$,
\begin{equation}
 \left\lVert U_kf\right\rVert_2^2
 =(n-2k)\left\lVert f\right\rVert_2^2+\left\lVert D_kf\right\rVert_2^2.
\end{equation}
In particular, if $k<n/2$, then
\begin{equation}
 \left\lVert U_kf\right\rVert_2^2\geq(n-2k)\left\lVert f\right\rVert_2^2.
\end{equation}

