[Defi 24 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] For any continuous deterministic function $(\psi_t)_{t\geq 0}$ taking values in $\mathcal{H}^6_{\mathrm{Sym}}(\mathbb{S})$ such that for any $k\in \mathbb{N}^{*}$, $|\langle \psi,e_k\rangle| \leq C k^{-6}$ and let $(\zeta_t)_{t\geq 0}$ be a deterministic curve satisfying conditions $\fbox{{\bf C3}}-\fbox{{\bf C4}}$.
Then, the integral process $(\int_0^t \psi_r\cdot\mathrm{d}\zeta_r)_{t\geq 0}$ is defined almost surely as:
\begin{align*}
\int_0^t \psi_r\cdot\mathrm{d}\zeta_r:=  \int_0^t \psi_r\cdot\mathrm{d}\mathscr{J}_r + \int_0^t \psi_r\cdot\mathrm{d}\eta_r
\end{align*}
Moreover, for any smooth function $\psi$ it satisfies for all $T\geq 0$
\begin{align}
\sup_{t\in[0,T]}\Big| \int_0^t \psi_r\cdot\mathrm{d}\zeta_r  \Big| \leq C \|\zeta_T\|_{2,-2} \times \sup_{t\in [0,T]}\|\psi_t\|_2.
\end{align}

[Lemma 18 of arXiv:2605.15931, '2605.15931'] For each $n \in \mathbb{N}$ and $1\leq k \leq \ell$, the processes
		$$
		F^{n,k}_{a}:=n^{1/2}\int_0^{\tilde{\tau}^n(X)\wedge a}\nabla f_k(X_s)\cdot \sigma(X_s)dW_s\,{\stackrel{\textnormal{a.s. and }L^1}{\to}}\, V^{n,k}
		$$
		as $a \to \infty$. We denote $F^n_a=(F^{n,1}_a,...,F^{n,\ell}_a)$ and $V^n=(V^{n,1},...,V^{n,\ell})$. We have
		$$
		V^{n}\,{\stackrel{\textnormal{w}}{\to}}\,  J_f(x)\sigma(x)W_{\tau^1(\sigma(x)W)}
		$$
		{as $n\to \infty$.}

