[Proposition prop:main of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] \mbox{}
            \begin{enumerate}
                \item  Assume that the assumptions of Theorem (thm:main of the paper) ((item:1 of the paper)) holds for $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$. Then, under $\mu_{\mathbf{q}}$, the scaled process (equation def:step_Y of the paper) converges weakly in $D\left( \left[0,\mathbf{T}\right] \right)$, $\mathbf{T} > 0$ to the centered Brownian motion with variance $D_{k}\left(\mathbf{q}\right)$. 
                \item  Assume that the assumptions of Theorem (thm:main of the paper) ((item:2 of the paper)) holds for $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$ and $i \in {\mathbb{Z}}$, and that there exists $\lambda > 0$ such that ${\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ e^{\lambda s_{\infty}\left(1\right)} \right] < \infty$.
                Then, under $\mu_{\mathbf{q}}$, the sequence {$\left(Y^{{i}}_{k}\left(n\right) / n\right)_{n \in {\mathbb{N}}}$} satisfies the LDP with the good rate function $I^{Y{,i}}_{\mathbf{q},k}$. 
                \item  Suppose that $\mathbf{q} \in \mathcal{Q}$ satisfies ${\mathbb{E}}_{\nu_{\mathbf{q}}}\left[ s_{\infty}\left(1\right)^{p} \right] < \infty$ with some $p > 1$. Then, for any $k \in {\mathbb{N}}$ with $q_{k} > 0$, $i \in {\mathbb{Z}}$ and $p \ge 1$, we have 
                    \begin{align}
                        \lim_{n \to \infty} {\mathbb{E}}_{\mu_\mathbf{q}}\left[ \left| \frac{1}{n} Y^{{i}}_{k}\left( n \right) - v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right) \right|^{p} \right] = 0.
                    \end{align}
            \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

