[Lemma 17 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] For every $p>1$ there is $C_p<\infty$ such that, for all centered
jointly Gaussian $U,V$,
\begin{equation}
\abs{\Cov(\abs{U}^p,\abs{V}^p)}
\le C_p
\begin{cases}
\abs{\Cov(U,V)}^p,&\text{for $1<p\le2$,}\\
\Var(U)^{p/2-1}\Var(V)^{p/2-1}\Cov(U,V)^2,&\text{for $ p\ge2$.}
\end{cases}                                                       
\end{equation}

[Proposition 58 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] One has
\begin{equation}
 \overline\Pi_u^{(z)}x^\mu(h,h_z)
 =\rho_*\!\left[
 \prod_{t=1}^{\ell}
 p_{\ell,t-1}^*(r_{i_t+1}^{(t-1)}+h_z)
 \prod_{j=1}^n c_j(F_j^{(\ell)})^{d_j}
 \right].
\end{equation}

