[Thm 12 of arXiv:2607.06242, 'Exponential mixing and Freidlin--Wentzell large deviation principle for Markov cocycles'] There is a unique family $\{\G_{\sigma}\}_{\sigma\in\Sigma_0}\subset \mathcal{P}_{V}(E)$, measurable in $\sigma$, such that
      \[\G_\sigma Q_\sigma=\G_{\Theta \sigma},\qquad \sigma\in \Sigma_0.\]
      Moreover, there exists $\lambda>0$ such that the following properties hold.
      \begin{itemize}
        \item Pullback exponential stability: for every $\sigma\in \Sigma_0$ and $x\in E$, there is $C_{\lambda}(\sigma,x)>0$ such that, for all $t\geq 0$,
        \begin{align*}
          \W_{D_\sigma}\left(\delta_x P_t^{\beta_{-t} \sigma}, \G_\sigma\right) \leq C_\lambda(\sigma,x)e^{-\lambda t}.
        \end{align*}
        \item Forward exponential stability: for each fixed $r\in[0,T)$, there is a full measure set $\Sigma_r\subset\Sigma_0$ such that, for every $\sigma\in \Sigma_r$ and $x\in E$, there is $C_{\lambda,r}(\sigma,x)>0$ such that, for all $n\geq0$,
        \begin{align*}
          \W_{D_{\beta_t \sigma}}\left(\delta_x P_t^\sigma, \G_{\beta_t \sigma}\right) \leq C_{\lambda,r}(\sigma,x)e^{-\lambda t},\qquad t=nT+r.
        \end{align*}
      \end{itemize}
      Moreover, there exists a universally measurable set $\widehat{\Sigma} \subset \Sigma$ with full measure, invariant under $\left(\beta_t\right)_{t \in \mathbb{R}}$, and a universally measurable modification $\left\{\widehat{\G}_\sigma\right\}_{\sigma \in \widehat{\Sigma}}$ of $\left\{\G_\sigma\right\}_{\sigma\in\Sigma_0}$, such that
      \[
        \widehat{\G}_\sigma P_t^\sigma=\widehat{\G}_{\beta_t \sigma}, \quad \forall \sigma \in \widehat{\Sigma}, \quad \forall t \geq 0.
      \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:restrict-unit of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] The $\infty$-category $N_\Delta(\textbf{\textup{topSymMonCat}}_\Delta)$ is semiadditive, with products computed in the 1-category of topological categories.
    \begin{proof}
        It is clear that the projections induce even an isomorphism 
        \[
            \textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes,\textbf{\textup{D}}^\otimes\times\textbf{\textup{E}}^\otimes)\xrightarrow{\;\,\smash{\cong}\,\;}\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes,\textbf{\textup{D}}^\otimes)\times\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes,\textbf{\textup{E}}^\otimes)
        \]
        for all topological symmetric monoidal categories $\textbf{\textup{C}}^\otimes,\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes$, and hence exhibit $\textbf{\textup{D}}^\otimes\times\textbf{\textup{E}}^\otimes$ as a product. Analogously, one sees that $1$ (with the unique symmetric monoidal structure) is terminal.

        One directly checks for any $\textbf{\textup{C}}^\otimes$, the map ${\mathds{1}}\colon 1\to\textbf{\textup{C}}^\otimes$ classifying the symmetric monoidal unit admits a (unique) symmetric monoidal structure; any other symmetric monoidal functor $1\to\textbf{\textup{C}}^\otimes$ is isomorphic to ${\mathds{1}}$ by the unitality condition for symmetric monoidal functors, and the unitality condition for symmetric monoidal \emph{transformations} implies that this isomorphism is unique. Thus, $\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{1}},\textbf{\textup{C}}^\otimes)$ is equivalent in the enriched sense (and hence in particular Dwyer--Kan equivalent) to the terminal category for any $\textbf{\textup{C}}^\otimes$, so that $1$ is also initial.

        Finally, we will show that for any $\textbf{\textup{C}}^\otimes,\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes$ the map
        \begin{equation}
            \textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes\times\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes)\to\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes,\textbf{\textup{E}}^\otimes)\times\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes)
        \end{equation}
        induced by the inclusions $i_1\colon\textbf{\textup{C}}^\otimes\to\textbf{\textup{C}}^\otimes\times\textbf{\textup{D}}^\otimes\gets\textbf{\textup{D}}^\otimes
	\nobreak
	\mspace{6mu plus 1mu}
	{:}
	\nonscript\mkern-\thinmuskip
	\mathpunct{}
	\mspace{2mu}
 i_2$ of the units is an equivalence again, so that $i_1$ and $i_2$ exhibit $\textbf{\textup{C}}^\otimes\times\textbf{\textup{D}}^\otimes$ as the coproduct, which will then complete the proof of semiadditivity. For this, let us make the tensor product $\textbf{\textup{E}}\times\textbf{\textup{E}}\to\textbf{\textup{E}}$ into a strong symmetric monoidal functor $\mu$ via the associativitiy and symmetry isomorphisms of $\textbf{\textup{E}}^\otimes$, and consider the composite
        \begin{multline}
            \textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes,\textbf{\textup{E}}^\otimes)\times\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes)\xrightarrow{\;{-}\times{-}\;}
            \textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes\times\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes\times\textbf{\textup{E}}^\otimes)\\\xrightarrow{\;\mu\circ{-}\;}\textbf{\textup{Fun}}_\textup{cont}^\otimes(\textbf{\textup{C}}^\otimes\times\textbf{\textup{D}}^\otimes,\textbf{\textup{E}}^\otimes).
        \end{multline}
