[Proposition Ham3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $u$ be the positive  bounded solution to the hypoelliptic heat equation $\mathcal{L} u(x,t)=\partial_tu(x,t)$ with the initial value  $0\le f\le C$ ($C$ is a constant), we have for any  $x\in\mathbb{R}^{m_0}\times\cdots \times\mathbb{R}^{m_r}$ and $t>0$, \begin{equation}
\frac12\langle \mathcal{C}(t)\nabla \ln u,\nabla \ln u\rangle\le \ln \frac{C}{u}.
\end{equation}

[Definition 2 (Lipschitz Continuity) of arXiv:2608.24146, 'Robust Data-Collection Policy Learning for Low-Variance Online Policy Evaluation'] The function $f: \mathcal{X}\to \mathbb{R}$ is $L-$Lipschitz if $\forall x_1,x_2\in \mathcal{X},$ 
\begin{align}
\norm{f(x_1)-f(x_2)}\leq L\norm{x_1-x_2}.
\end{align}

[Prop martingalep of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Let $\eta(t)$ be from (prop11112 of the paper) with $a=2$. Define $\eta(t)=0$ if $t\le 0$. On the full binary tree $\mathbb{T}$ and with $\Theta_v$ as in (equation agedef of the paper), 
define
\begin{equation} 
\mathscr{X}_n(t)=\sum_{|v|=n-1}2\eta(\alpha^n(t-\Theta_v)),\ \ \ \ \forall\,n\ge 1.
\end{equation}
 Then
\begin{enumerate}[(i)]
\item The sequence $\{\mathscr{X}_n(t)\}$ satisfies the stochastic Picard iterations (equation pant_bin_iter of the paper) for the binary pantograph 
process  with ground state $\mathscr{X}_0(t)=\eta(t)$, corresponding to $a=2$ and $w_0=0$, i.e.
\begin{equation}
{{\mathscr{X}}_{n}}(t)=\left\{ \begin{array}{*{35}{l}}
   0 & \text{if} & T_\theta\ge t,  \\
   \mathscr{\mathscr{X}}_{n-1}^{(1)}(\alpha (t-T_\theta))+\mathscr{X}_{n-1}^{(2)}(\alpha (t-T_\theta)) & \text{if} & T_\theta<t.  \\
\end{array} \right.
\end{equation}
\item For each $t>0$, $\{\mathscr{X}_n(t)\}$ is a martingale with respect to the filtration $\mathcal{F}_n=\sigma(T_v:\,|v|\le n)$.
\item The limit $\mathscr{X}(t)=\lim_{n\to\infty}\mathscr{X}_n(t)$ exists. Moreover, $\mathbb{E}(\mathscr{X}(t))=\eta(t)$, and
for any $\delta\in(1,1/\gamma)$, $\mathbb{E}(\mathscr{X}^\delta(t))\le \frac{\eta_\delta(t)}{2^{\delta}}$, where $\eta_\delta$ 
is given in (exampleone of the paper).
\end{enumerate}

