[Theorem MainRes of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] Assume that $(\mathbf{H1})$-$(\mathbf{H5})$ hold. Then for each initial values $x\in \mathcal{H}_\eta$ and $y \in \mathcal{H}$ with $\eta \in (\gamma-1/4,\gamma) $, we have
	\begin{equation}
		\lim_{\varepsilon\rightarrow 0}  \mathbb E\big[\|X^\varepsilon-\bar{X}\|_{\eta, 0}^{2}\big]=0,
	\end{equation}
	where $\bar{X}_t$ is the unique solution of the corresponding averaged equation
	\begin{equation*}
		\left\{ \begin{aligned}
			d\bar{X}_t&=\big[ A \bar{X}_t+\bar{F}_1 (\bar{X}_t)\big]dt+G_1(\bar{X}_t)d \mathbf B_t,\\
			\bar{X}_0&=x,
		\end{aligned} \right.
	\end{equation*}
	with the averaged coefficient $\bar{F}_1 (x):=\displaystyle \int_{\mathcal{H}} F_1 (x,y) \mu^x (dy)$ for $x\in\mathcal{H}$, where $\mu^x$ is the unique invariant measure with respect to the Markov semigroup of frozen equation
 \begin{equation}\nonumber
\left\{ \begin{aligned}
	d Y_t&=\big[A Y_t+F_2(x,Y_t)\big]dt+G_2(x,Y_t) d \widetilde{W}_t,\\
	Y_0&= y.
\end{aligned} \right.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma apx_lemma: random_walk_expected_hitting_size of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] Let $G$ be a quasi-transitive graph of superlinear polynomial growth.

    For any $K_1, K_2 \ge 1$, there exist constants $c = c(G, K_1, K_2)$ and $C = C(G)$, such that for any $a \ge 2$, $x \in V$, and $D \subseteq B_x(K_1 a)$ with $|D| \ge |B_x(a)|/K_2$, we have



    \begin{align}
        c \cdot \theta(a) \leq \sum_{y \in D} \mathbb P_x \left( \tau_y \le a^2 \right) \leq C \cdot \theta(a) \, ,
    \end{align}
    where $\theta(a)$ is defined as 
    \begin{align*}
        \theta(a) := \begin{cases}
            a^2 & \text{if } d \geq 3, \\
            a^2 / \log a & \text{if } d = 2.
        \end{cases}
    \end{align*}

