[Theorem 7 of arXiv:2606.22526, 'The conditional expectation of the product of the first $n-1$ Hermite polynomials in a mul'] Assuming the sequence of random variables $X_{1},\ldots,X_{n}$ form a Markov
chain with zero expectations, $f_{N}$ as its marginal distributions and
(\ref{MCN}) as conditional distribution of $X_{j+1}|X_{j}=y$ the conditional
expectoration $C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=E\left(  H_{k}
(X_{j})|X_{n},\ldots,X_{j+1}=z,X_{j-1}=y,\ldots,X_{1}\right)  $ takes one of
the following equivalent forms
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\sum_{s=0}^{k}\binom{k}{s}\rho
_{j-1,j}^{k-s}\left(  1-\rho_{j-1,j}^{2}\right)  ^{s}\rho_{j,j+1}^{s}
H_{k-s}(y)\\
\times H_{s}\left(  \frac{z-\rho_{j-1,j}\rho_{j,j+1}y}{\sqrt{1-\left(
\rho_{j-1,j}\rho_{j,j+1}\right)  ^{2}}}\right)  /\left(  1-\left(
\rho_{j-1,j}\rho_{j,j+1}\right)  ^{2}\right)  ^{s/2},\nonumber
\end{gather}
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\frac{1}{\left(  1-\left(  \rho
_{j-1,j}\rho_{j,j+1}\right)  ^{2}\right)  ^{k}}\sum_{s=0}^{\left\lfloor
k/2\right\rfloor }(-1)^{s}\binom{k}{2s}\binom{2s}{s}s!\nonumber\\
\times\left(  \rho_{j-1,j}\rho_{j,j+1}\right)  ^{2s}\left(  \left(
1-\rho_{j-1,j}^{2}\right)  \left(  1-\rho_{j,j+1}^{2}\right)  \right)  ^{s}\\
\times\sum_{m=0}^{k-2s}\binom{k-2s}{m}\left(  1-\rho_{j-1,j}^{2}\right)
^{m}\left(  1-\rho_{j,j+1}^{2}\right)  ^{k-2s-m}\rho_{j-1,j}^{k-2s-m}
\rho_{j,j+1}^{m}H_{m}(z)H_{k-2s-m}(y).\nonumber
\end{gather}
\begin{gather}
C_{k}(y,z,\rho_{j-1,j},\rho_{j,j+1})=\left(  \frac{\rho_{j-1,j}^{2}
+\rho_{j,j+1}^{2}-2\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}}{1-\rho_{j-1,j}^{2}
\rho_{j,j+1}^{2}}\right)  ^{k/2}\\
\times H_{k}\left(  \frac{y\rho_{j-1,j}\left(  1-\rho_{j,j+1}^{2}\right)
+z\rho_{j,j+1}\left(  1-\rho_{j-1,j}^{2}\right)  }{\sqrt{\left(
1-\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}\right)  \left(  \rho_{j-1,j}^{2}
+\rho_{j,j+1}^{2}-2\rho_{j-1,j}^{2}\rho_{j,j+1}^{2}\right)  }}\right)
.\nonumber
\end{gather} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th 5.1111 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
Let (ass4.1-1 of the paper) hold  and let $g$ be independent of  the law of $Z(\cdot,\cdot)$. Assume $\max\limits_{1\leqslant i\leqslant N}\|\psi^i(\cdot)\|_{L^\infty_{\mathscr{F}_T}[0,T]}\leqslant K_1$. Then for any  $p\geqslant2$, there exist two  constants $l^*_0$ and $l^*_1$ with $\min\{l^*_0,l^*_1\}>1$, and a positive constant $C$, depending only on $(\beta,\beta_0,K_1,K_2,T,\phi(\cdot),\gamma, l^*_0, l^*_1,p)$, such that for almost all $t\in[0,T]$ and for  $i=1,\cdots,N,$
	\begin{equation}
		\begin{aligned}
			&\ \mathbb{E}\bigg[| Y^{N,i}(t)- \overline{Y}^i(t)|^p

			+\(\int_t^T \sum\limits_{j=1}^N|Z^{N,i,j}(t,s)- \delta_{ij}\overline{Z}^i(t,s)|^2ds\)^\frac{p}{2} \bigg] \nonumber\\


			&\leqslant   C\bigg\{\mathbb{E}\[
 \int_t^T  {\cal W}_2^{p(l_0^*l_1^*)^2}(\mu^N(s),\overline{\mu}(s))ds\]\bigg\}^{\frac{1}{(l_0^*l_1^*)^2}}.
		\end{aligned}
	\end{equation}

