[Thm who-is-afraid-of-the-J-homomorphism of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] There exists an initial example of an extension of 
    \begin{equation}
        {N_\textup{top}}(\textbf{\textup{L}}^\oplus)\xrightarrow{\;j^\otimes\;}\Spc_*^\otimes\xrightarrow{\;\textup{const}\;}\Spc_{\textup{Glo},*}^\otimes
    \end{equation}
    (where $\textup{const}$ denotes the unique symmetric monoidal left adjoint) to a symmetric monoidal global functor ${\mathpalette\ulhelper{j}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}^\otimes\colon{N_\textup{top}}(\textbf{\textup{L}}^{\oplus,\flat})\to\ul\Spc_{\textup{Glo},*}^\otimes$, and the diagram
    \begin{equation}
        \begin{tikzcd}[row sep=1ex]
            & \ul{{\mathfrak S\kern-.4pt}}_{\textup{gl},*}^{\otimes}\arrow[dd,"\Phi"',"\sim"]\\
            {N_\textup{top}}(\textbf{\textup{L}}^{\oplus,\flat})\arrow[ur, bend left=15pt,"{\mathpalette\ulhelper{\mathfrak j}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}^\otimes"]\arrow[dr, bend right=15pt," {\mathpalette\ulhelper{j}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}^\otimes"']\\
            & \ul\Spc_{\textup{Glo},*}^\otimes
        \end{tikzcd}
    \end{equation}
    commutes. More precisely, any identification of the resulting symmetric monoidal functors on global sections $\smash{{N_\textup{top}}(\textbf{\textup{L}}^\oplus)\rightrightarrows\Spc_{\textup{Glo},*}^\otimes}$  extends uniquely to an equivalence filling $((diag:comparison-of-js of the paper))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition GaussianandLaguerre of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] For $\beta>0$, an $N\times N$ \emph{Gaussian $\beta$-ensemble} is a probability measure on $N$-tuple $(\lambda_{1}\ge \ldots\ge \lambda_{N})\in \mathbb{R}^{N}$ with density function 
    \begin{equation}    
   \frac{1}{Z_{N,\beta}}\prod_{1\le i<j\le N}(\lambda_{i}-\lambda_{j})^{\beta}\prod_{i=1}^{N}\exp\left(-\frac{\lambda_{i}^{2}}{2N}\right),
    \end{equation}
    and an $N\times L$ \emph{Laguerre $\beta$-ensemble} ($N\le L)$ is a probability measure on $N$-tuple $(\lambda_{1}\ge \ldots\ge \lambda_{N})\in \mathbb{R}^{N}$ with density function
    \begin{equation}
       \frac{1}{Z_{N,L,\beta}}\prod_{i=1}^{N}\left[\lambda_{i}^{\frac{\beta}{2}(L-N+1)-1}\exp\left(-\frac{\beta\lambda_{i}}{2} \right)\right]\prod_{1\le i\le j\le N}(\lambda_{i}-\lambda_{j})^{\beta}.
    \end{equation}
    $Z_{N,\beta}$ and $Z_{N,L,\beta}$ are certain normalizing constants.

[Lemma KIintegralRatio of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Assuming (equation asmp:obsRG of the paper),  for sufficiently large $N$,
\begin{align}
	\left| \frac{ {\sf m} [ K_{N,\varnothing} (\Lambda,   h'_N z \one)] }{{\sf m} [ I_{N,\varnothing} (\Lambda,  h'_N z \one) ]} \right|
		\le O_L (1) \tilde{g}_N^{3/4} r_N^{{\kp}}  .
\end{align}

