[Lemma 4 of arXiv:2608.29152, 'Uniform Statistical Convergence of Empirical Sinkhorn Potentials\\ with Exponential and Po'] For a pointwise measurable class $\mathcal F$ bounded in $[0,B]$ with entropy integral $\Gamma(\mathcal F)$, and for any $\delta\in(0,1)$, independent observations $Z_1,\ldots,Z_n\sim P$ satisfy
\begin{equation}
 \sup_{h\in\mathcal F}|(P_n-P)h| \le \frac{C_{\mathrm D}}{\sqrt n} \left[ \Gamma(\mathcal F) + B\sqrt{\log\frac{2}{\delta}} \right]
\end{equation}
with probability at least $1-\delta$, for some universal constant $C_{\mathrm D}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_balanced of arXiv:2507.06522, 'Balanced multi-species spin glasses'] We say the multi-species parameter pair $(\vc\Delta,\vc\lambda)$ is \textit{balanced} if
\begin{equation}  \tag{H3} 
\begin{split}
\Delta^2_{t} \quad &\text{does not depend on $t\in\mathscr{S}$ for $p=1$, and} \\
\sum_{s_2,\dots,s_p\in\mathscr{S}}\Delta^2_{t,s_2,\dots,s_p}\lambda_{s_2}\cdots\lambda_{s_p} \quad &\text{does not depend on $t\in\mathscr{S}$, for every $p\geqslant2$.}
\end{split}
\end{equation}

[Definition DUFJ-INT-SJ-B of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] A random function $v\left( {x} \right)$ is said to be inertial-range intermittent, if for two positive exponents ${p_1} > {p_2}$, there exists an increasing function $\mathfrak{h}_2\left( r \right)$ such that
\begin{equation}
\frac{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {v\left( { \cdot  + l\mathbf{n}} \right) - v\left(  \cdot  \right)} \right\|}_{{L^{{p_2}}}}}}} \sim {\mathfrak{h}_2}\left( {r} \right) \to  \infty , \ \  \forall \, l \in \left[ {{l_D},{l_I}} \right] , \  \mbox{as}\ r \to  \infty , \ \mathbb{P}\mbox{-a.s.} 
\end{equation}

[Lemma 19 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] For $\Pp$-a.e.~$\omega$,
\begin{equation*}     \max_{0\le k<b^n}\abs{\xi_{n,k}(\omega)}\le C(\omega)n     \qquad\text{for all sufficiently large }n.                 
\end{equation*}

[Lemma 15 (Shifted Wasserstein recursion) of arXiv:2605.24937, '2605.24937'] Assume~\eqref{eq:one-step-w2-framework}. For all $0\le n\le N-2$,
\begin{equation}
  d_{n+1}^{\,2}
  \;\le\;
  L^{2}(1-\eta_n)^{2}\,d_n^{\,2}
  +2\,(1-\eta_n)\,\overline a_1\,d_n
  +\overline a_0^{\,2},
\end{equation}
where
$\overline a_0:=\sup_{0\le k<N}\|a_0(\widehat X_k)\|_{L^{2}}$
and
$\overline a_1:=\sup_{0\le k<N}\|a_1(\widehat X_k,\widetilde Y_k)\|_{L^{2}}$.

