[Lemma lemma_compare_hm of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $M\ge N\ge 1$, $v\in D\subset \widetilde{B}(\frac{N}{2})$, $x_1\in \partial B(N)$, $x_2\in \partial B(M)$ and $D'\subset [\widetilde{B}(2M)]^c$, 
	 \begin{equation}
	 N^{d-2}	\widetilde{\mathbb{P}}_{x_1}(\tau_{D}=\tau_{v}<\tau_{D'}) \asymp M^{d-2}	\widetilde{\mathbb{P}}_{x_2}(\tau_{D}=\tau_{v}<\tau_{D'}).
	 \end{equation}

