[Prop Prop_TransversalityCriterion_HarmonicSpinors_4D of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $B$ be a manifold and $\Gamma \mskip0.5mu\colon\thinspace B \to \mathbf{Dir}$ a smooth map.
  The following are equivalent:
  \begin{enumerate}
  \item
    $\Gamma$ is transverse to $\mathrm{pr}_\mathbf{Dir} \mskip0.5mu\colon\thinspace {\mathbf{P}}\mathbf{Harm}^{\pm,*} \to \mathbf{Dir}$.
  \item

    For every $b \in B$ and $({\mathbf{p}},[{\mathfrak l}];\Phi) \in \mathbf{Harm}^{\pm,*}$ with $\Gamma(b) = {\mathbf{p}}$
    the map
    \begin{equation*}
      \delta_{\Phi} \mskip0.5mu\colon\thinspace T_bB \to \paren[\big]{\ker D_{R_\Phi^\mp}^\mp}^*
    \end{equation*}
    defined by
    \begin{equation*}
      \delta_\Phi(v)\kappa
      \coloneq
      \Inner*{T_{\Phi,\kappa},T_{{\mathbf{p}}}\mathrm{pr}_\mathbf{Met} \circ T_b\Gamma(v)}_{L^2}
      + \Inner*{\mu(\Phi,\kappa),\mathrm{pr}_{V_\nabla} \circ T_b\Gamma(v)}_{L^2}
    \end{equation*}    
    is surjective.
    Here $R_{\Phi}^\pm$ denotes the chiral residue condition induced by $\Phi$.
    \qed
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:weak-one-edge-estimates of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For every fixed $R\ge2$, as $n\to \infty$, 
\begin{equation}

        \max_{e\in\mathcal P_\vartheta,\,\ell(e)\le R}
        \left|\frac{q_e}{p_e}-1\right|\longrightarrow0 .
\end{equation}
Moreover,
\begin{equation}

        \sum_{e\in\mathcal P_\vartheta}q_e+
        \sum_{e\in\mathcal P_\vartheta}p_e\le C_\vartheta,
\end{equation}
and, for all $R\ge2$,
\begin{equation}

        \sum_{\substack{e\in\mathcal P_\vartheta\\ \ell(e)>R}}q_e+
        \sum_{\substack{e\in\mathcal P_\vartheta\\ \ell(e)>R}}p_e
        \le \frac{C_\vartheta}{R}+o_n(1).
\end{equation}

