\[
\mathbb{E} \left[ \CompL(t) \right] = \mathbb{E} \left[ \CompL(t) \mathds{1}_{\{H < \beta t\}} \right] + \mathbb{E} \left[ \CompL(t) \mathds{1}_{\{H \ge \beta t\}} \right].
\]
