body:
[Theorem prop: levy processes 1 of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Fix $S\subseteq\mathbb R$ with and let  $X=(X_t)_{t\in[0,T]}$ be an $S$-valued Lévy process, with characteristics $(b,a,F)$. Assume that $\int_{|y|>1}\exp(\alpha  |y|) F(dy)<\infty$ for some $\alpha>0$.        Set  
\begin{align*}
    \mathcal{V}&\subseteq\{h\in H(\mathbb C) \colon h \text{ is of exponential type }\tau<{\alpha}\},\\
       \mathcal{V}^*&:=\{\mathbf{u}\in \mathcal{S}^* \colon h_\mathbf{u}=h,  \ h\in \mathcal{V}\}.
\end{align*}
Then,
\begin{enumerate}
\item $X$ is an $S$-valued $\mathcal{V}$-holomorphic process. 
    \item  For all $h\in \mathcal V$, the process $N^h$ given in equation (equation eq:localmart of the paper) is a true martingale.
    \item  For all $\mathbf{u}\in  \mathcal{V}^*$, there exists a $\mathcal{V}^*$-valued solution $(\mathbf{c}(t))_{t\in[0,T]}$ of (equation eq: ODE pointwise of the paper) with initial condition $\mathbf{u}$ which satisfies condition~(moment formula iii of the paper) of Theorem~(th: moment formula holomorphic of the paper). 
 \end{enumerate}
 In particular, for each $\mathbf{u}\in  \mathcal{V}^*$, the holomorphic formula holds true:
    \begin{align*}
    \mathbb E[h_\mathbf{u}(X_T)]=h_{\mathbf{c}(T)}(x_0).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 14 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] We have
\begin{align*}
    \lim_{T\to\infty}W_T(f)=\lim_{T\to\infty}\inf_{u\in\mathbb{H}}F_T(u)=\inf_{u\in\mathbb{H}}F_\infty(u)=:W(f)
\end{align*}
where
\begin{align*}
F_\infty(u)=\mathbb{E}\left[\varPhi_\infty(\mathbb{Y},u)+\Vert \nabla Z_\infty(u)\Vert_{L^4}^4+\frac{1}{2}\Vert u \Vert_\mathcal{H}^2\right].
\end{align*}

