body:
[Theorem prop_new_QM of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $
	\refstepcounter{newcnstcnt}
	\ensuremath{C_{\thenewcnstcnt}}(d)>
	\refstepcounter{cnstcnt}
	\ensuremath{c_{\thecnstcnt}}(d)>0$ such that the following hold. When $3\le d\le 5$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N)$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N)]^c$,
		\begin{equation}
	\begin{split}
			\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big) 
			 \asymp  \mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big).	
			 \end{split}
	\end{equation}
When $d=6$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N^{1-\varsigma(N)})$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N^{1+\varsigma(N)})]^c$,
\begin{equation}
N^{-10\varsigma(N)}	\lesssim \frac{\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big)}{\mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big)}\lesssim N^{\varsigma(N)}.
\end{equation}
When $d\ge 7$, for any $N\ge 1$, $A_1,D_1\subset  \widetilde{B}(\ensuremath{c_{\ref*{const_new_QM2}}}N^{\frac{2}{d-4}})$ and $A_2,D_2\subset [\widetilde{B}(\ensuremath{C_{\ref*{const_new_QM1}}}N^{\frac{d-4}{2}})]^c$,
	\begin{equation}
	\begin{split}
			\mathbb{P}^{D_1\cup D_2}\big( A_1\xleftrightarrow{\ge 0} A_2\big)
			 \asymp  N^{6-d} \mathbb{P}^{D_1}\big( A_1 \xleftrightarrow{\ge 0} \partial B(N) \big) \mathbb{P}^{D_2}\big( A_2 \xleftrightarrow{\ge 0} \partial B(N) \big).	
			 \end{split}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is $r$-demicontinuous;
\item[(ii)] The common order and uo adherence of $\Ba_{F}$ is contained in $r\Ba_{F}$;
\item[(iii)] Whenever $f_{p}\too f$, then $\|f\|\le r\liminf\|f_{p}\|$;
\item[(iii')] Whenever $f_{p}\touo f$, then $\|f\|\le r\liminf\|f_{p}\|$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:time_const of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $G$ be any probability measure on $[0, \infty)$. Then there exists a convex, deterministic function $\Lambda: [0,\infty) \to [0, \infty)$ depending on $G$ such that 
\begin{equation}
\Lambda(\nu)=\lim_{n\to \infty} \frac 1 n T((0,0),(n,{\lceil v n \rceil})).
\end{equation}
almost surely and in $L^1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 31 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Suppose $n \geq 1$ and $\Lambda \supset \Lambda_{2n}$. Let $\mu$ be a measure on $(\mathbb{R}^{+})^{\Lambda} \times \{0, 1\}^{\overline{E}(\Lambda)}$ that satisfies weak monotonicity and \eqref{eq: zero conditioning}. Then
    \begin{align*}
        \sum_{e \in \overline{E}(\Lambda)} \mathrm{Cov}_\mu(\mathbbm{1}_{\{o \longleftrightarrow \partial \Lambda_n\}}, \omega_{e}) \geq \frac{n \min_{x \in \Lambda_n} \mu[C_x]}{(4D+6) Q_n} \mu[o \longleftrightarrow \partial \Lambda_n] (1 - \mu[o \longleftrightarrow \partial \Lambda_n] ),
    \end{align*}
    where $Q_n \coloneq \max_{x \in \Lambda_n} \sum_{k=0}^{n-1} \mu[x \longleftrightarrow \partial \Lambda_k(x)]$.

