		=\Delta_v^{-1/2}\zeta_v(1)^{-1}
		\optionA{\P_v\left(-\lambda_{\mathrm{L}}(s);\varphi_v,f_v,f_{v,s}\right)}
		\optionB{\P_v\left(s,-\lambda_{\mathrm{L}}(s);\varphi_v,\Phi_v\right)}
	\end{equation*}
	for $s$ in general position.

