body:
[Theorem 1 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] Assume that for some $\gamma,\rho>0$, $N_P(z) = C z^{\gamma} + O (z^{\gamma-\rho})$.

Fix $\alpha=-1$ and $\beta>\gamma s+\max(0,1-\rho s)$, then 
\begin{enumerate}
    \item 
     For almost every $m \in[-1,1]$ there exists $C_m>0$ such that 
\begin{equation}
    \nm{u}_{L^2_{t,x}(\M)} \leq C_m \nm{(L -m) u}_{H^{\beta}_t L^2_x(\M)}.
\end{equation}

    \item For all $\ep>0$, there exists a set $\mathcal{A}_{\ep} \subset [-1,1]$ with $\mu(\mathcal{A}_\ep) <\ep$ and $C_{\ep}>0$ such that for all $m \in [-1,1] \backslash \mathcal{A}_{\ep}$, we have the uniform upper bound
    \begin{equation}
        \nm{u}_{L^2(\M)} \leq C_{\ep}\nm{(L-m) u}_{H^{\beta}_t L^2_x(\M)} .
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2607.16145, 'The Memoryless Best-Choice Problem'] For arbitrary stopping rule $\tau$, the $\delta$-extensions 
{\rm (\ref{Bot-ext})}
satisfy
\begin{equation}
\frac{\rm d}{{\rm d} \delta}\,{\mathbb P}[\tau^\delta=T]{\big |}_{\delta=0}={\mathbb E}\tau -{\mathbb P}[\tau=T].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:stochastic_intensity of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] Let $\Phi$ be a simple locally finite point process and $\mathcal{F}_t$ a history of $\Phi$. If there exists a locally integrable $\mathcal{F}_t$-adapted process $\lambda(t)\geqslant 0$ satisfying:
  \begin{gather} 
    \E{\Phi((s,t])\;\middle|\; \mathcal{F}_s} = \E{\int_s^t \lambda(u)du \;\middle|\; \mathcal{F}_s},
  \end{gather}
then $\lambda(t)$ is called an $\mathcal{F}_t-$\emph{stochastic intensity} of $\Phi$.

[Proposition 4 of arXiv:2608.25094, 'Noising-Denoising by Large Temperature Schr\"{o}dinger Bridges'] In addition to Assumption \ref{assumption}, suppose that 
    \begin{align}
        \limsup\limits_{T \to +\infty} \Exp{\diffref}\left[d^2(x,\Phi_{T/2}(x))\right] < +\infty,
    \end{align}
    where $\Phi_{T/2}: M \to M$ is the quadratic cost optimal transport map from $R_{T/2}^*\mu$ to $R_{T/2}^*\nu$. Then
    \begin{align*}
        \limsup\limits_{T \to +\infty}\exp(\lambda_1 T)\left(\left(\Exp{P_{T}}-\Exp{Q_{T}}\right)\left[\log\left(\frac{d(R_{T/2}^*\nu)}{d\diffref}(\Phi_{T/2}(x_{T/2}))\right)\right]\right) < +\infty.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 27 of arXiv:2608.02103, '$p$-Adic Diffusion and Random Walks on $[0,1]$'] Let $\mathfrak{M}_n$ be the Markov 

    process 
    attached to $W_n$. Then for given two states $I^{(n)},J^{(n)}\in A_n$  the transition probability of $\mathfrak{M}_n$ is given by the solution of the following Cauchy problem for $u(\cdot,t)\in X_n$, and $u(x,\cdot)\in C^1[0,\infty)$:
    \begin{equation}

    \begin{cases}
      \frac{\partial u}{\partial t} (x,t)=\mathcal{W}_{n}u(x,t)\\
      u(x,0)=\textbf{P}_nu_0(x)\in X_n
    \end{cases}\,.
\end{equation}

[Lemm l:tail-and-comparison-mesh of arXiv:2607.18194, 'Temperature chaos in directed polymers'] Let $t_0,t_1,\dots,t_{n+1}$ be as in (equation e:eps-mesh-times of the paper).
    For all sufficiently small $\varepsilon>0$ and all $m\geqslant 0$, we have
    \begin{align*}
        \mathbb{P}\left(
            \max_{0\leqslant k_1 < k_2 \leqslant n+1}\,
            \sup_{z,w\in J^{\delta}}
            \left|\mathcal{L}(t_{k_1},z; t_{k_2},w) 
            - 
            \int_{t_{k_1}}^{t_{k_2}} d\mathcal{L} \circ \widehat{\Pi}_{(t_{k_1},z),(t_{k_2},w)}
            \right|
            > m \varepsilon^{10}
        \right)
        \leqslant Ce^{-cm^{6/7}},
    \end{align*}
    where $\widehat{\Pi}_{(t_{k_1},z),(t_{k_2},w)}$ is the path obtained by rounding the geodesic $\Pi_{(t_{k_1},z),(t_{k_2},w)}$ to $\varepsilon^{50}\mathbb{Z}$ as in (def:rounding of the paper).

[Corollary 6 of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] Consider the Gaussian kernel in~\eqref{eq:gaussian} and $X_{n+1} = X_n \cup \{x_{n+1}\}$.
  Then
  \begin{equation*}
    \mathrm{cond}( \b{K}_{n+1} ) \geq \frac{1}{2} \bigg( \frac{\sqrt{2}(b-a)}{ \ell} \bigg)^{-2n} n! \quad \text{ and } \quad \mathrm{cond}( \b{K}_{n+1} ) \geq \frac{1}{2d} \bigg( \frac{\sqrt{2}(b-a)}{ \ell} \bigg)^{-2m} m!
  \end{equation*}
  in the settings of \Cref{thm:interpolation-1d} ($d = 1$) and \Cref{thm:interpolation} ($d \geq 1$), respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 24 of arXiv:2607.18104, '2607.18104'] For the \textbf{TASEP height function} $(\hTASEP(\lambda;y,t))_{y\in \Z,t\geq 0}$, assume that $(0,0) \in \lambda$ for a fixed down-right path $\lambda \in \Lambda$. For all $t\geq 0$, consider the down-right path
\begin{equation}
\lambda_t= (z^{t}_i)_{i \in \Z} := \{ w \in \Z^2 \, \colon \,  T_{\lambda,w} \leq t < T_{\lambda,w+(1,1)} \} 
\end{equation} such that $z^{t}_{0}=(x_t,x_t)$ for some $x_t \in \Z$. For $y \in \Z$ and $t > 0$, set $h_t(0)=x_t$ and recursively
\begin{equation}
h_t(i) - h_t(i-1) = \begin{cases} -1 & \text{ if } z^{t}_i-z^{t}_{i-1} = \eone , \\
 0 & \text{ if } z^{t}_i-z^{t}_{i-1} = -\etwo . 
\end{cases}
\end{equation}
 The \textbf{periodic TASEP height function} $\hpTASEP$ is defined as in \eqref{eq:CornerExtremalBasic} and \eqref{eq:CornerExtremalBasic2}, with respect to the periodic last passage times $\Tper$ from Definition~\ref{def:LastPassageTimes} and a down-right path $\lambda^{\per}_N \in \Lambda_{N,k}$.

[Lem convex-opt of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] For $X\in\mathbb{R}^{d_{1}\times d_{2}}$, let $X=U\Sigma V^{T}$
denote its compact SVD. Suppose there exists $W$ such that 
\begin{gather}
\mathcal{A}^{*}[\mathcal{A}(X)-b]+\lambda(UV^{T}+W)=0,\nonumber \\
U^{T}W=0,\quad WV=0,\quad\normop W\le1.
\end{gather}
Then $X$ is a global minimizer of ((eq:matrix-lasso of the paper)) for every
$r\ge\operatorname{rank}(X)$. If, in addition, 
\begin{equation}
H\ne0,\mathcal{A}(H)=0\implies\normnuc{X+H}>\normnuc X
\end{equation}
then $X$ is the \emph{unique} global minimizer for every $r\ge\operatorname{rank}(X)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 48 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $z \in \nU$. If $0 \leq s \leq t \leq T$, we define the following maps
\begin{align}

I_{s,t}^{n,z} &: \bZ_T \ni \bX \mapsto \int_{s}^{t} e^{i \langle \bX(r), z \rangle} \varphi_n^{z}(r,\bX(r)) \, \d r \in \mathbb{C},
\\

I_{s,t}^{z} &: \bZ_T \ni \bX \mapsto \int_{s}^{t} e^{i \langle \bX(r), z \rangle} \varphi^{z}(r,\bX(r)) \, \d r \in \mathbb{C},
\end{align}
where
\begin{align}

\varphi_n^{z}(r,\bX(r))&= i \; \duality{\bF_n(\bX(r))}{z}{}{} 
- \frac{1}{2} \Vert \duality{\newG_{0,n}(r,\bX(r))}{z}{}{} \Vert_{\ell^2}^2,
\\

\varphi^{z}(r,\bX(r))&= i \; \duality{\bF(\bX(r))}{z}{}{} 
- \frac{1}{2} \Vert \duality{\newG_0(r,\bX(r))}{z}{}{} \Vert_{\ell^2}^2,
\end{align}
with
   \begin{align}
     \newG_0: [0,T] \times \mathbb{V} \ni (t,\bX=(\bu,\phi))\mapsto (\bSi_0(t)\bu + \bG_0(t,\bu), 0)_{k=1}^\infty\coloneqq (\newG_{0}^k(t,\bu))_{k=1}^\infty \in 
     \ell^2(\nHB).
  \end{align}
Then the maps $I_{s,t}^{n,z}$  and $I_{s,t}^{z}$ are measurable.

[Proposition 1 (Poisson-gamma representation) of arXiv:2606.22066, 'A Bessel-zero obstruction to hyperbolic complete monotonicity of noncentral chi-square den'] For \(a,b>0\) and \(\theta\ge0\), \(p_{a,b,\theta}\) is a probability density on \((0,\infty)\), and
\begin{equation}

p_{a,b,\theta}(x)
=
e^{-\theta}\sum_{m=0}^{\infty}
\frac{\theta^m}{m!}\,
\gamma_{a+m,b}(x),
\end{equation}
where
\begin{equation}
\gamma_{\alpha,b}(x)
=
\frac{b^\alpha}{\Gamma(\alpha)}x^{\alpha-1}e^{-bx}.
\end{equation}
Equivalently, if \(N\sim\mathrm{Poisson}(\theta)\), then \(p_{a,b,\theta}\) is the density of a gamma law with random shape \(a+N\) and fixed rate \(b\).

