[Theorem 13 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Consider a pullback square of fpqc algebraic stacks
  \begin{equation*}
    \begin{tikzcd}
      \mcalY' \arrow[r,"g'"] \arrow[d,"f'"'] & \mcalY \arrow[d,"f"] \\
      \mcalX' \arrow[r,"g"'] & \mcalX.
    \end{tikzcd}
  \end{equation*}
  Assume that \(g \colon \mcalX' \to \mcalX\) is flat and \(f \colon \mcalY \to \mcalX\) is a \(B\mcalG\)-torsor for a flat affine group scheme \(\mcalG\) over \(\mcalX\).
  For $\mcalF \in \mcalD_{\qcoh}^+(\mcalY)$, the base change morphism
  \begin{equation*}
    \BC_{f,g}(\mcalF)\colon Lg^*Rf_*\mcalF\to Rf'_*L(g')^*\mcalF
  \end{equation*}
  defined in \Cref{QuasiCoherentBaseChangeMorphism} is an equivalence in \(\mcalD_{\qcoh}(\mcalX')\).

[Thm 1 of arXiv:2604.06122, 'REM universality for linear random energy'] Assume that Assumption \ref{assum:1} holds. Given a deterministic number $c\in (0,\gamma)$, there exists a unique $\tilde a\in (0,\varsigma)$ and $\tilde \lambda\in \R_{>0}$ (depending on $c$) such that
\been{

G^*(\tilde a)=c,\quad G'(\tilde \lambda)=\tilde a.
}
Moreover, for any random sequence $(C_n)_{n\in \N}$ such that
\been{

C_n(h) \in ( 0, \Gamma_n(h)),\quad \geas,\qquad\textup{and}\qquad \lim_{n\to\infty}\tfrac{1}{n}C_n=c,\quad \gas,
}
there exists a $h-$measurable random sequence $(A_n)_{n\in \N}$ such that the sequence of measure kernels $\(\mathbf{K}_n \)_{n\in \N}$, defined by
\been{

\mathbf{K}_n(h,\mathfrak{U}):=e^{C_n(h)}\Ps(\{\sigma:\,H_n(h,\sigma)-A_n(h)\in\mathfrak{U}\}),\quad h\in \R^{\N},\,\mathfrak{U}\in \mathcal{B}(\R),
}
converges vaguely $\Gas$ to the deterministic measure $\D_{\tilde \lambda}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

