[Theorem th:mainth2d of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Fix any $\beta \in (\frac{1}{2},1]$. Then
\begin{enumerate}
\renewcommand{\upshape(\arabic{enumi})}{\upshape(\arabic{enumi})}
    \item Any partition $\{B_\ell = B_\ell(n,m_n)\}_{ \ell=1,\ldots,m_n}$, which satisfies as $n\to\infty$
\begin{equation}

	\sum_{\ell=1}^{m_n} \sigma_n^2(B_\ell) \ = \ ({4}\beta^2 + o(1)) \, n^3 
\end{equation}
must also satisfy
\begin{equation}
	\max_{\ell=1,\ldots, m_n}
	\sigma_n^2(B_{\ell})  \ \ge \ \big( {2} \beta^2(2\beta-1) + o(1) \big) \, {n^3} \,.
	\end{equation}
    \item
    {As a consequence}, $\{Z_n\}$ satisfies an irreducible CLT in the sense of Definition (def:irreducibility of the paper).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] For $\e>0$, $x\in \R^2$ and $t>0$ fixed and for
$s\in [0,t]$ and $y\in \R^2$, set 
$$
\varphi^\e_{t,x}(s,y)=\theta(\nabla \phi_\e \ast K^{\theta,\lambda}_{t-s})(x-y)\in\R^2.
$$
It holds that (these are equalities in $\R^2$)
\begin{equation}
\left\{\begin{array}{ll}
\partial_s \varphi^\e_{t,x}(s,y)+\frac1\theta(\Delta_y \varphi^\e_{t,x}(s,y) -\lambda 
\varphi^\e_{t,x}(s,y))=0, & s\in [0,t],y \in \R^2,\\[3pt]
\varphi^\e_{t,x}(t,y)=\nabla \phi_\e(x-y),&y \in \R^2.
\end{array}\right.
\end{equation}
For all $r\geq 2$, there exists $A_{r}$ (also depending on $\theta$)
such that for all $t\geq s \geq 0$, all $y\in \R^2$,
\begin{gather}
\int_{\R^2} |\varphi^\e_{t,x}(s,y)|^r \dd x \leq \frac{A_r}{(\e+t-s)^{\frac{3r}2-1}}
\quad \text{and} \quad 
\int_{\R^2} |\nabla_x\varphi^\e_{t,x}(s,y)|^r \dd x \leq \frac{A_r}{(\e+t-s)^{2r-1}},\\
\int_0^t \int_{\R^2} |\varphi^\e_{t,x}(s,y)|^r \dd x \dd s \leq \frac{A_r}{\e^{\frac{3r}2-2}}
\quad \text{and} \quad 
\int_0^t \int_{\R^2} |\nabla_x\varphi^\e_{t,x}(s,y)|^r \dd x \dd s \leq \frac{A_r}{\e^{2r-2}},\\
\int_0^t \int_{\R^2} |\nabla_y\varphi^\e_{t,x}(s,y)|^r \dd x \dd s \leq \frac{A_r}{\e^{2r-2}}
\quad \text{and} \quad 
\int_0^t \int_{\R^2} |\nabla_x\nabla_y\varphi^\e_{t,x}(s,y)|^r \dd x \dd s \leq \frac{A_r}{\e^{\frac{5r}2-2}}.

\end{gather}

