[Theorem 45 (Deterministic rank comparison in the two tractable regimes) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Let $\theta_0\in\Theta$ and let $T\subset T_{\theta_0}\Theta$ be a tangent block.
\begin{enumerate}[label=\textup{(\roman*)}]
\item Suppose the model is edge-homogeneous near $\theta_0$, satisfies \cref{ass:regularity}, and the representation hypothesis of \cref{thm:homogeneous} holds for the visible depths under consideration. Then all such visible depths have the same first-order rank on $T$.
\item Suppose the model has exact depth $r$ at $\theta_0$ and satisfies \cref{ass:regularity}. Then for every $m<r$,
\begin{equation}
\rank\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_T\bigr) \le \rank\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_T\bigr).
\end{equation}
Moreover, strict coarse-depth loss on $T$ is equivalent to strict rank drop from depth $r$ to depth $m$ on $T$ itself.
If, in addition, the hypotheses of \cref{thm:selected-criterion-global} hold on $T$, or the hypotheses of \cref{thm:selected-criterion} hold on some subspace $T_0\subset T$, then depth $m$ loses a nonzero first-order direction relative to depth $r$ on the corresponding block.
\end{enumerate}

