[Corollary 7 of arXiv:2608.26662, 'Boundary–Moment Universality and Curvature Corrections in Random Geometric Graphs on Riema'] Under the hypotheses of Theorem~\ref{thm:S2}, if
$f\equiv \Vol_g(M)^{-1}$, then, for every $T<\infty$, uniformly for
$0\le t\le T$,
\[
\log\Pp\{S_{2,n}>t n^{-3/(2d)}\}
=-\frac{A_2(d)t^{2d}}{\Vol_g(M)^2}
+\frac{C_2(d)t^{2d+2}}{6\Vol_g(M)^3}
\left(
\int_M\Scal_g\,d\mathrm{vol}_g
\right)n^{-3/d}
+o(n^{-3/d}).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm teo_d1 of arXiv:2412.05950, 'Quantitative particle approximation of nonlinear stochastic Fokker-Planck equations with s'] Assume $(\mathbf{A}^V)$, $(\mathbf{A}^c)$, $(\mathbf{A}^F)$, $K = \delta_0$, let $T_{max}$ be the maximal existence time for ((SPDE_Ito of the paper)) and fix $T \in (0,T_{max})$. In addition, let the dynamics of the particle system be given by ((Ndensity of the paper)) with $\nu=Id$, $\sigma$ independent of the space and for any $m\geq1$, 
				\begin{align*}
					\sup_{N \in \mathbb{N}} \Big \| \left\| \rho^N_0 \right\|_{2} \Big \|_{L^m(\Omega)} < \infty
				\end{align*}
				with $d=1$ and $ \beta \in \left(0,\frac{1}{3}\right) $.
				Then
				\begin{align*}
					\Big \| \left\|\rho - \rho^N \right\|_{T,2} \Big \|_{L^m(\Omega)}  &\le C \Big \| \left\|\rho_0 - \rho^N_0 \right\|_{2} \Big \|_{L^m(\Omega)} \nonumber + C N^{-\varkappa} \, \nonumber 
				\end{align*}
				where
				\begin{align*}
					\varkappa = \min \left(\frac{\beta}{2}, \frac{1}{2}-\frac{3}{2}\beta \right)
				\end{align*}
				\noindent and $\rho$ is a  solution of SPDE (equation SPDE_Ito of the paper) with initial condition $\rho_0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2609.01346, '2609.01346'] There is $\varepsilon_0>0$ such that
\begin{equation}
 (r_{n,k}-\varepsilon_0,r_{n,k})\cap\sS=\varnothing.
\end{equation}
Consequently,
\begin{equation}
 0<\delta_*\leq r_{n,k}-\varepsilon_0<r_{n,k}.
\end{equation}

