[Lemma equation:upperboundfordimMBl of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] For every compact set $K\subseteq X$,  
\begin{equation}
    \dimMBl (K\setminus \mathcal{J}_{\underline{r},0}^{{\Leb}}(K))\leq d-s_2.
\end{equation}

[Prop thm:smc-transition of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $P_{\ell}(x,dy)$ denote the transition
kernel of the SMC process. Then 
\begin{equation}
P_{\ell}(x,dy)=e^{-\ell x} \delta_{x}(dy)+p_{\ell}(x,y) dy,
\end{equation}
where the density $p_{\ell}(x,y)$ is 
\begin{equation}
p_{\ell}(x,y)=\begin{cases}
\frac{\ell}{\ell-1}e^{-y}\left(1-e^{-(\ell-1)\min(x,y)}\right), & \ell\neq1\\
e^{-y}\min(x,y), & \ell=1.
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] Let $n \in \mathbb{N}$ and $\mathbb{P},\mathbb{Q} \in \mathcal{M}_1(\mathcal{C})$ martingale measures such that $\mathbb{Q}|_{\mathcal{F}^n}\ll \mathbb{P}|_{\mathcal{F}^n}$. 
We denote the Radon-Nikodym density of $\mathbb{Q}|_{\mathcal{F}^n}$ with respect to $\mathbb{P}|_{\mathcal{F}^n}$ on $(\mathcal{C},\mathcal{F}^n)$ as $\frac{d\mathbb{Q}}{d\mathbb{P}}|_{\mathcal{F}^n}$ and define: 
\begin{equation*} \begin{split}
H(\mathbb{Q}|\mathbb{P})|_{\mathcal{F}^n}:=\begin{cases}
    \int _{\mathcal{C}} \log \frac{d\mathbb{Q}}{d\mathbb{P}}|_{\mathcal{F}^n}d\mathbb{Q} \, \text{ if } \, \mathbb{Q}|_{\mathcal{F}^n} \ll \mathbb{P}|_{\mathcal{F}^n} \\
    +\infty \, \text{ otherwise.}
\end{cases}
\end{split} \end{equation*}

[Corollary 12 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\delta_0,\gamma,c>0$ such that the following holds for every $\delta \leq \delta_0$.
	Consider $x_0,y \in \cD(\delta)$ with $\Vert x_0-y \Vert\leq (4/5) r_\delta$.
	Then, for every $\varepsilon \leq \gamma r_\delta$,
	\begin{align}
		\bbP\bigl(X_{t_\delta} \in\sB(y,\varepsilon) \mid X_0 = x_0 \bigr) \geq c r_\delta \lambda_{\min} (\varepsilon/ r_\delta)^2\ \text{ with }\ t_\delta \de 2 r_\delta^2.
	\end{align}

[Lem 9 of arXiv:2605.02420, '\textbf{Large time behavior of critical marked Hawkes processes with heavy tailed marks an'] a)
Under the assumptions of Lemma \ref{lem:lem1} a) we have that
   \begin{equation}
   g_T(t)=\int_0^\infty\left(f_T(t+s)-H(g_T(t+s))\right) R(s)ds+Q_T(t)

  \end{equation}
where $Q_T$ has its support in $[0,Ta]$, where $a$ is given by \eqref{e:a} and  
\begin{equation}
 \liminf_{T\to \infty}( \inf_{t\ge 0} TQ_T(t))\ge 0

\end{equation}
Moreover, if additionally Assumption \ref{ass:phi_alpha} holds with $\beta=\alpha$, then
\begin{equation}
\limsup_{T\to \infty}(\sup_{t\ge 0}\abs{TQ_T(t)})=0.

\end{equation}

b) Under the assumptions of Lemma \ref{lem:lem1} b) and if additionally $\varphi$ satisfies \eqref{e:phi_x_integrable} then \eqref{e:Q_T} and \eqref{e:Q_T_2} are satisfied. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:hoffman-exact of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $z_1,\ldots,z_n\in\mathbb{R}^d$ be increments and let $X^{\rm PL}$ be the piecewise-linear path that traverses the increment $z_a$ on the $a$-th segment. Then
\begin{equation}
\mathrm{Sig}(X^{\rm PL})_{0,T}
=\exp_{\otimes}(z_1)\otimes\cdots\otimes\exp_{\otimes}(z_n)
=\Phi\big(\mathrm{Sig}^{\rm sum}(z_1,\ldots,z_n)\big),

\end{equation}
where $\Phi$ is Hoffman's exponential from the quasi-shuffle character to the shuffle character. Thus the Hoffman step has no discretization error; it is an algebraic identity.

[Corollary 4 (No dichotomy in the Cauchy case) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] When $\mu$ satisfies \Cref{Assum:Cauchy} and $\theta$ has finite moment of order $\delta$ for all $\delta >0$, then a
\(\Tree_{n}\)-walk with $\theta$-jumps in \(\Z^{d}\) is
recurrent, whatever the dimension \(d\) is:

\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} 0.
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 43 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$ with $d\neq 6$, there exist $\Cl,\Cl,\Cl,\cl >0$ such that for any $v\neq v'\in \widetilde{B}(\Cref{const_additional_lemma_two_arm0})$ and any sufficiently large $N\ge 1$,
	\begin{equation}
	\mathbb{P}\big(	\widehat{\mathsf{H}}_{v'}^{v}(N) \big)	\gtrsim   |v-v'|^{\frac{3}{2}}N^{-[(\frac{d}{2}+1)\boxdot 4]},
	\end{equation}
	where $\widehat{\mathsf{H}}_{v'}^{v}(N)$ is defined as $\mathsf{H}_{v'}^{v}(N)\cap \{v\xleftrightarrow{\ge 0} \partial B(\Cref{const_additional_lemma_two_arm1}N)  \}^c \cap \{v' \xleftrightarrow{\le 0} \partial B(\Cref{const_additional_lemma_two_arm1}N) \}^c 
			 	  \cap \big\{ |\widetilde{\phi}_{v}|,|\widetilde{\phi}_{v'}| \in [\cref{const_additional_lemma_two_arm3}, \Cref{const_additional_lemma_two_arm2}] \big\} $.

