[Proposition cor-core-lemma-alpha>=2 of arXiv:2607.22324, 'The conclave process'] {}
    Given $\alpha \geq 2$, define 
    \begin{align*}
        &\mathfrak T_{\mathsf{crit}}= \left\{ (M,\delta):(M,\delta) \mbox{ satisfying } (equation eq-assum-lem-2.4 of the paper) \right\} \,; \\
        &\mathfrak T_{\mathsf{unique}} = \Big\{ (M,\delta) \in\mathfrak T_{\mathsf{crit}}: (\log\log n)^{-300-2\alpha} < \tfrac{\delta^{-1}}{\log n} < (\log\log n)^{300+2\alpha} \Big\}\,;  \\
        &\mathfrak T_{\mathsf{mult}} = \Big\{ (M,\delta) \in\mathfrak T_{\mathsf{crit}}: (\log\log n)^{-300-2\alpha} < \tfrac{\delta^{-1}}{(\log n)^{\frac{\alpha}{2}}} < (\log\log n)^{300+2\alpha} \Big\} \,.
    \end{align*}
    In addition, define the event
    \begin{align*}
        \mathcal E_{\mathsf{lead}} &= \{\mathcal L(\mathbf X_{2})=\mathcal L(\mathbf X_{3})=\ldots=\mathcal L(\mathbf X_{10})\} \,.
    \end{align*}
    Then we have 
    \begin{align*}
        &\mathbb P\left( \mathcal E_{\mathsf{lead}}\cap\{\mathbf X_{10} \in \cup_{(M,\delta) \in \mathfrak T_{\mathsf{unique}}}\overline{\Omega}_n(M,\delta)\}\mid E_{\mathsf{unique}} \right) = 1-o(1)\,, \\ 
        &\mathbb P\left( \mathcal E_{\mathsf{lead}}\cap\{\mathbf X_{10} \in \cup_{(M,\delta) \in \mathfrak T_{\mathsf{mult}}}\overline{\Omega}_n(M,\delta)\}\mid E^c_{\mathsf{unique}} \right) = 1-o(1)\,.
    \end{align*}

