[Corollary dimensional-criterion-simplified of arXiv:2412.08400, '\vspace{-1.0cm} Characterization of Exponential Families of \\ Lumpable Stochastic Matrice'] If 
    \begin{equation*}
        \underbrace{\sum_{(x,x') \in \mathcal{D}} \left| \mathcal{S}_x \right|}_{ \text{\# of rows in every block}} > \underbrace{\left( \left| \mathcal{D} \right| - \left| \mathcal{U} \right| \right)}_{  \substack{\text{\# completely} \\ \text{merging blocks}} } + \underbrace{\left(\left| \mathcal{Y} \right| - \left| \mathcal{X} \right|\right)}_{\substack{\text{state space} \\ \text{compression}}} + \underbrace{\left(\left| \mathcal{E} \right| - \left| \mathcal{R} \right| \right)}_{  \substack{\text{\# of non-merging}\\ \text{transitions}}},
    \end{equation*}
    where $\mathcal{U}$ and $\mathcal{R}$ are defined in (equation equation:block-type-nomenclature of the paper),
    then $\mathcal{W}_{\kappa}(\mathcal{Y}, \mathcal{E})$ does not form an e-family.

[Corollary cor:OZ of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] [Ornstein--Zernike decay]

Let $d\ge 1$ and
suppose that Assumptions~(ass:Omega of the paper) and~(ass:J of the paper) hold.
For nonzero $x \in {\mathbb Z^d}$, let ${\mu_{\hat x}},\eta_{\hat x},\Lambda_{\hat x}$ be given by Proposition~(prop:geom-intro of the paper).
Then as $\abs x\to \infty$, we have
\begin{equation}
S(x) =
	\frac 1 { (2\pi)^{(d-1)/2} \sqrt{\det\Lambda_{\hat x}} }
	\frac{1}{ (\hat x \cdot \Lambda_{\hat x}^{-1} \hat x)^{1/2} }
	\frac{ \norm {\eta_{\hat x}}_2^{(d-3)/2}} { \norm  x_2^{(d-1)/2}}
	e^{-m_S  \abs x_S}
	[ \hat h ^{(\mu_{\hat x})} (0) + o(1)] ,
\end{equation}
with the $o(1)$ depending only on $d,M,K_{\mathrm{IR}},\zeta,m_S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 36 (Minimal informative window equals exact depth under global coordinate-rank loss) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Assume exact depth $r$ at $\theta_0$ together with \cref{ass:regularity}, and let $T\subset T_{\theta_0}\Theta$ be a tangent block. Assume:
\begin{enumerate}[label=\textup{(\alph*)}]
\item \begin{equation}
\rank\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_T\bigr)=\dim T,
\end{equation}
\item for every $m<r$ there exists a finite family
\begin{equation}
I^{(m)}=\{(y_j^{(m)},a_j^{(m)}):1\le j\le s_m\}
\end{equation}
of visible state--appended-edge pairs at depth $m$ such that, with
\begin{equation}
M_{I^{(m)}}:=D\Phi_{I^{(m)}}^{(m)}(\theta_0)|_T:T\to\RR^{s_m},
\end{equation}
one has
\begin{equation*}
\Ker\bigl(M_{I^{(m)}}\bigr)\subset\Ker\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_T\bigr) \qquad\text{and}\qquad \rank\bigl(M_{I^{(m)}}\bigr)<\rank\bigl(Dq_{\cQ}^{(r)}(\theta_0)|_T\bigr).
\end{equation*}
\end{enumerate}
Then
\begin{equation}
m_*(T,\theta_0)=r.
\end{equation}

