[Proposition prop:momentinequality of arXiv:2507.08692, 'Some notes on higher order concentration of measure'] Let $\mu$ be a measure on a product of finite sets satisfying a $\mathfrak{d}\mathrm{-LSI}(\sigma^2)$. Then, for any $f \in L^\infty(\mu)$ and any $r \ge 2$ we have
	\begin{equation} 
		\norm{f - \IE f}_r \le (\sigma^2(r-3/2)/2)^{1/2} \norm{\mathfrak{h} f}_r
	\end{equation}
	and
	\begin{equation}
		\norm{(f - \IE f)_+}_r \le (2\sigma^2 (r-3/2))^{1/2} \norm{\mathfrak{h}^+ f}_r.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 63 of arXiv:2607.18104, '2607.18104'] Fix $\delta>0$ and $M\in \N$, and assume that the Bernoulli paths $(h_0^{i,1,1})_{i \in \lbr M \rbr}$ and $(h_0^{i,2,1})_{i \in \lbr M \rbr}$ are all $(N,k)$-periodic and satisfy  $h_0^{i}:=h_0^{i,1,1}=h_0^{i,2,1}$ for all $i \in \lbr M \rbr$. We define for all $t\in [0,\delta N^{3/2}]$ and $i \in \lbr M \rbr$ the $\boldsymbol{(\delta,N)}$\textbf{-patched ASEP height function} 
\begin{equation}
h^{\textup{patch},\delta}(h^{i}_0;y,t) := \begin{cases} \hA_{1,1}\big(h_0^{i,1,1},0;y,t\big) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\hA_{2,1}(h_0^{i,2,1},0;y,t) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) . 
\end{cases}
\end{equation} For all $t\geq 0$ and $i\in \lbr M \rbr$, recall $f(t)$ from \eqref{def:Functionf}, and let the number of particles between $f(t)+\frac{1}{4}N$ and $f(t)+\frac{5}{4}N$ for the patched ASEP with initial conditions $h_0^{i}$ be defined as
\begin{equation}
    K^{i}_t := h^{\textup{patch},\delta}\Big(h^{i}_0;f(t),t\Big) -  h^{\textup{patch},\delta}\Big(h^{i}_0;f(t)+N-1,t\Big) . 
\end{equation}
We now obtain $h^{\textup{patch},\delta}$ for all $(y,t) \notin \mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ by extension so that $h^{\textup{patch},\delta}(h^{i}_0;\cdot,t)$ is an $(N,K_t^{i})$-periodic Bernoulli path. Now suppose that we have constructed the $(\delta,N)$-patched ASEP height function until time $j\delta N^{3/2}$ (the base case $j=1$ is covered above). Then we set 
\begin{equation}
h^{\textup{patch},\delta}(h^{i}_0;y,t) := \begin{cases} \hA_{1,j}\big(h_{j\delta N^{3/2}}^{i,1,j},0;y,t\big) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,\frac{1}{2}\big) ,   \\
\hA_{2,j}(h_{j\delta N^{3/2}}^{i,2,j},0;y,t) & \text{ if } (y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(\frac{1}{2},1\big) , 
\end{cases}
\end{equation}
for all $(y,t) \in \mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ with $t \in [j\delta N^{3/2},(j+1) \delta N^{3/2}]$, and define $h^{\textup{patch},\delta}(h^{i}_0;y,t)$ outside of $\mathcal{I}_{\delta,N}^{\rho}\big(0,1\big)$ by extension to a periodic path as for the base case $j=1$.

[Lem error-steady-states of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $N^\varepsilon$ and $L^\mathrm{av}$ be given as in (equation eq:eff of the paper) and (equation eq:aver-gen of the paper), respectively, and let $\hat{\rho}^\varepsilon$ and $\pi^\mathrm{av}$ be the corresponding steady states. Then, there exists $C > 0$ and $\varepsilon_0 > 0$ such that
    \begin{equation*} 
        \|\hat{\rho}^\varepsilon - \pi^\mathrm{av}\|_{\mathrm{TV}} \leq C\varepsilon
    \end{equation*}
    for all $\varepsilon \in (0,\varepsilon_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 9 (Le Gall \cite{LeGallLocTime,LeGallStFlour}) of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $N\geq 1$. 
Fix $f$ a smooth function with compact support in $\C$.
Then
\begin{equation}

\int_{S_\varepsilon(\zeta_M)} f(z) d^2 z\,
=
\sum_{n=1}^{N} (-1)^{n-1} \dfrac{1}{n!}\dfrac{(:\Theta_{\zeta_M}^{n}:,f)}{h_M(\varepsilon)^{n}}
\, + R_{N,\varepsilon}(f),
\end{equation}
where the error term $R_{N,\varepsilon}(f)$ satisfies, as $\varepsilon\to 0$,
\begin{displaymath}
\E[R_{N,\varepsilon}(f)^{2}]^{1/2} = o(\vert \log\varepsilon\vert^{-N}).
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Inverse3 of arXiv:2609.01350, 'New classes of trace-form permutation polynomials and their compositional inverses'] Let $q=2^m$, $f_2(x)=x+\gamma {\rm Tr}_{q}^{q^2} (c_1 x+ c_2 x^2+ c_3x^3+c_3x^{q+2}+x^{2q-1}),$ where $c_1 \in \mathbb F_{q^2}$, $c_2, c_3  \in \mathbb F_{q}$ and $\gamma \in \mathbb F_{q}^*$ such that $1+\gamma{\rm Tr}_q^{q^2}(c_1)=\gamma$. Then the compositional inverse of $f_2(x)$ is
\begin{equation}
  f_2^{-1}(x)=
  \begin{cases}
    \gamma^{-1}x
      & \text{if } x\in\mathbb F_q,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      & \text{if } x\notin\mathbb F_q,\ \beta=0,\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}+R+\dfrac{\beta}{R}
      & \text{if } x\notin\mathbb F_q,\ \beta\neq0,\ m \text{ odd},\\[0.8em]
    x+h_2(x)+\dfrac{x^3+x^{3q}}{x^{q+1}}
      +\dfrac{\theta^{(q+2)/3}+\theta^{(2q+1)/3}}{\beta}
      & \text{if } x\notin\mathbb F_q,\ m \text{ even},
  \end{cases}
\end{equation}
where
\[
  \beta=h_2(x)^2+(x+x^q)\,h_2(x)
        +\frac{(x+x^q)^6}{x^{2q+2}}
        +\frac{(x+x^q)^4}{x^{q+1}}
        +(x+x^q)^2+x^{q+1},
\]
\[
  R=\bigg(\beta\,(x+x^q)\sum_{i=0}^{(m-1)/2}
      \Big(\frac{\beta}{(x+x^q)^2}\Big)^{4^i}\bigg)^{1/3},
\]
and, in the last case, $\theta\in\mathbb F_{q^2}\setminus\mathbb F_q$ is either
root of $\theta^2+\beta(x+x^q)\theta+\beta^3=0$ (both roots give
the same value). For $m$ even one always has $\beta\neq0$, so the
four cases are exhaustive.

[Lemma 3 ({\cite[Eq.~(3.7, 3.8)) of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] {PeltolaWuGlobalMultipleSLEs}}]

Fix $\kappa\in (0,4]$ and $2N$-polygon $(\Omega; x_1, \ldots, x_{2N})$. 
For $1\le j\le N$, let $\gamma^j$ be chordal $\SLE_{\kappa}$ in $(\Omega; x_j, x_{2N+1-j})$. Let $\PP_N^{(\kappa)}$ be the probability measure on $\bs{\gamma}=(\gamma^1, \ldots, \gamma^N)$ under which the curves are independent. Then the law of rainbow $\SLE_{\kappa}$ in $(\Omega; x_1, \ldots, x_{2N})$ has the same law as $\PP_N^{(\kappa)}$ weighted by the Radon-Nikodym derivative 
\begin{align}
\frac{\prod_{j=1}^{N}\LZtwo(\Omega;x_j,x_{2N+1-j})}{\LZ_{\rainbow}^{(\kappa)}(\Omega;x_1,\ldots,x_{2N})}\one_{\LE_{\emptyset}(\bs{\gamma})}
		\exp\left(\frac{\mathfrak{c}}{2}\blm(\Omega;\gamma^1,\ldots,\gamma^N)\right), 
\end{align}
where $\LE_{\emptyset}(\bs{\gamma}) = \{ \gamma^{j} \cap \gamma^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and $\blm$ is the Brownian loop measure defined in~\eqref{eqn::blm_def}.
In particular, we have 
\begin{align}
	\begin{split}
		\LZ_{\rainbow}^{(\kappa)}(\Omega;x_1,\ldots,x_{2N})
		= \prod_{j=1}^{N}\LZtwo(\Omega;x_j,x_{2N+1-j}) \times
		\E_N^{(\kappa)} \left[
		\one_{\LE_{\emptyset}(\bs{\gamma})}
		\exp\left(\frac{\mathfrak{c}}{2}\blm(\Omega;\gamma^1,\ldots,\gamma^N)\right)
		\right].
	\end{split}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Assume the conditions of Theorem~\ref{thm:clt-additive} and that $m\stackrel{\lambda}{\to}\infty$
as in \eqref{eq:lambda-scaling}.
Fix $r\in\mathbb{N}$ and distinct points $x^1,\ldots,x^r\in\mathbb{N}^d$.
Set 

\begin{equation*}
\widetilde{f}_r(m):=(\widetilde{f}(x^1;m),\ldots,\widetilde{f}(x^r;m))^\top \ \text{and} \ \
f_r:=(f(x^1),\ldots,f(x^r))^\top.
\end{equation*}

Then

\begin{equation}
\sqrt{|m|_1}\,\big(\widetilde{f}_r(m)-f_r\big)
\xrightarrow[m\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}_r(0,\Sigma_{f,r}),
\end{equation}

where, for $1\le i,j\le r$,

\begin{equation}
\Sigma_{f,r}(i,j)
=
\frac{f(x^i)\big(\mathbbm{1}_{\{x^i=x^j\}}-f(x^j)\big)}{\mu_\lambda}.
\end{equation}

