and therefore
\begin{equation}
 \KL(Q^A\kldiv Q)=B,
 \quad
 \TV(Q^A,Q)=1-e^{-B},
 \quad
 d_{\mathrm{Hel}}^2(Q^A,Q)=1-e^{-B/2}.

\end{equation}

[Definition 16 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] An $\mathcal{F}_t$ progressively measurable process $\mathcal{Y}^{\epsilon}: \R \times \Omega \rightarrow H$ is said to be a stationary solution for the crude cocycle $(U^{\epsilon}, \theta)$ if for any fixed $s \in \R$, $\P$-a.s.
	\begin{equation} 
		U^{\epsilon}_0(t, \mathcal{Y}(s,\omega), \theta(s, \omega))=\mathcal{Y}^{\epsilon}(t+s,\omega)=\mathcal{Y}^{\epsilon}(t,\theta(s, \omega)), \quad \forall t \, \geq 0.
\end{equation}

[Lemma lem.follmer of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Fix $t_0 \in [0,1)$, $p \geq 2$, and $f \in \mathcal{A}_p^{\mathrm{F}}(t_0)$.
Define $v$ by (equation def.v of the paper). Then, the SDE
\begin{align*}
    dX^f(t) = \partial_x v(t,X^f(t))\,dt + dB(t), \quad t_0 \leq t \leq 1, \quad X^f(t_0) = 0,
\end{align*}
has a unique strong solution, which satisfies $X^f(1) \sim f \, d\gamma_{1- t_0}$. In particular,
\begin{align} 
     \|X^f(1)\|_{\infty} = [f]_{\infty}.
\end{align}
Moreover, the drift
\begin{align} 
    \alpha^f(t) \coloneqq \partial_x v(t,X^f(t)), \qquad t_0 \leq t \leq 1,
\end{align}
is a mean-zero martingale such that
\begin{align} 
    \|\alpha^f(t)\|_p \leq \frac{c_0}{2}, \qquad t_0 \leq t \leq 1.
\end{align}

