	\begin{align}
		\lim_{n \rightarrow \infty} \lt\|K_n\rt\| \nu_n(S_n)=0,
	\end{align}
	then \eqref{eq:thm:decay-masses} holds true.

[Lemma lem:quasi_isometry of arXiv:2503.21737, 'High-intensity Voronoi percolation on manifolds'] For every $\varepsilon>0$ and every distinct vertices $x,y\in V_\varepsilon$,
    \begin{equation}
        \frac{1}{4\varepsilon} \mathrm{d}_{M}(x,y)\leq \mathrm{d}_{G_\varepsilon}(x,y) \leq \frac{\Delta(\varepsilon)}{2\varepsilon} \mathrm{d}_{M}(x,y).
    \end{equation}

[Lemma generation_semigroup of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] The operator
\begin{align*}
    A:D(A)=X_1\subseteq X_0\rightarrow X_0
\end{align*}
 is linear and closed. Moreover, $-A$ is self-adjoint and satisfies
\begin{align}
    \langle -A x,x\rangle_{X_0}\geq \left\|x\right\|_{X_{1/2}}^2\geq g(1)\left\| x\right\|_{X_0}^2
\end{align}  
for all $x\in X_1.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 10 (Finite-time convergence of the normalized latent recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Suppose Assumptions~\ref{assump:mdp}, \ref{assump:mix},
\ref{assump:stable_kernels}, and \ref{assump:stepsizes} hold. Moreover, choose
$\frac45\alpha_{\mrm N}(1-\gamma)=:\lambda_{\mrm N}>1$ and set
\begin{equation}
        \epsilon_n^{\mrm N}
        :=
        \sqbk{(n+n_0^{\mrm N})
        \crbk{2L_{0,\rho}+4L_{\kappa,\rho}(1+c_\wedge^{-1})}
        \log\!\crbk{\frac{5(n+n_0^{\mrm N})}{n_0^{\mrm N}}}}\inv.

\end{equation}
For $\delta\in(0,1)$, define $r_c:=       \frac{c_\wedge}{64(1\vee L_{\kappa,\rho})}$ and set the burn-in number of iterations to be
\begin{equation}
        m_0(\delta):=\ceil{
        \frac{256\tmix^2}{c_\wedge^2}
        \log\!\crbk{\frac{6\cN_\rho(r_c)}{\delta}}} 
        \vee\ceil{n_0^{\mrm N}}
        \vee\ceil{16\alpha_{\mrm N}}.

\end{equation}
Then, with probability at least $1-\delta$
\begin{equation}
\begin{aligned}
        \norm{\theta_n^{\mrm N}-\theta^*}
        &\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{m_0(\delta)+n_0^{\mrm N}}
        {n+n_0^{\mrm N}}}^{\lambda_{\mrm N}} \\
        &\quad+
        \frac{370\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{
        \alpha_{\mrm N}\crbk{
        \cL_n^{\mrm N}(\delta)+\log\cN_\rho(\epsilon_n^{\mrm N})}}
        {n+n_0^{\mrm N}}}
        +
        \frac{\alpha_{\mrm N}^{2}}
        {c_\wedge(\lambda_{\mrm N}-1)(n+n_0^{\mrm N})}}
\end{aligned}

\end{equation}
simultaneously for all $ n\ge m_0(\delta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 49 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $\beta>0$. Let $G=(V,E)$ be a subgraph of $\mathbb Z^d$ with $0\in V$. Let $S\cap B=\emptyset$ be finite subsets of $V$, with $S$ containing $0$. Assume that $\partial S$ is separating $0$ and $B$ in the sense that every path from $0$ to $B$ has to visit $\partial S$. Then,
\begin{equation}
	\phi_{G, \beta}^0[0 \connect{} B] \leq \sum_{\substack{u\in S\\ v\notin S\\ u\sim v}} \phi_{S, \beta}^0[0 \connect{} u]\beta\phi_{G, \beta}^0[v \connect{} B]. 
\end{equation}

