[Lemma lem:A of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] For every $T>0$, 
\begin{align}
\lim_{K\to\infty}&\limsup_{n\to\infty}\mathbb P_{{\mathcal P}}(A_{n,K,T})=0, \\

\lim_{K\to\infty}&\limsup_{n\to\infty}\mathbb P_{{\mathcal P}}(B_{n,K,T})=0,
\end{align}
almost surely.

[Defi 1 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $\mathcal{T}$ be a topological space satisfying the first axiom of countability and let $F,F_n:\mathcal{T}\to[-\infty,\infty]$
    \begin{enumerate}
        \item 
    We say that the sequence of functionals $(F_n)_n$ $\Gamma$-converges to $F$ if
    \begin{itemize}
        \item ($\liminf$-inequality) For every sequence $x_n\to x$ in $\mathcal{T}$
        \begin{align*}
            F(x)\leq\liminf_{n\to\infty}F_n(x_n),
        \end{align*}
        \item($\limsup$-inequality) For every point $x$ there exists a sequence $x_n\to x$ in $\mathcal{T}$(recovery sequence) such that
        \begin{align*}
            F(x)\geq \limsup_{n\to\infty}F_n(x_n).
        \end{align*}
    \end{itemize}

    \item A sequence of functionals $(F_n)_n$ is called equicoercive if there exists a compact set $\mathcal{K}\subset\mathcal{T}$ such that for all $n\in\N$
    \begin{align*}
        \inf_{x\in\mathcal{K}}F_n(x)=\inf_{x\in\mathcal{T}}F_n(x).
    \end{align*}
    \end{enumerate}

