body:
[Proposition 22 (Exact rank computation) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] In the setting of \cref{ex:branching}, with parameter block $(\eta_1,\eta_2)\in(0,1)^2$:
\begin{enumerate}[label=\textup{(\alph*)}]
\item the depth-two chain on $\cS_2=\{ba,ad,db,ae,ec,ca\}$ is irreducible and has stationary distribution
\begin{equation*}
\pi(\eta_1,\eta_2)=\frac{1}{3(\eta_2+1-\eta_1)}(\eta_2,\eta_2,\eta_2,1-\eta_1,1-\eta_1,1-\eta_1),
\end{equation*}
\item in the reduced chart given by the free coordinates $\mu(d\mid ba)$ and $\mu(d\mid ca)$,
\begin{equation*}
\bar q_{\cQ}^{(2)}(\eta_1,\eta_2)=(\eta_1,\eta_2),
\end{equation*}
\item in the reduced depth-one chart with free coordinate $q_{a,d}^{(1)}$,
\begin{equation*}
\bar q_{\cQ}^{(1)}(\eta_1,\eta_2)=\frac{\eta_2}{\eta_2+1-\eta_1},
\end{equation*}
\item for every interior point $\theta_0=(\eta_1^0,\eta_2^0)$,
\begin{equation}
\rank D\bar q_{\cQ}^{(2)}(\theta_0)=2, \qquad \rank D\bar q_{\cQ}^{(1)}(\theta_0)=1.
\end{equation}
\end{enumerate}
if $D:=\eta_2^0+1-\eta_1^0$ and $h=(1-\eta_1^0,-\eta_2^0)$, then
\begin{equation}
D\bar q_{\cQ}^{(1)}(\theta_0)h=0, \qquad D\bar q_{\cQ}^{(2)}(\theta_0)h\neq0.
\end{equation}

