[Theorem th:near-critical-scaling of arXiv:2606.11503, 'Percolation on hierarchical lattices'] For any $\lambda \in \mathbb{R}$,
  \begin{equation}

    f_{k} \Big( p_\star + \frac{\lambda}{\zeta^k} \Big) \to h^{-1}(\lambda),
  \end{equation}
  where the diffeomorphism $h: (0, 1) \to \mathbb{R}$ is characterized as the unique linear conjugation of $f$ (that is, $h \circ f = \zeta \cdot h$) such that $h'(p_\star) = 1$.

  \nc{c:tail_h_1}
  \nc{c:tail_h_2}
  Moreover, there exist constants $\uc{c:tail_h_1}, \uc{c:tail_h_2} > 0$ such that
  \begin{equation}

    \exp \Big( -\uc{c:tail_h_1} |\lambda|^\nu \Big)
    \leq h^{-1}(\lambda)
    \leq \exp \Big( -\uc{c:tail_h_1}^{-1} |\lambda|^\nu \Big),
    \text{ as $\lambda \to -\infty$}
  \end{equation}
  and
  \begin{equation}

    1 - \exp \Big( -\uc{c:tail_h_2} \lambda^\mu \Big)
    \leq h^{-1}(\lambda)
    \leq 1 - \exp \Big( -\uc{c:tail_h_2}^{-1} \lambda^\mu \Big),
    \text{ as $\lambda \to \infty$},
  \end{equation}
  where the exponents $\mu$ and $\nu$ are the ones appearing in (th:off-critical-decay of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 25 of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] Let $k<n,\,f\colon \mathbb{R}^k \to \mathbb{R}$ be a bounded measurable function, then there exist $C, C' > 0$, such that
    \begin{equation*}
        \bigl|\mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1) G_\beta(U_n)] - \mathbb{E}_\pi[f(Z_1, \dots, Z_k) G_\beta(Z_1)]\, \mathbb{E}_\pi[G_\beta(Z_n)] \bigr| \leq C \e^{-C'(n-k)}.
    \end{equation*}

[Proposition 30 of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For every $x,\wt x\in\R$ with $x\neq\wt x$,
  \begin{align}
    \frac{\partial}{\partial x}
    \EE\bigl[
      F_{\wt x}^{\al,\be}F_{x}^{\al,\be}
    \bigr]
    =\lim_{\eps\downarrow0}
    \EE\left[
      \frac1\be\log \cZ_{\wt x}^\eps
      \frac{\partial}{\partial x}
      \frac1\be\log \cZ_x^\eps
    \right].
  \end{align}

[Proposition 24 of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] For all $x \in \hcV^{(\rm h)}_{\nu}$, $\sigma \in \{\pm 1\}$, define
  \begin{equation*}
    Z_{x} = 2 + \frac{2}{\#\Sib^{-}(x)}\ind_{\{\#\Sib^{-}(x) \neq 0\}}\,,
  \end{equation*}
  and
  \begin{equation*}
    \b u_{\sigma}(x) = \frac{1}{\sqrt{Z_{x}}} \Biggl( \b 1_{x} + \sigma\frac{\b 1_{S_{1}^{\pp -}(x)}}{\sqrt{D_{x}^{\pp -}}} - \frac{\b 1_{\Sib^{-}(x)}}{\#\Sib^{-}(x)}\Biggr)\,.
  \end{equation*}
  The family $(\b u_{\sigma}(x))_{x \in \hcV^{(\rm h)}_{\nu}, \sigma\in \{\pm 1\}}$ is orthonormal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 72 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] For any $p\geq d_{0}+1$  
\begin{equation}

\|G_{\cA}\|_{L_{p/(p-1)}(\bR^{d+1}_{0})}\leq N(\delta,d  )\lambda^{(d+2)/(2p)-1}P(\cA)
\end{equation}
In particular, for any Borel $f\geq0$ given on $\bR^{d+1}$ (and $\lambda\geq \varkappa_{0}^{2}\rho_{b}^{-2}$) on $\{\tau<\infty\}$ we have
\begin{equation}

E_{\cF_{\tau}}\int_{0}^{\infty}e^{-\lambda t}f(t,x_{\tau+t})\,dt
\leq N(\delta,d )
\lambda^{(d+2)/(2d_{0}+2)-1}\|f\|_{L_{d_{0}+1}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $\xi,g$ satisfy (H1) and (H3). Assume that $(Y,Z,A,A')$ solves
    \begin{align*}
        Y_t=\xi+\int_t^T g(s,Y_s,Z_s)d\langle B\rangle_s-\int_t^T Z_sdB_s+(A_T-A_t)-(A'_T-A'_t),
    \end{align*}
    where 
    \begin{align*}
        (Y,Z)\in S_G^\infty(0,T)\times H^2_G(0,T),
    \end{align*}
    and $A$, $A'$ are continuous nondecreasing processes with $A_0=A'_0=0$.

 \begin{itemize}
     \item[(1)] Suppose that $A'_T\in L^\infty_G(\Omega_T)$.  Then, for any $\alpha\geq 1$, there exist two constants 
     \begin{align*}
         &C_1:=C_1(\|Y\|_{S^\infty_G},\|A'_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma}),\\
         &C_2:=C_2(\|Y\|_{S^\infty_G},\|A'_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma},\alpha),
     \end{align*}
     such that 
    \begin{align*}
        \|Z\|_{BMO_G}\leq C_1,\  \hat{\E}[|A_T|^\alpha]\leq C_2.
    \end{align*}
    \item[(2)] Suppose that $A_T\in L^\infty_G(\Omega_T)$.  Then, for any $\alpha\geq 1$, there exist two constants 
    \begin{align*}
         &C'_1:=C'_1(\|Y\|_{S^\infty_G},\|A_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma}),\\
         &C'_2:=C'_2(\|Y\|_{S^\infty_G},\|A_T\|_{L^\infty_G}, T,L_y,L_z,M_0,\bar{\sigma},\alpha),
     \end{align*}
     such that 
    \begin{align*}
        \|Z\|_{BMO_G}\leq C'_1,\  \hat{\E}[|A'_T|^\alpha]\leq C'_2.
    \end{align*}
 \end{itemize}

