[Lem l:8.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let ${\rm A} \subseteq{\rm D}_n^\circ$ be an $(r_n,n-r_n)$-clustered set and ${\mathbf A}$ a minimal $r_n$-cover of it in the sense of~(equation e:2.10t of the paper) such that $|{\mathbf A}|\leq n^{1/2+\eta_0/4}$, where $\eta_0$ is as in~(equation e:2.3 of the paper). Then, as $n \to \infty$, 
	\begin{equation}
		\mathbb{P}_\partial \Big(\tau_{\partial {\rm B}(x;r_n)} < \overline{\tau}_\partial \wedge \min_{y \in {\mathbf A} \setminus \{x\}}
		\tau_{\partial {\rm B}(y;r_n)} \Big)
		= \frac{2\pi}{\deg(\partial) n}\Big(1+o(n^{-\eta/4})\Big) \,,
	\end{equation}
	uniformly over all such sets ${\rm A}$ and $x \in {\mathbf A}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma distYYbar of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] \begin{equation}
\sup_{-\varepsilon \le t \le t^{(a,b)}}|\overline Y_1^N(t)- Y_1^N(t)| \to 0 \quad \mbox{in probability as } N\to \infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 25 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] For $\Delta^\partial : \langle \mcT angle 	o \langle \mcT angle \otimes \langle \mcT_1 angle$, we can write
	 egin{align*}
		\Delta^\partial (	au, \mfn, \mfe) =  \sum_{\substack{C \in \mbC[	au] \ C 
eq \emptyset}} \sum_{\eps_C} \sum_{n_{
ot \ge C}} \sum_{e \in C}  rac{1}{\eps_C!} {\mfn \choose n_{
ot \ge C}} & (	au_{
ot \ge C}, n_{
ot \ge C} + \pi \eps_C, \mfe) \ & \otimes \mfp_{\cT_1} \partial_e \mfC (	au, 	au_{
ot \ge C} , \mfn -n_{
ot \ge C}, \mfe + \eps_C).
	\end{align*}

	We note that the sums defining $\Delta^\partial$ are effectively finite due to the projection $\mfp_{\cT_1}$ and the binomial coefficient.

[Corollary cor: generalization of Yu of arXiv:2411.17109, 'On the maximal correlation of some stochastic processes'] Let us consider i.i.d. non-degenerate random variables $X_1,X_2,\ldots,X_n$ taking values in a general measurable space $(F,\mathcal{F})$. Then for $1\leq \ell+1\leq m\leq n$, we have that
\begin{equation}
R\left(\sum_{i=1}^{m}\delta_{X_i},\sum_{j=\ell+1}^{n}\delta_{X_j}\right)=\frac{m-\ell}{\sqrt{m(n-\ell)}},
\end{equation}
where $\delta_{x}$ is the Dirac measure at $x$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor cor_bounded_st_times of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Fix \(x\ge0\), and let \(y_x^*\) be as in Proposition (prop_stopping_for_large_y of the paper). In the fixed-\(x\) problem (equation 2d_value_func_def of the paper) with value $U_x(\cdot)$, it is enough to minimize over stopping times \(\tau\) satisfying
    \begin{equation}
        \tau\le \tau_{-x,y_x^*} \quad 
        \text{ a.s., where }
        \qquad
        \tau_{\xi,\zeta}
        \coloneqq
        \inf\{t\ge0:Y_y(t)\notin(\xi,\zeta)\}.
    \end{equation}

[Lemma 8 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] (i) Let $\phi(x)=\left(1+\frac{1}{x^2}\log \frac{2x-1}{2(x-1)}\right)^{\frac{1}{2}}-1$ and $1<q<\infty$. Suppose that $\|Z\|_{BMO_G}<\phi(q)$. Then, we have 
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\frac{\mathcal{E}(Z)_T^q}{\mathcal{E}(Z)_\tau^q}\right]\right\|_{L^\infty(\P)}\leq C_q,
    \end{align*}
    where $C_q>0$ is a constant depending only on $q$. 

    \noindent (ii) Given $1<r<\infty$, suppose that $\|Z\|_{BMO_G}<\frac{\sqrt{2}}{2}(\sqrt{r}-1)$. Then, we have
    \begin{align*}
        \sup_{\P\in\mathcal{P}}\sup_{\tau\in \mathcal{T}_0^T}\left\|\E^{\P}_\tau\left[\left(\frac{\mathcal{E}(Z)_\tau}{\mathcal{E}(Z)_T}\right)^{\frac{1}{r-1}}\right]\right\|_{L^\infty(\P)}\leq C_r,
    \end{align*}
    where $C_r>0$ is a constant depending only on $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.27545, 'A simple proof of rapid mixing on random regular graphs beyond uniqueness'] Let $\mathcal{X} \subseteq \{0,1\}^V$ be a non-empty downward closed set family and suppose $\mu$ is a distribution fully supported on $\mathcal{X}$.  Suppose that for $\delta \in (0,1)$ we have that for all $\sigmabf \in \mathcal{X}$ the matrix $M_{\sigmabf}\in \R^{V\times V}$ given by
		\begin{equation}
			M_{\sigmabf}(u,v)=(1 - \delta)r_v(\sigmabf)\one_{u = v} - r_v(\sigmabf)(r_u(\sigmabf\cup \{v\}) - r_u(\sigmabf))  
		\end{equation}
		is positive semidefinite. Then continuous time Glauber dynamics for $\mu$ has spectral gap at least $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 31 (Deterministic bias, mixed-damping regime) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, for the mixed-damping regime \(\eta\gtrsim(1-\rho)^2\), the deterministic bias decomposes into $\cS_{\nesterov}(k) = \cS_{\mathrm{over}}(k) + \cS_{\mathrm{under}}(k)$, where the overdamped tail satisfies the two-sided bounds:
\begin{equation*}
    \cS_{\mathrm{over}}(k)
    \eqsim
    \begin{cases}
    \left(\frac{(1-\rho)^2}{\eta}\right)^s, &\qquad k\lesssim\frac{1}{1-\rho},\\
    \left(\frac{1-\rho}{\eta k}\right)^s, &\qquad k\gtrsim\frac{1}{1-\rho},
    \end{cases}
\end{equation*}
and $\cS_{\mathrm{under}}(k)$ represents the underdamped transient whose properties are formally established in Lemma~\ref{lem:nes_underdamped_transient_properties}.

[Lemma 6 of arXiv:2606.14170, 'Uniform-in-time error estimates for McKean-Vlasov SDEs with common noise and stochastic al'] Suppose that Assumptions \ref{A1} and \ref{N1} hold with $\lambda_1>2\lambda_2$. Then for any $p\ge 1$ and $h\in (0,h_p]$ with$$h_p=1\wedge\frac{\lambda_1-2\lambda_2}{2p(1+\lambda_2)^p},$$ there exists a constant $C>0$ such that for all $n\ge 0$ and $i\in\mathbb{S_N}$,
\begin{align*}
\mathbb{E}|X_{nh}^{i,N, h}|^p\le {\rm e}^{-\gamma^*nh}\mathbb{E}|X_0^{i,N,h}|^p+C, 
\end{align*}
in case of $\mathbb{E}|X_0^{i,N,h}|^p<\infty$, where $\gamma^*=\frac{\lambda_1-2\lambda_2}{2+3(2\lambda_1-3\lambda_2)}$.

[Lemma 42 (Outlier test-function convergence) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Assume \(|\theta|>1\), and let \(\varphi\) be analytic on a neighborhood of
\(\rho_\theta\).  Then
\begin{equation}
 \varphi\bigl(\lambda_{\rm out}(M_N^f)\bigr)
 =\varphi(\rho_\theta)+o_{\mathbb P}(1).
\end{equation}

[Proposition 20 of arXiv:2608.19744, 'Conditioned Brownian motion and local equivalence of path ensembles'] The process
\begin{equation}
 M_t^\beta
 = \mathrm e^{\lambda(\beta)t-\beta A_t}
   \frac{\phi_\beta(W_t)}{\phi_\beta(x)},
 \qquad t\ge0,
 \nonumber
\end{equation}
is a positive mean-one  $(\mathcal F_t) $-martingale under
 $\mathbb P_x $.  The consistent measures
\[
 \de \mathbb P_x^\beta|_{\mathcal F_t}
 =M_t^\beta\,\de \mathbb P_x|_{\mathcal F_t}
\]
define the law of the diffusion
\begin{equation}
 \de X_t=\de B_t+\nabla\log\phi_\beta(X_t)\,\de t,
 \qquad X_0=x.

\end{equation}

[Definition 8 (Information flow associated with coordinate $i$) of arXiv:2607.20823, 'Fluctuation impossibility results for stochastic burst networks'] Assuming that the series below is absolutely convergent, define
\begin{align}
(\dot I)_{X_i}
&:=
\sum_{n\ge0}
\sum_{v\in\mathbb Z_{\ge0}^{N-1}}
\sum_{k\ge1}
\pi(n,v)f_i(v)p_{i,k}
\log\frac{\pi_{n+k}^i(v)}{\pi_n^i(v)}
\notag\\
&\quad+
\sum_{n\ge1}
\sum_{v\in\mathbb Z_{\ge0}^{N-1}}
\pi(n,v)\frac{n}{\tau_i}
\log\frac{\pi_{n-1}^i(v)}{\pi_n^i(v)}.

\end{align}

[Lemma lemma-iteration-trick of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] Let $R>0$, $N,M\in \mathbb{N}$. Let $V,E, A, \left\{ U_i \right\}_{i=1}^N, \left\{F_j\right\}_{j=1}^M$ be non-negative, locally bounded functions defined on $[0,R)$ such that $A,F_j$ are non-increasing for all $j=1,\dots, M$. We assume that there exist $L_i,c_i, \tilde c, \ell_j\in [0,\infty)$, such that for any $s\ge 0$ and $\delta>0$ with $s+\delta \leq R$ we have  
    \begin{equation}

        \begin{split}
        V(s+\delta) + E(s+\delta)& \leq A(s) + \sum_{i=1}^N \left(\frac{2}{\delta}\right)^{L_i} U_i\left(s+\frac{\delta}{2}\right) \\
        & \leq A(s) + \varepsilon\sum_{i=1}^N c_i\left(\frac{4}{\delta}\right)^{L_i}U_i\left(s + \frac{\delta}{4} \right) + \varepsilon \, \tilde c \, E\left(s\right) + C_\varepsilon\sum_{j=1}^M \left( \frac{2}{\delta}\right)^{\ell_j} F_j(s),
        \end{split}
    \end{equation}for any $\varepsilon>0$ and a constant $C_\varepsilon<\infty$. Then, there exists a  constant $C^*\in (0,\infty)$ depending only on the preceding parameters, such that for any $s,\delta$:
    \begin{equation}

        V(s+\delta) \leq C^* \left(A(s) + \sum_{j=1}^M\delta^{-\ell_j} F_j(s)\right).
    \end{equation}

[Lemma 10 (Banach-valued time lift) of arXiv:2606.16662, '2606.16662'] Let \(X(t,s)\), \(0\le s\le t\le T\), be a random field with values in a finite-dimensional Banach space \(B\).  Assume that for some \(A_N\), all \(p_0\ge2\), some \(\eta\in(0,1]\), and some \(\chi\ge0\),
\begin{align}
        \|\|X(t,s)\|_B\|_{L^{p_0}(\Omega)}&\le C_{p_0}A_N,\\
        \|\|X(t,s)-X(t',s')\|_B\|_{L^{p_0}(\Omega)}
        &\le C_{p_0}A_NN^{\chi\eta}
        (|t-t'|^\eta+|s-s'|^\eta),
\end{align}
whenever both pairs \((t,s)\) and \((t',s')\) lie in the Volterra simplex.  Then, for every fixed \(p\ge2\) and every \(\eps>0\), if \(\chi\eta<\eps/4\),
\begin{equation}
        \|\|X\|_{C_{t,s}B}\|_{L^p(\Omega)}
        \le C_{p,T,\eps}A_NN^\eps .
\end{equation}
The same statement holds for a separable Banach-valued modification.  In the application below \(B=\cL(\ell_q^2,\ell_n^2)\), a finite-dimensional matrix space; the continuous-time norm is obtained from rational time skeletons.

[Definition GWS of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] A stochastic process $\boldsymbol{\mathcal{Y}}(t):=\boldsymbol{\mathcal{Y}}(t;\mathfrak{r},\omega,\boldsymbol{\mathcal{Y}}_{\mathfrak{r}})$ is a $\textsl{global (analytic) weak solution}$ of the system (equation STGF of the paper) for $t\geq\mathfrak{r}$ and $\omega\in\Omega$ if for $\mathbb{P}$-a.s. $\omega\in\Omega$
		\begin{align*}
			\boldsymbol{\mathcal{Y}}(\cdot)\in\mathrm{C}([\mathfrak{r},\infty);\mathbb{H})\cap\mathrm{L}^{2}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{V})\cap \mathrm{L}^{4}_{\mathrm{loc}}(\mathfrak{r},\infty;\mathbb{W}^{1,4}(\mathbb{Q}))
		\end{align*}
		and 
		\begin{align*}
			&(\boldsymbol{\mathcal{Y}}(t),\boldsymbol{\psi})+\nu\int_{\mathfrak{r}}^{t}(\nabla\boldsymbol{\mathcal{Y}}(\xi),\nabla\boldsymbol{\psi})\/\mathrm{d}\/\xi+\int_{\mathfrak{r}}^{t}b(\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\xi\nonumber\\&=(\boldsymbol{\mathcal{Y}}_{\mathfrak{r}},\boldsymbol{\psi}) - \alpha \int_{\mathfrak{r}}^{t}\langle\mathrm{J}(\boldsymbol{\mathcal{Y}}(\xi)), \boldsymbol{\psi}\rangle \/\mathrm{d}\/\xi - \beta \int_{\mathfrak{r}}^{t}\langle\mathrm{K}(\boldsymbol{\mathcal{Y}}(\xi)) , \boldsymbol{\psi}\rangle \/\mathrm{d}\/\xi +\int_{\mathfrak{r}}^{t}(\boldsymbol{\mathfrak{K}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\xi +\sigma\int_{\mathfrak{r}}^{t}(\boldsymbol{\mathcal{Y}}(\xi),\boldsymbol{\psi})\/\mathrm{d}\/\mathrm{W}(\xi),
		\end{align*}
		for every $t\geq\mathfrak{r}$ and for every $\boldsymbol{\psi}\in\mathbb{X}$.

[Definition 25 (Outgoing eikonal function and inverse foliation density) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The \emph{outgoing eikonal function} $u$ is the solution of the following fully nonlinear hyperbolic initial value problem,
where $\gfour$ is the acoustical metric defined in \eqref{E:ACOUSTICALMETRIC}
and the PDE is known as the \emph{acoustic eikonal equation}:
\begin{align} 
\begin{cases}
(\gfour^{-1})^{\alpha \beta} \partial_{\alpha} u \partial_{\beta} u = 0, 
	\\
\p_t u > 0, 
	\\
u|_{\Sigma_0} = - x^1.
\end{cases}
\end{align}
We define the \emph{outgoing inverse foliation density} $\upmu$ by:
\begin{align} 
	\upmu 
	& 
	\eqdef 
	- 
	\frac{1}{(\gfour^{-1})^{\alpha \beta} \partial_{\alpha} t \partial_{\beta} u} > 0.
\end{align}

[Proposition 46 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, suppose that $E_{+,0}$ is a regular right edge for $\Pi_0$ in the sense of Definition~\ref{def:reg_r_edge}. With high probability, $Y_0$ is $\eta_*$-regular around $\la_{1,0}$ in the sense of \cite[Definition~1]{ding2022edge} or \cite[Definition~1]{ding2022tracywidom}. More explicitly, there exist constants $c,C>0$ such that
        \begin{enumerate}[label=(\roman*)]
                \item For $z=E+\ii\eta$ with \begin{align}
                        \la_{1,0}-c\leq E\leq\la_{1,0},\qquad \eta_*+\sqrt{\eta_*\abs{\la_{1,0}-E}}\leq\eta\leq10,  
                \end{align} 
                we have
                \begin{align}
                         \Im m_{0,N}(E+\ii\eta) & \sim\sqrt{\la_{1,0}-E+\eta},  
                \end{align}
                \item For $z=E+\ii\eta$ with \begin{align}
                        \la_{1,0}\leq E\leq\la_{1,0}+c,\qquad \eta_*\leq\eta\leq10, 
                \end{align}
                we have
                \begin{align}
                         \Im m_{0,N}(E+\ii\eta) & \sim\frac{\eta}{\sqrt{E-\la_{1,0}+\eta}}. 
                \end{align}
        \end{enumerate}
       Moreover, $\la_{1,0}\sim1$ and $\|W_0\|\leq C$ with high probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm: sewing bound of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Consider $R \in C ([0, T]^2_{\leq}, \mathbb{R}^n)$ such that
		$R_{s t} = o (t - s)$. Then, for all $\eta \in (1, \infty)$,
		\begin{equation}
			\| R \|_{\eta} \leq K_{\eta} \| \delta R \|_{\eta}\,, \hspace{1.5cm} K_{\eta} :=(1 - 2^{1 - \eta})^{- 1} .

		\end{equation}

[Theorem 1 of arXiv:2511.11189, 'Sharp asymptotics for the maximal distance from the boundary to the nucleus of a typical P'] When \(t \rightarrow \infty\),
		\begin{equation}
			\PR(\D\geq t) = C_d (d\kappa_d)^d t^{d(d-1)} e^{-\kappa_d t^d} + \mathcal{O}( t^{d(d-2)} e^{-\kappa_d t^d})
		\end{equation}
		where 
		\begin{equation}
			C_d = \frac{1}{2^{d-1}\sqrt{\pi}(d-1)!} \frac{\Gamma\left(\frac{d}{2}\right)^d}{\Gamma\left(\frac{d+1}{2}\right)^{d-1}}.

		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:main theorem inversion of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d,\infty]$. Suppose that $\Phi$ is an invariant locally absolutely square-integrable random complex measure which is (beyond) $p$-uniform. Then there exists an invariant transport kernel $K$ such that $\Phi = K\lambda_d$, and such that $K$ and $\lambda_d$ satisfy the conditions of Theorem~(t:main theorem of the paper).
\begin{proof}
Such a transport kernel $K$ is explicitly constructed in Appendix~(ss:Reduction to Lebesgue of the paper). There, it is named $L$, and we also do so in this proof. As in~(equation e:L of the paper), we choose it as
\begin{equation}
    L(x,B) := \kappa_d^{-1}\Phi(B\cap(B_1+x)), \quad x\in\R^d, B\in\cB^d.
\end{equation}
By Lemma~(l: simplification to lebesgue of the paper), it is invariant and $\Phi=L\lambda_d$. It also trivially fulfills Condition~(c:condition square-integrable stealthy of the paper) with respect to $\Phi$ and any $\varepsilon>0$. To apply Theorem~(t:main theorem of the paper), it remains to analyze the components of $\Psi_q$ for $q\in\N_0$ as defined in~(equation e:Psi_q definition of the paper). Let $q\in\N_0$ and suppose that $q_1,...,q_d\in\{0,...,q\}$ such that $q_1+\dots +q_d=q$. Then,
\begin{equation*}
    \int x_1^{q_1}\cdots x_d^{q_d}\, L^\ast(y, dx) = \frac{1}{\kappa_d}\int_{B_1+y}(x_1-y_1)^{q_1}\cdots(x_d-y_d)^{q_d} \, \Phi(dx).
\end{equation*}
Therefore, for $f\in\cC_c^\infty$ the $(q_1,...,q_d)$-component $\Psi_{q;q_1,...,q_d}$ of $\Psi_q$ satisfies
\begin{align*}
    \Psi_{q;q_1,...,q_d}(f) &= \int g(y) \int x^q\, L^\ast(y, dx) \, dx\nonumber\\
    &= \frac{1}{\kappa_d}\iint_{B_1+x} f(y) (x_1-y_1)^{q_1}\cdots(x_d-y_d)^{q_d} \, dy \, \Phi(dx).
\end{align*}
The inner integral is a convolution of $f$ with a bounded function with bounded support, and therefore is in $\cC_c^\infty$ as a function of $x$. Now, an application of Theorem~(t:asymptotic variance test function of the paper) and Theorem~(t: stealthy characterization of the paper) yields that if $\Phi$ is (beyond) $p$-uniform (with some radius), then $\Psi_{q;q_1,...,q_d}$ also is, which concludes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

