[Lemma 48 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $\ccG\! \subset \! \ccF$ be a $\sigma$-field and let $(Z^{_{(n)}}_s)_{s\in \bbR_+}$, $n\ino \bbN^*$, be a sequence of $\bbR$-valued continuous processes such that $Z^{_{(n)}}_0\eqo 0$. Let $\ttb\ino (1, \infty)$ and $\gamma \ino (0, 1]$. Let us assume that for all $p\ino \bbN^*$, there exists a $\ccG$-measurable r.v.~$\mathtt C_p$ such that for all $n\ino \bbN^*$, 
\begin{equation}

\textrm{$\bP$-a.s.~} \quad \bE \big[ \big( \mathtt{Hol}_{\gamma , \, p} (Z^{_{(n)}}_{^{\,}} )\big)^\ttb  \big| \ccG\big] \leq \mathtt C_p < \infty \; .
\end{equation}  
Then conditionally given $\ccG$, the laws of the processes $(Z^{_{(n)}}_{^{\,}}\! )_{n\in \bbN^*}$ are a.s.~tight on $\bC^{0} (\bbR_+, \bbR)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 (Absolute inner shadowing) of arXiv:2609.02788, '\textbf{Quantized Einstein Metrics on \(S^7\) with \(SU(3)\)-Symmetry}'] For $s_0$ fixed sufficiently far inside the cone chart,
\begin{equation}
 \|U_{\PE}(s)-U_{\RF}(s)\|\le Cb^2e^{2s},
 \qquad s_0\le s\le s_b,
\end{equation}
uniformly for $|\mu|\le\mu_0$.

[Definition def:UT of arXiv:2608.05089, 'Correlation decay in area-tilted line ensembles'] A line ensemble $\mathbf{X}$ is uniformly tight if for any $\varepsilon > 0$ there is some $C$ such that,
for all $t \in \mathbb{R}$ we have
\begin{equation}
    \mathbb{P} \mleft[X^1(t) \geqslant C\mright] \leqslant \varepsilon.
\end{equation}

[Theorem 15 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] Let $\mathfrak{F} = \{ f \in C(\X) : |f(x)| \le 1 + \rho(x_0, x)^p \}$ with any given $x_0 \in \X$ be a family of test functions satisfying Hypothesis $\mathbf{(H_1)}$. Then the following statements are equivalent:
		\begin{itemize}
			\item [(\runum{1})] $\Phi$ admits a unique invariant measure $\mu\in\mathcal{P}(\X)$ 
            and for all $x\in\X$,
            \begin{equation*}
               \lim_{t\rightarrow\infty} W_p(P^*_t\delta_x,\mu)=0.
            \end{equation*}
			\item[(\runum{2})] $\Phi$ is eventually continuous with respect to $\mathfrak{F}$ on $\X$, and there exists $z\in\X$ such that $\Phi$ satisfies the lower bound condition \eqref{eq:LBC_P} at $z$.
            \item[(\runum{3})] There exists $z\in\X$ such that $\Phi$ is eventually continuous with respect to $\mathfrak{F}$ at $z$ and  satisfies the lower bound condition \eqref{eq:LBC_P} at $z$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

