    P_{\theta}^{*}[\mu] \coloneqq \mathfrak{D}_{e^{-\theta}}[\mu] \boxplus \mathfrak{D}_{\sqrt{1-e^{-2\theta}}}[\mathbf{s}].
\end{equation*}

