body:
[Proposition prop:loc of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Suppose (equation alphaH=3/2 of the paper), and set
    \begin{align*}
        \delta = h^{\rho\alpha} \quad \text{and} \quad
        \varepsilon= \delta^{\frac{2H+2}{3+2\alpha}}

        = h^{\rho}.
    \end{align*}
    Fix $0<t_1<t_2$. Then, there exists $K > 0$ such that for any $\rho \in (0\,,1)$, there exists $r_\rho \in (0\,,1)$ such that
    \begin{align*}
        \|\Delta^h_B u(t\,,x)\|_2^2 \le K \rho\, h^2 \log(1/h)
    \end{align*}
    uniformly for all $t \in [t_1\,,t_2]$, $x \in \mathbb{R}$ and $h \in (0\,,r_\rho]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem lrst of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] \noindent  Let $X,Y$ be $R^{2}$-valued random vectors with
densities $f_{X},f_{Y}$. If $X\leq _{\mathrm{lr}}Y$, then $X\leq _{\mathrm{st
}}Y$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 434 of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Assume that $G(t,y)=F(t)\cdot y$ for some locally bounded function $F$ on $\mathbb{R}_+$. 
 If  
 \begin{eqnarray}
   \int_0^\infty \frac{y^2}{n^2}\, \mu_n(dy) \to \sigma^2  \in (0,\infty)
 \quad \mbox{and}\quad 
 X^{(n)} \to X^* \in C(\mathbb{R}_+;\mathbb{R}_+) \mbox{ weakly in $D(\mathbb{R}_+;\mathbb{R}_+)$},
 \end{eqnarray} 
 as $n\to\infty$,   we have $Z^{(n)}  \overset{\rm f.d.d.}\longrightarrow Z^*$ with the limit process $Z^* $ given by
 \begin{eqnarray*}
 Z^*(t):= \int_0^t \int_0^{X^* (s)} F(t-s) B^* (ds,dz), \quad t\geq 0,
 \end{eqnarray*}  
 where $B^* (ds,dz)$ is Gaussian white noise with intensity $ \sigma^2\cdot ds\, dz$. (Proof in the paper; no proof environment follows the statement in the TeX.)

