[Theorem 2 of arXiv:2605.31471, 'Convergence Rates of Continuous-Time Random Walks to Time-Fractional Diffusions with Unbou'] Fix $\alpha\in\R$ and $r\in\N_0$. Let Assumptions
    \ref{asm:classical}, \ref{asm:weighted-regular}, \ref{asm:rw}, and
    \ref{asm:rw-bounded} hold, and let the walk satisfy
    Assumption~\ref{asm:rw-weighted-stability}.  Suppose also that
    Assumption~\ref{asm:classical} is valid for an order $m\ge r+5$.
    Let $F_t$ be the semigroup of \eqref{eq:SDE-flow}. Then, for every
    $f\in \cC^{r+4}_{\alpha,\infty}(\cX)$,
    \begin{equation} 
        \sup_{s\le t}
        \|U_h^{\lfloor s/h\rfloor}f-F_s f\|_{\alpha,r}
        \le
        C_{\alpha,r} e^{\mu_{\alpha,r}t}h
        \|f\|_{\alpha,r+4}.
    \end{equation}
    For the killed semigroups, if $c\ge0$, then
    \begin{equation} 
        \sup_{s\le t}
        \|e^{-c\lfloor s/h\rfloor h}U_h^{\lfloor s/h\rfloor}f-e^{-cs}F_s f\|_{\alpha,r}
        \le
        C'_{\alpha,r}e^{(\mu_{\alpha,r}-c)t}h
        \|f\|_{\alpha,r+4}.
    \end{equation}
    The estimate holds for all sufficiently small $h>0$.  The constants
    depend on $\alpha,r,K_{\alpha,r},d,R_\xi$, and the moment constants in
    Assumption~\ref{asm:rw}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:DP of arXiv:2510.13572, 'Coalescence in Markov chains'] \mbox{\hfil}
\begin{letlist}

\item 
$\mathcal{P}(\mathcal{G})=\mathcal{D}_S$ if and only if $\mathcal{G}= \mathcal{F}^{\text{\rm perm}}_S$.  
\item 
$\mathcal{P}(\mathcal{G})=\mathcal{P}_S$ if and only if $\mathcal{G}= \mathcal{F}_S$.

\end{letlist}

[Defn Def: general polynomial process of arXiv:2605.16921, '${\ASL_n}(\mathbb Z)$ invariant random subsets of $\mathbb Z^n$'] With the data $(k, m, T, \pi, s)$ as above, let $\nu$ be a the Haar probability measure on a closed subgroup of  $T_{\leq k}[X_1, \ldots, X_d]$ stable under  $P \mapsto \alpha(\gamma, x)(P) \circ \gamma^{-1}$  for every $\gamma \in \SL_d(\mathbb{Z})$, and let $f: T \to [0, 1]$ be measurable and invariant under the range of $\alpha$. The associated \emph{polynomial point process} on $\mathbb{Z}^d$ is obtained as follows:
    \begin{itemize}
        \item draw a random polynomial $\underline{P}$ according to $\nu$;
        \item independently across $t \in \mathbb{Z}^d$, keep $t$ with probability $f(\underline{P}(t))$.
    \end{itemize}

[Proposition pro3.1 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
For any given $(y(\cdot), z(\cdot,\cdot))$ and for almost all $t\in[0,T]$,
if the following mean-field BSDE
\begin{equation}
{\cal Y}(t,s)=\psi(t)+\int_s^Tg(t,r,y(r),{\cal Z}(t,r),\mathbb{P}_{y(r)}, \mathbb{P}_{{\cal Z}(t,r)})dr-\int_s^T{\cal Z}(t,r)dW(r),\quad s\in[t,T]
\end{equation}
admits a unique solution, denoted by $({\cal Y}(t,\cdot),{\cal Z}(t,\cdot))$,
then the following mean-field BSVIE
\begin{equation}
Y(t)=\psi(t)+\int_t^Tg(t,s,y(s),Z(t,s),\mathbb{P}_{y(s)}, \mathbb{P}_{Z(t,s)})ds-\int_t^TZ(t,s)dW(s), \quad  t\in[0,T]
\end{equation}
also admits a unique solution $(Y(\cdot),Z(\cdot,\cdot))$.
Moreover,
\begin{align*}
  Y(t) = \mathcal{Y}(t,t)\quad  \text{and}\quad Z(t,s) = \mathcal{Z}(t,s)\quad  \text{for}\ (t,s) \in \Delta[0,T].
\end{align*}

[Dfntn 14 of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] We define
    \begin{align*}
        \mathcal{S}_\mathcal{C} := 
        \Span{\{ \varphi_i^{(  k)}   e_i: i\in\{1,\ldots,d\},\;   k\in\N_0^d \}},
    \end{align*}
    where, for $i\in\{1,\ldots,d\}$ and $  k = (k_1,\ldots,k_d)^\top\in \N_0^d$,
    \begin{align*}
        \varphi_i^{(  k)}:\Omega\rightarrow \R,\qquad \varphi_i^{(  k)}(x_1,\ldots,x_d) := \cos(\pi k_i x_i) \prod_{\substack{1\leq j \leq d \\ j\neq i}} \sin(\pi k_j x_j),
    \end{align*}
    and $  e_i$ denotes the $i$-th column of the identity matrix in $\R^{d\times d}$.

[Proposition 26 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $\mu>0$ and $\gamma\in(0,2-\frac{d}{2})$. We have
\begin{equation}
\|(\CH^\sharp+\Delta)v^\sharp\|_{H^{\gamma}(\IR^d)}\lesssim\|v^\sharp\|_{H^{\frac{d}{2}+\gamma+\kappa}(\IR^d)\cap L_\mu^2(\IR^d)}
\end{equation}
for any $\kappa>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 64 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] We have, for every $t \in [0,T]$,  
\begin{equation}
\langle M_t, \bv \rangle=L_t^{\bv}, \;\; \forall \bv \in \nU.
  \end{equation}

[Lemma 9 (Graph-rate separation) of arXiv:2609.03466, 'Least-Favorable Location for Binomial Top-$t$ Selection'] \emph{Center classification and wedge-scale separation.} At $p=\pc$:
\begin{enumerate}[label=(\alph*)]
\item a one-edge component has rate $\Jn$;
\item a two-edge connected component has rate $\Kn$;
\item a matching of two edges has rate $2\Jn>\Kn$;
\item every connected component containing at least three edges has rate strictly larger than $\Kn$.
\end{enumerate}
Consequently, for fixed $k,t,\delta$, there is a neighborhood $U$ of $\pc$ and a number $\eta>0$ such that every inclusion--exclusion term in $\mathcal R_n$ has probability at most
\begin{equation}
 C(n+1)^ke^{-n(\Kn+2\eta)},
 \qquad p\in U.

\end{equation}
Its first two derivatives with respect to $p$ are $O(e^{-n(\Kn+\eta)})$, uniformly on $U$. Therefore
\begin{equation}
 \|\mathcal R_n\|_{C^2(U)}=O(e^{-n(\Kn+\eta)}).

\end{equation}

\emph{Local edge-dominance separation.} After shrinking $U$ if necessary, there is also $\gamma>0$ such that every connected two-edge graph and every other non-single-edge graph occurring in \eqref{eq:exact-graph-decomp} satisfies
\begin{equation*}
 \mathcal I_p(G)\ge I_1(p)+\gamma,
 \qquad p\in U.
\end{equation*}
For $j=0,1,2$, the $j$th derivative of the sum of all such terms is bounded by
\begin{equation*}
 C_j n^{C_j}e^{-n(I_1(p)+\gamma)},
 \qquad p\in U.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:restvk of arXiv:2412.09145, 'Asymptotic expansions for normal deviations of random walks conditioned to stay positive'] For every tuple $(j,q,s,\nu,\mu)$ satisfying $s+\nu+2\mu \le r+3$, $q\le 2j$ there exist polynomials $H_\eta$ of degree $\eta$, 
$\eta\le\lfloor \frac{r+3}{2} \rfloor$ such that 
\begin{multline*}
    z^{q-s+\nu}
    \sum_{k=2}^{n-1}
        \frac{
        v_k^{(s+\nu+2\mu)}
        e^{-\frac{z^2}{2(n-k)}}
        }
        {
        (n-k)^{j+\nu+\mu+1/2}
        }
=
    \frac{z^{q-s+\nu}}{n^{j+\nu+\mu+1/2}}
    e^{-\frac{z^2}{2n}}
    \sum_{\eta=0}^{\lfloor \frac{r+3}{2} \rfloor}
        \frac{H_\eta(z^2/n)}{n^{\eta}}
\\
+
    O\left(\frac{1}{(\min(\sqrt{n},1+|z|))^{r+2}}\right).
\end{multline*}

