\[
\Omega_{n,K}:=\ccbb{\sif \ell1\inddd{N_\ell(n)>j_n}\le K\log n \quad\mbox{ and }\quad \sup_{\ell\in{\mathbb N}}N_\ell(n)\le Kn}.
\]
Note that, 
\begin{equation}
\lim_{n\to\infty}\mathbb P(\Omega_{n,K}) = 1.
\end{equation}
Indeed, recalling that $N(n) = \sif\ell 1N_\ell(n)$ is a  Poisson random variable with parameter $n$, we have
\begin{align*}
