[Corollary coro:fubini of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $X=(X_t)_{t\in[0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$. Assume that $b_j,a_{ij}\in\mathcal O(S)$ and $K$ is a kernel with holomorphic jump size. Suppose that for some $\varepsilon>0$ the following conditions hold true.
        \begin{enumerate}
            \item for all $|\beta|\geq2$ and $z\in P^d_{R(S)+\varepsilon}(0)$, $\int_E|\underline{\bm{j}}( y)^{\ast \beta}|_z \ F(d y)<\infty$;
            \item the map $ \int_{\|j(\cdot, y)\|>1}\exp(|j_{ \varepsilon,1}(\cdot, y)|+\dots+|j_{ \varepsilon,d}(\cdot, y)|) \ F(d y)$ is locally bounded on $P^d_{R(S)+\varepsilon}(0)$.
        \end{enumerate}
        Let $\mathcal{V}$ and $\mathcal{V}^*$ be defined as in equation (equation eq:Vgeneralkernel of the paper). 
        Then, $K\in \mathcal O(S)$ and $X$ is an $S$-valued $\mathcal{V}$-holomorphic process. Moreover, for all $\mathbf{u}\in\mathcal{V}^*$,  $\mathcal{A}h_\mathbf{u}={h_{L(\mathbf{u})}}|_S$, where $L:\mathcal{V}^*\rightarrow \mathcal{S}^*$ is the operator introduced in equation (equation eq:Lgeneralkernel of the paper), and for all $|\beta|\geq2$, 
        \begin{align}
    \mathbf{m}^\beta=\bm{\lambda} \ast \int_E\underline{\bm{j}}( y)^{\ast \beta}\ F(d y).
        \end{align}

