[Lemma 14 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let $\gamma \in (0,1)$ and Assumptions \ref{ass:K} and \ref{ass:F} hold. Let $g\in\shc^\gamma$ and $f\in \shc^\gamma\cap L^1$. Then we have 
\begin{equation}
\|gF(K*f)\|_{\shc^\gamma}\leq \|g\|_{\shc^\gamma}C_{F,K}(1+\|f\|_{L^1}).
\end{equation}

[Proposition 14 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] Let  us consider $\phi, \tilde{\phi} : \bR^d \rightarrow \bR^{d'}\times \bR^{d'\times d} $. Then we have
\begin{enumerate}
    \item  $$\norm{P\phi - P\tilde{\phi} }_{\infty} \leqslant \norm{\phi -\tilde{\phi}}_{\infty}\,.$$
    \item  {If $\phi\in C^2(\bR^d,\bR^{d'}\times \bR^{d'\times d})$ such that $\norm{\nabla^2 \phi(x)} \leqslant C(1+|x|^{r'})$ for all $x \in \bR^d$. Then there exists $C\geqslant 0$ that does not depend on $\Pi$ such that
    $$\norm{\frac{P\phi-\phi}{\rho_{r'}}}_{\infty,\Box} := \sup_{x \in \Box}\norm{\frac{P\phi(x)-\phi(x)}{\rho_{r'}(x)}}\leqslant C\delta^2(1+\delta^{r'}).$$}

    \item 
    \begin{equation}

        \norm{P\phi(x)} \leqslant P\rho_{r'} (x)\sup_{z \in \Pi}\norm{\frac{\phi(z)}{\rho_{r'} (z)}},\quad\forall x \in \bR^d.
    \end{equation}
    \item  If $r' \geqslant 2$, there exists $C$ that does not depend on $\Pi$ such that
    \begin{equation}

        \sup_{x \in \bR^d} \left| \frac{P \rho_{r'}(x)}{\rho_{r'}(x)}\right| \leqslant 
        {1+C\delta^2(1+\delta^{r'})}.

    \end{equation}

\end{enumerate}

