[Prop eq:OP_BSig of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For $\mu > - \frac12$, ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2}$ with $k_j > -1$, $1 \le j \le d_2$, define 
\begin{equation} 
 \bm Q_{\bm j, \bm k, m}^n(\bm x,\bm y) = \hat {\bm L}_{\bm j, n-m}^{({\boldsymbol{\kappa}}, \alpha+2m)}(\bm y) |\bm y|^m 
      \bm B_{\bm k, m}^\mu \left(\frac{\bm x}{|\bm y|}\right),
\end{equation}
where $\alpha = 2 \mu + d_1-1$. Then
$\{\bm Q_{\bm j, \bm k, m}^n: |\bm k| = m, \, |\bm j| = n-m, \, \bm k \in {\mathbb N}_0^{d_1}, \, \bm j \in {\mathbb N}_0^{d_2}, 0\le m \le n\}$ 
is an orthogonal basis of ${\mathcal V}_n\big({\mathbb B}^{d_1}\!\! \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{\mu, {\boldsymbol{\kappa}}}^{{\mathbb B}\rtimes \Sigma}\big)$. 
Moreover, the norm square of $\bm Q_{\bm j, \bm k, m}^n$ is given by 
\begin{equation} 
   \bm h_{\bm j, \bm k, m}^{n; \mu,{\boldsymbol{\kappa}}}  

       =  (2\mu+d_1)_{2m} \bm h_{\bm k,m}^{\mu, {\mathbb B}}  
       \bm h_{\bm j,m}^{({\boldsymbol{\kappa}}, {\alpha}+2m), \triangle}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:convergegeneral of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi$ be the discrete uniform distribution, $P \in \mathcal{S}(\pi)$ and $Q \in \mathcal{Q}$ be a permutation matrix. Let $\Pi$ be the matrix where each row equals to $\pi$. We have
	\begin{itemize}
		\item(One-step contraction measured by $D^{\pi}_{KL}$) \begin{align*}
			D^{\pi}_{KL}(P \| \Pi) &= D^{\pi}_{KL}(P Q \| \Pi) = D^{\pi}_{KL}(Q P \| \Pi) = D^{\pi}_{KL}(Q P Q\| \Pi).
		\end{align*}

		\item(KL-divergence Dobrushin coefficient)
		\begin{align*}
			c_{KL}(P) = c_{KL}(PQ) = c_{KL}(QP) = c_{KL}(QPQ).
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Assumption \Unif\, of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] We say that $\mathcal{S}$ satisfies the assumption ${\mbox{\textsc{Unif(}$\delta$\textsc{)}}}\,={\mbox{\textsc{Unif(}$\delta,r_0,\theta_0$\textsc{)}}}\ $ for some parameters $\delta,r_0,\theta_0$ if all edge-lengths in $\mathcal{S}$ are comparable to $\delta$, meaning that for any  neighbouring $v^{\bullet}\in G^\bullet$ and $v^{\circ}\in G^\circ$ one has
	\begin{equation}
		r_0^{-1}\cdot \delta \leq  |\mathcal{S}(v^{\bullet})- \mathcal{S}(v^{\circ})| \leq r_0\cdot \delta,
	\end{equation}
and all the geometric angles in the quads $\mathcal{S}$ are bounded from below by $\theta_0$.

[Lemma seq of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] If $z=z_1-\epsilon$ for some suitable $\epsilon$ (say less or equal to $\frac{\mu_{n,N}}{2\kappa_{N}}$), then there exists a sequence $s_N$ with finite limit such that
    \begin{equation}
    \zeta^{\frac{3}{2}}(z)=\frac{\sqrt{\epsilon^3(z_{2}-z_{1})}}{2z_{1}}\left(1+\frac{3}{5}s_{N}\epsilon+O(\epsilon^2)\right)
\end{equation}
and hence,
\begin{equation}
   \kappa_{N}^{\frac{2}{3}}\zeta(z)=\frac{\epsilon\kappa_{N}}{\sigma_{n,N}}\left(1+\frac{2\epsilon s_{N}}{5}+O(\epsilon^2)\right),
\end{equation}
\begin{equation}
    \left(\frac{\kappa_{N}}{\sigma^3_{n,N}}\right)^{\frac{1}{6}}\tilde{f}^{-\frac{1}{4}}(z)=1-\frac{2}{5} s_{N}\epsilon+O(\epsilon^2).
\end{equation}
Here $z_1$, $z_2$, $\kappa$ and $s$ are all double-indexed sequences with respect to $(j,k)\in\mathbb{N}^2$. We will abbreviate them as in this lemma if $(j,k)=(n,N)$. Moreover, the L--G transform $\zeta$ and induced $\tilde{f}$ is always assumed to be around $z_1$ (with parameter $(n,N)$ here).

