[Lemma N+1s-NE-PIT of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $t \in \mathop  \cap \limits_{j = 0}^q \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, the combination
\begin{equation*}
\left( {{u_{q,n + 1}},{v_{q,n + 1}},{\mathfrak{p}_{q,n + 1}},{\mathring{R}_{q,n + 1}},{S_{q,n + 1}},{\mathfrak{P}_{q + 1,n + 1}}} \right)
\end{equation*}
fulfills the $\left( {n + 1} \right)$-step Newton--Euler--Reynolds system
\begin{equation*}
\left\{ {\begin{array}{*{20}{l}}
{\partial _t}{v_{q,n + 1}} + \mathrm{div} \left( {{u_{q,n + 1}} \otimes {u_{q,n + 1}}} \right) + \nabla {\mathfrak{p}_{q,n + 1}} = \mathrm{div} \left( {{\mathring{R}_{q,n + 1}} + {S_{q,n + 1}} + {\mathfrak{P}_{q + 1,n + 1}}} \right),\\
{u_{q,n + 1}} = {v_{q,n + 1}} + \mathfrak{W}_q,\\
\mathrm{div}\,   {u_{q,n + 1}} = 0 .
\end{array}} \right.  
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm-OR01 of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] For $Z\in\mathcal X$ and $n\in\mathbb{N}$, we have
\begin{align*}
\lim_{\eta\to\infty}\left\{\eta-\left(\mathbb{E}[(\eta-Z)_+^n]\right)^{1/n}\right\}=\mathbb{E}[Z].
\end{align*}
As a result, for $X,Y\in\mathcal X$ and $n\in\mathbb{N}$,
$X\ge_n Y$ implies $\mathbb{E}[X]\ge \mathbb{E}[Y]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem dimhatleastconjecture of arXiv:2506.10448, 'Hitting probabilities and the Ekstr\"om--Persson conjecture'] For every $\mu \in \mathcal{P}(\mathbb{R}^d)$ {and} for every $\alpha>0$, one has 
\begin{equation}
\overline{F}_{\mu}\Bigl(\frac 1\alpha\Bigr) \leq f_{\mu}(\alpha)\leq \min\Bigl\{
  \frac{1}{\alpha}, \overline{H}_{\mu}\Bigl(\frac 1\alpha\Bigr)\Bigr\},
\end{equation}
and the above bounds are optimal. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Sampling Theorem) of arXiv:2609.03418, 'Sampling and Density Theorems for the Fractional Opdam--Cherednik Transform'] Let $ f\in PW^\theta_{\alpha,\beta}.$
Then
\begin{align}
f(\lambda) = f(0)S_0^\theta(\lambda) + \sum_{j\in\mathbb Z\setminus\{0\}} f(s_j)S_j^\theta(\lambda),
\end{align}
where
\begin{align}
S_0^\theta(\lambda) = e^{-\frac i2\lambda^2\cot\theta} \frac{ \Psi_{\alpha,\beta}(\lambda\csc\theta) }{ \Psi_{\alpha,\beta}(0) }, 
\end{align}
and, for $j\ne0$,
\begin{align}
S_j^\theta(\lambda) = e^{-\frac i2(\lambda^2-s_j^2)\cot\theta} \frac{ \lambda\sin\theta }{ s_j(\lambda-s_j) } \frac{ \Psi_{\alpha,\beta}(\lambda\csc\theta) }{ \Psi_{\alpha,\beta}'(\mu_j) }, \quad \mu_j=s_j\csc\theta. 
\end{align}
The value at $\lambda=s_j$ in \eqref{Sec4_Eqn18} is understood by continuity. The interpolation functions satisfy
\begin{align}
S_j^\theta(s_k)=\delta_{jk}, \quad j,k\in\mathbb Z.
\end{align}
The series in \eqref{Sec4_Eqn16} converges in the $PW^\theta_{\alpha,\beta}$-norm and uniformly on compact subsets of $\mathbb R$.

